window.POEM_DB=window.POEM_DB||{};POEM_DB["ming_014"]={"n":"袁宏道","dyn":"明","poems":[{"t":"大堤女","f":"七言绝句","c":["文窗斜对木香篱，胡粉薄施细作眉。","贪向墙头看车马，不知裙著刺花儿。"]},{"t":"江上见数渔舟为公卒所窘 其一","f":"五言绝句","c":["钓竿拂晓霜，衣薄芦花絮。","一亩不籍官，也被官差去。"]},{"t":"竹枝词 其二","f":"七言绝句","c":["雪里山茶取次红。","白头孀妇哭春风。","自从貂虎横行后，十室金钱九室空。"]},{"t":"桃花雨","f":"七言绝句","c":["浅碧深红大半残，恶风催雨剪刀寒。","桃花不比杭州女，洗却胭脂不耐看。"]},{"t":"文殊台","f":"七言古诗","c":["芙蓉万尺花如铁，秋窗昼洒红霞屑。","螺顶仙人骑杖来，天衣晓带雪山雪。","帝遣神丁量海洗，绣锷斑棱生平砥。","一萍吹作浔阳城，半七疏为九江水。","高青直上一万重，绿瞳笑启金泥封。","烟重云骨不可去，怒鞭白雀恼张公。"]},{"t":"西陵桥","f":"古风","c":["西陵桥，水长在。","松叶细如针，不肯结罗带。","莺如衫，燕如钗。","油壁车，斫为柴。","青骢马，自西来。","昨日树头花，今朝陌上土。","恨血与啼魂，一半逐风雨。"]},{"t":"显灵宫集诸公以城市山林为韵 其二","f":"七言古诗","c":["野花遮眼酒沾涕，塞耳愁听新朝事。","邸报束作一筐灰，朝衣典与栽花市。","新诗日日千馀言，诗中无一忧民字。","旁人道我真聩聩，口不能荅指山翠。","自从老杜得诗名，忧君爱国成儿戏。","言既无庸嘿不可，阮家那得不沉醉。","眼底浓浓一杯春，恸于洛阳年少泪。"]},{"t":"闻省城急报","f":"七言古诗","c":["黄鹄矶头红染泪，手杀都堂如儿戏。","飞鞚叠骑尘碾尘，报书一夕三回至。","天子圣明臣敛手，胸臆决尽天下事。","二百年来好纪纲，辰裂星纷委平地。","天长阍永叫不闻，健马那堪持朽辔。","书生痛哭倚蒿篱，有钱难买青山翠。"]},{"t":"擢歌行","f":"五言古诗","c":["妾家白蘋洲，随风作乡土。","弄篙如弄针，不曾拈一缕。","四月鱼苗风，随君到巴东。","十月洗河水，送君发杨子。","杨子波势恶，无风浪亦作。","江深得鱼难，鸬鹚充糕臛。","生子若凫雏，穿江复入湖。","长时剪荷叶，与儿作衣襦。"]},{"t":"横塘渡","f":"古风","c":["横塘渡，临水步。","郎西来，妾东去。","妾非倡家人，红楼大姓妇。","吹花误唾郎，感郎千金顾。","妾家住虹桥，朱门十字路。","认取辛夷花，莫过杨梅树。"]},{"t":"古荆篇","f":"古风","c":["年年三月飞桃花，楚王宫里斗繁华。","云连蜀道三千里，柳拂江堤十万家。","丹楼绣幌巢飞燕，青阁文窗起睡鸦。","鸦归燕语等閒度，不记江城春早暮。","东风香吐合欢花，落日乌啼相思树。","王孙挟弹郢门西，少年借客章台路。","少年矫矫名都儿，雕鞍朱勒黄金羁。","采桑陌上青丝笼，红粉楼中白纻辞。","白纻绿水为君起，青春环佩如流水。","东城丝管接西城，相府豪华压朱邸。","侠客飞鹰古道傍，佳人卖笑垂杨里。","垂杨二月隐朱楼，家家宴喜楼上头。","綦舄喧阗朝送酒，管弦嘈杂夜藏钩。","繁弦急管夜初阑，惜花少女怨春残。","桃花滟滟歌成血，兰炷漫漫火送寒。","晓风杨柳菖蒲浦，秋月梧桐金井栏。","秋月春花无断绝，门前郁李九回折。","愿作阳台雨后云，谁怜洛水风中雪。","阳台洛水梦空长，那似倡家玳瑁床。","选得东家佳姝妹，却延西第好儿郎。","织成锦席迷蝴蝶，种得青梧栖凤凰。","游人恋恋无穷已，踏遍江城春万里。","只解宾从集似云，那惜年光去如矢。","花开花落迥生愁，郢树鄢云几度秋。","霍氏功名成梦寐，梁王台馆空山丘。","荣枯翻复竟何言，昨宵弱水今昆崙。","无人更哭西州路，有雀还登翟氏门。","汉恩何浅天何薄，百年冠带坐萧索。","昔时嘘气成烟云，今朝失势委泥砾。","青娥皓齿嫁何人，金床玉几为谁作。","已矣哉，归去来。","楚国非无宝，荆山空有哀。","君看《白雪》、《阳春》调，千载还推作赋才。"]},{"t":"拟作内词 其一","f":"七言绝句","c":["玉殿莲筹夜未央，内人传旨出昭阳。","朝来刚赴西宫约，莫遣经筵进讲章。"]},{"t":"拟作内词 其二","f":"七言绝句","c":["宜春苑里日初斜，三百妖童校丽华。","韎韐戎衣朱鬣马，不知若个是官家。"]},{"t":"拟作内词 其三","f":"七言绝句","c":["百子池头九子萍，美人双照月棱青。","宫槐叶绿春如水，诵得《莲花》两卷经。"]},{"t":"拟作内词 其四","f":"七言绝句","c":["阿监当头送好音，羊车行处载鸾衾。","朝来领取铺宫例，御帕亲封少府金。"]},{"t":"拟作内词 其五","f":"七言绝句","c":["彩仗龙旌拂曙轻，朝朝东阁坐先生。","皂囊久积言官奏，分付金珰取次行。"]},{"t":"拟作内词 其七","f":"七言绝句","c":["金衣滑滑搅春眠，白发中官进简编。","天子自临宣示帖，美人亲碾校书笺。"]},{"t":"拟作内词 其八","f":"七言绝句","c":["一般春色有枯荣，十树樱桃九树生。","拾得青梅如弹子，护花铃下打流莺。"]},{"t":"伤周生","f":"七言律诗","c":["溪头曾见浣春纱，珠箔于今天一涯。","紫陌重邀千宝骑，青楼无复七香车。","美人南国空湘水，处子东邻是宋家。","记得西廊香阁里，瓶花长插一枝斜。"]},{"t":"客有赠余宫烛者即席同刘元定方子公丘长孺陶孝若赋之","f":"七言古诗","c":["刻凤含鱼吐春燄，只拟蓬莱天上见。","绿绨方底散青烟，一朝别却宫云面。","不照明珰翠步摇，书帷自剪读《离骚》。","捍拨春雷罢不闻，细雨珠花滴小槽。","韩家灯檠夜相伴，离离朱粉烟黄卷。","瓦瓶石臼竹方床，上有罗文折角砚。","莫道不如宫里时，高斋守尽兰心茜。","邯郸才人嫁厮养，犹胜闭置閒宫殿。","柏梁宴罢霞成堆，昆明池底夜珠来。","红膏自膻不得近，阿监但扫沉香灰。","汗花凝滴雪珠腻，蜀葵粉湿青虫醉。","一石酒尽尚留髡，扇婢瓮儿烂熳睡。","烛龙传语九微光，输尽婪杯老閒吏。"]},{"t":"紫骝马","f":"古风","c":["紫骝马，行且嘶。","愿为分背交颈之逸足，不愿为追风绝景之霜蹄。","霜蹄灭没边城道，朔风一夜霜花老。","纵使踏破天山云，谁似华阴一寸草。","紫骝马，听我歌。","壮心耗不尽，奈尔四蹄何。"]},{"t":"郊外水亭小集 其一","f":"七言律诗","c":["山自萧森涧自寒，却怜胜地在长安。","桐阴恰好当窗覆，柳色终宜近水看。","已倦呼儿犹问酒，不情逢客强加冠。","湘江亦有幽居处，多少芙蓉忆钓竿。"]},{"t":"郊外水亭小集 其二","f":"七言律诗","c":["幽篁戛戛坐来清，懒慢都无对客情。","戏水鸥雏分浪出，趁巢乌母曳枝行。","堂前羯鼓人三爵，花下弹棋鸟一声。","红药青轩如梦里，几年尘傍马头生。"]},{"t":"郊外水亭小集 其三","f":"七言律诗","c":["清歌袅袅两妖童，尼酒题诗兴转工。","拾翠女来虚槛外，分蔬人立小畦中。","落花扑面都如雪，密树宜亭不碍风。","怪得夜来乡梦好，穿云直入武陵东。"]},{"t":"秋闺","f":"五言律诗","c":["秋色透罗帏，寒芳片片飞。","蛩吟生暗壁，萤火度空机。","闺月流新照，帘霜换故衣。","征鸿与荡子，同去不同归。"]},{"t":"别王百谷","f":"七言律诗","c":["河上青霜雁字斜，西风匹马又天涯。","锦帆径绕郎官舍，冠子桥通处士家。","好事每挥林下麈，清斋长试谷前茶。","东邻不是无姝子，眼底何人解浣纱。"]},{"t":"虎丘 其一","f":"五言绝句","c":["一片千人石，瑩晶若有神。","剑光销不尽，留与醉花人。"]},{"t":"春江引","f":"古风","c":["溪潋潋，草茙茙，野桃露滴珊瑚红。","花气晓腥鱼子浪，柳枝晴扇麦苗风。","美人罗袖扑香蕊，科斗旋旋丁子尾。","百舌欲止复冲人，一声滴溜芳蹊里。"]},{"t":"皇甫仲璋邀饮惠山上 其一","f":"七言律诗","c":["东风吹水浴平沙，鸂鶒鸬鹚满钓槎。","去日翟公犹有客，到来潘岳已无花。","溪鳞呷雨层层浪，水碓舂云处处家。","白石青松如画里，临流乞得惠泉茶。"]},{"t":"和萃芳馆主人鲁印山韵 其二","f":"七言律诗","c":["爱看幽鸟曝新阳，每遇嘉阴即倒觞。","尽日竹烟消酒去，有时莺语入帘长。","春塘雨过波纹乱，花坞风回蝶翅香。","行到碧桥深柳处，一帆凉月满吴航。"]},{"t":"小妇别诗 其二","f":"七言绝句","c":["弱柳轻帆快送人，巫山原是女儿神。","愿随泼火清明雨，洗却钱塘十里尘。"]},{"t":"广陵别景升小修","f":"七言律诗","c":["搔头几日见新丝，二月河桥上马时。","长短官街惊梦鼓，高低杨柳罥肠枝。","江烟一担充行李，流水三叉各路岐。","北地南天千万里，青巾白帢几人知。"]},{"t":"淮安舟中 其一","f":"五言律诗","c":["别思抽如绪，酲酲也不休。","触篷风自语，砑橹浪相揉。","野钓空舟侧，荒窑古渡头。","微官真可笑，谚语拾姜猴。"]},{"t":"淮安舟中 其三","f":"五言律诗","c":["空郊不可行，积砾与蒿平。","菌耳悬枯木，烧痕入古城。","按图知旧垒，认柳识邮程。","一望淮阴墓，今人百感生。"]},{"t":"淮阴侯祠","f":"七言古诗","c":["秋郊兔尽韩卢窘，三尺青蛇捲锋颖。","到手山河掷与人，却向雌鸡纳腰领。","英雄桎足归罗网，辩士舌端空来往。","本将衣饭畜王孙，未许肝肠敌亭长。","一局残棋了项秦，五湖西子白纶巾。","贪他一颗真王印，卖却淮阴跨下人。"]},{"t":"经下邳","f":"七言绝句","c":["诸儒坑尽一身馀，始觉秦家网目疏。","枉把六经灰火底，桥边犹有未烧书。"]},{"t":"饮马长城窟行","f":"五言古诗","c":["长城水呜咽，夜夜作秦语。","问子何代人，防胡旧军旅。","冤魄滞孤魂，不得归乡土。","白水洗白骨，瘢尽水酸楚。","洗多成黑流，水性毒于蛊。","立马古战场，长嘶待天雨。"]},{"t":"长安有狭斜行","f":"古风","c":["按金驹，立长沟。","枇杷落尽茱萸秋。","山西女儿帕勒头。","面上堆粉鬓堆油。","二十五弦弹箜篌。","猩红衫子葡萄紬。","笑问南装如此不。"]},{"t":"妾薄命","f":"五言古诗","c":["落花去故条，尚有根可依。","妇人失夫心，含情欲告谁。","灯光不到明，宠极心还变。","只此双蛾眉，供得几回盻。","看多自成故，未必真衰老。","辟彼数开花，不若初生草。","织发为君衣，君看不如纸。","割腹为君餐，君咽不如水。","旧人百宛顺，不若新人骂。","死若可回君，待君以长夜。"]},{"t":"相逢行","f":"五言古诗","c":["行行即曲巷，曲巷多蒿草。","窗路掠蛛丝，读书岁月老。","壁上荣启图，手里黄石编。","当尽三时衣，不直数缗钱。","儿女无裈著，常时煨故纸。","税地植桃花，十树九树死。","君莫悲腐草，腐草发光耀。","玄霜畏冬青，白发傲年少。"]},{"t":"悲哉行","f":"古风","c":["石马立荆棘，荒城叫老狸。","昔时冠带人，唯有鹤来?。","宿志慕长生，朋党尽刺讥。","父母不我容，碧海三山飞。","朝牧老君龙，莫守刘安鸡。","仙家岁月长，桃子三垂枝。","?来见荒冢，半是孙曾碑。","城池百易主，族里无从知。","古人悲夜绣，今我亦似之。","白骨不可语，鹤归空尔为。"]},{"t":"门有车马客行","f":"五言古诗","c":["门有车马客，锦襕乌纱巾。","寒毛接短鬓，丝丝沙与尘。","问子何劳劳，上书西入秦。","八年始一命，官卑不救贫。","冒霜揖槐柳，望灰拜车轮。","一身百纠縳，形如一束薪。","手缠不自解，利刃寄他人。","蔗与蘖同餐，虽甘亦苦辛。"]},{"t":"京洛篇","f":"五言古诗","c":["煌煌京洛城，朱衣喧广道。","白首贱书生，驴輚挂诗草。","怀刺谒恩门，门卒相轻眇。","十上十不达，登街颜色槁。","叠身事贵公，习谀苦不早。","罩眼一寸纱，茫茫遮人老。"]},{"t":"虾䱉行","f":"五言古诗","c":["虾䱉出潢潦，道逢东海使。","鱼服而介身，呷浪以相戏。","物微恐见侵，跳波争努臂。","东陂招能兄，西溪唤螺弟。","水虫万馀种，各各条兵议。","聚族鼓鳞鬣，不能当一嚏。"]},{"t":"升天行","f":"古风","c":["乘赤雾，鞭鸾辙。","路逢王子晋，玉箫已吹折。","织女弄机丝，馀纬烂霄阙。","下土虮虱民，误唤作雌霓。","张翁老且耄，举止多媟亵。","侍仙三万年，不曾见隆准。","真人多窜左，天狐惨馀孽。","羲御失长鞭，牵牛叹河竭。"]},{"t":"青县赠潘茂硕","f":"五言律诗","c":["竹叶遮人吏，公移只坐销。","印床生木耳，廨舍长蔬苗。","贫邑多诗料，閒官有醉僚。","一城不数武，客得几科条。"]},{"t":"梨花初月夜","f":"七言绝句","c":["梨花疏点贴窗流，斜月笙箫处处楼。","醉里不知花是影，隔纱惊唤小扬州。"]},{"t":"天坛 其一","f":"七言绝句","c":["空坛深净驳琉璃，秃发簪冠老导师。","铜呇金涂秋草里，如今不似世宗时。"]},{"t":"天坛 其二","f":"七言绝句","c":["碧翁难道是无情，分合千年议不成。","不得宁居天亦苦，古来多事是书生。"]},{"t":"天坛 其四","f":"七言绝句","c":["仙苑桃花朵朵香，曾于天上看霓裳。","刘郎老去风情减，閒把音容问太常。"]},{"t":"昌平道中","f":"七言绝句","c":["庵前乞得老僧茶，一派垂杨十里沙。","乌笼白檐凭拣取，麝香李子枕头瓜。"]},{"t":"得舍弟徐州书 其二","f":"七言绝句","c":["佳人生死不知闻，辜负梨花一面云。","昨日宫罗新裁剪，为伊留得半拖裙。"]},{"t":"刘常侍水轩 其三","f":"古风","c":["竹药崩沙岸，槐根出钓矶。","卷帘山放入，打果雀惊飞。","护乐添新幕，抛毬换短衣。","倦来观洗马，?络尽珠玑。"]},{"t":"戊戌初度 其二","f":"七言律诗","c":["禅灯滟滟雪玻璃，贝典将来戒小妻。","客里羁情笼野鸽，乡中春梦阅山鸡。","灰心竟日疏《庄子》，弹舌清晨诵准提。","无限长林无限羽，一枝那复计高低。"]},{"t":"戊戌初度 其三","f":"七言律诗","c":["閒居心似夹冰鱼，雪里轮蹄亦自疏。","研酒和来香泛帖，瓶花吹落湿沾书。","艰深乍觉诗如谶，消散方知道是虚。","一卷杂华诵未了，被人邀得过僧庐。"]},{"t":"罗隐南王章甫小集斋中说旧事偶成 其一","f":"七言绝句","c":["汉江秋净石粼粼，黄鹤楼高不见尘。","今日楼台归劫火，眼中犹聚上楼人。"]},{"t":"罗隐南王章甫小集斋中说旧事偶成 其二","f":"七言绝句","c":["万瓦如鳞绣作堆，别山重见秃翁来。","晴川阁下南条水，一日同君荡几回。"]},{"t":"罗隐南王章甫小集斋中说旧事偶成 其三","f":"七言绝句","c":["珠楼曲曲贮仙娃，一带风窗十里纱。","记得中和门外路，女墙东去是他家。"]},{"t":"入超化寺水村","f":"七言律诗","c":["颓峦叠谷泻溪光，石上题名尚李唐。","竹叶送阴遮古寺，稻芒随水出山庄。","一林过雨芦花白，半壁疏云栗子黄。","犹记西风红蓼里，桐槽载网入潇湘。"]},{"t":"十六夜和三弟","f":"七言律诗","c":["凉月如霜鉴薄帷，空杯无计觅糟醨。","买镫聊复欢儿女，弄笔粗能遣岁时。","花火每攒骑马客，蜡光先照走桥姬。","少年乐事今无几，近老方知此兴衰。"]},{"t":"暮春同谢生汪生小修游北城临水诸寺至德胜桥水轩待月 其二","f":"七言律诗","c":["无才终是乐官閒，何地何宾不解颜。","乍叠乍铺风里水，半酣半醒雾中山。","御沟板落金鳞出，宫树花翻乳燕还。","浅绿疏黄是处有，泥人真自胜姬鬟。"]},{"t":"送君超兄还武陵 其二","f":"七言律诗","c":["山水心情谢永嘉，断沟残石渐盈车。","高斋是处鸦栖墨，娃阁频分燕作家。","袖里新书惊惠子，卷中逸事困张华。","乌藤白帢仙仙去，知入桃源几树花。"]},{"t":"和小修","f":"七言古诗","c":["蓟州新酒白石缸，空云影澄鸭头江。","露梢千缕扑斜窗，黄笙藤枕梦吴艭。","葛絺小眼如云凉，星河放教万尺长。"]},{"t":"和江进之杂咏 其一","f":"七言律诗","c":["山亭处处挈胡床，不独游忙睡亦忙。","官况易消如暴水，痴儿难长似黄杨。","岩花盛日求长假，石榻开时见古方。","掷却儒绅与巾子，添将冰水注茶汤。"]},{"t":"和江进之杂咏 其二","f":"七言律诗","c":["盆池清浅薄苔封，弱竹丛丛个影重。","残帙有芸犹被蠹，空阑无蕊亦招蜂。","西山郁郁蓁蓁气，讲阁朝朝暮暮钟。","箬叶数筐书尺五，岕茶新寄自吴侬。"]},{"t":"和江进之杂咏 其三","f":"七言律诗","c":["藤叶常悬四五葩，閒随方罫过邻家。","西厢托疾东厢假，南寺听经北寺茶。","蝶老花阑如倦客，天清云薄似飞纱。","姬衫典尽瓶犹馁，学把缗钱托画叉。"]},{"t":"和江进之杂咏 其四","f":"七言律诗","c":["六尺莎阶九尺庐，玄毫白楮任生疏。","花前屡泛摈愁酒，架上聊存引睡书。","蕲竹细纹如浪滑，吴绡寒纬似云舒。","幽窗一枕腾腾去，炼佛求仙事总虚。"]},{"t":"繁台张昭甫给谏竹居王孙邀饮留别","f":"七言律诗","c":["白果青蔬劳远程，高台倾矣曲池平。","沙田似雪耘枯冢，柿子如丹缀土城。","古渍有无遗宋岳，监门应否识侯生。","欲知别后愁多少，试检霜毛添几茎。"]},{"t":"宿朱仙镇 其一","f":"七言绝句","c":["秋高夜铎冷空庭，草木犹疑战铁腥。","地下九哥今悔不，六陵花鸟哭冬青。"]},{"t":"宿朱仙镇 其二","f":"七言绝句","c":["羯胡岁岁括金钱，称侄称臣也枉然。","马角不生龙蜕冷，酸心直到犬儿年。"]},{"t":"宿朱仙镇 其三","f":"七言绝句","c":["青骢挽断绿杨丝，寒食西湖祭酒时。","第六桥头香十里，桃花风起叠琉璃。"]},{"t":"宿朱仙镇 其四","f":"七言绝句","c":["祠前箫鼓赛如云，茹泣争劖吊古文。","一等英雄含恨死，几时论定曲将军。"]},{"t":"柳浪馆 其一","f":"七言律诗","c":["遍将蓝沈浸春颜，风柳鬖鬖九尺鬟。","鹤过几回沉影去，僧来时复带云还。","閒疏滞叶通邻水，拟典荒居作小山。","欲住维摩容得否，湖亭才得两三间。"]},{"t":"柳浪馆 其二","f":"七言律诗","c":["一春博得几开颜，欲买湖居先买閒。","鹤有累心犹被斥，梅无高韵也遭删。","凿窗每欲当流水，咏物长如画远山。","客雾屯烟青箧里，不知僧在那溪湾。"]},{"t":"坐王章甫水明楼","f":"七言律诗","c":["峦光设色浅深间，万瓦鳞鳞鉴碧湾。","孤塔自来当沔口，高僧相过说庐山。","常时杯底沈黄鹤，每就堂中乳白鹇。","南北精蓝青比比，蒲团才得个人闲。"]},{"t":"瀑布","f":"七言古诗","c":["寒空日夜摩幽绿，雾縠龙绡披几束。","银湾截断牵牛人，鞭起眠龙驾天毂。","帝宫酒暖浇愁春，雾汁茫茫泻清渌。","夜寒霜重玉女骄，袖裹金匜向地覆。","湘娥手挈潇湘来，雪魄云魂斗不足。","炎官不到落星城，六月人间呵冻玉。"]},{"t":"久雪忽晴喜而有作","f":"七言律诗","c":["残花残木总精神，才见寅年一日春。","柳态美如新栉发，山容亲似远归人。","閒追老衲三馀辈，更踏冰池五六巡。","江郭早须骑马出，旋呼稚子觅头巾。"]},{"t":"放言效白 其二","f":"七言律诗","c":["贤愚富贵且凭他，山上髻鬟柳上娥。","铁网试捞穿海月，渔舟任截过头波。","齐肩大士辞荤久，秃发中书感事多。","船上老郎江口女，咿哑容易得成歌。"]},{"t":"放言效白 其三","f":"七言律诗","c":["鸾靴争说上场难，衫袖郎当且自看。","世路两平三仄岭，人情八折九回滩。","胸中毛女霞千片，石上王乔药一丸。","梦去几番登岳顶，扶桑清水浴赪盘。"]},{"t":"放言效白 其四","f":"七言律诗","c":["高人窃欲比无功，閒把心情托去鸿。","《易》象有时输瓦卜，骚材兼不废媱风。","谋生拙似衔冰鹤，触事刚如蚀木虫。","莫放大鹏天上去，恐遮白日骇愚蒙。"]},{"t":"柳浪初正","f":"七言律诗","c":["旋赊白发号衰翁，旧业今缘次第空。","山鸟乍闻新格磔，峡僧遥寄小玲珑。","坐消纤雨轻阴日，閒踏疏黄浅碧风。","收拾方桥与兰桨，待看红萼慢流中。"]},{"t":"别龙君超君御兄弟","f":"七言律诗","c":["青鞋不破武陵春，归去西风一面尘。","荷叶山头闻杜宇，桃花源上别秦人。","深村稻熟泉当户，废苑茶香寺作邻。","可是无花无地主，祗缘无计得分身。"]},{"t":"桃花流水引 其一","f":"七言绝句","c":["华阳巾子碧绦环，紫府帘前旧押班。","阿母筵头争一掷，醉中输却小蓬山。"]},{"t":"桃花流水引 其四","f":"七言绝句","c":["夜深仙犬吠花关，私过云英与玉环。","天上看来偷律重，玉桃一颗谪人间。"]},{"t":"桃花流水引 其五","f":"七言绝句","c":["扫断红霞陌上尘，青鸾白凤集仙真。","吹笙捣药皆厮品，要作蓬山骂坐人。"]},{"t":"桃花流水引 其八","f":"七言绝句","c":["光碧堂前催赐衣，少年天女弱腰围。","而今花样新奇甚，不用银河织锦机。"]},{"t":"托龙君超为觅仙源隐居诗以寄之","f":"七言律诗","c":["云石村中且卜庐，凭君为买一峰馀。","全栽芝菊为疆界，尽写云岚入券书。","门对仙童浇药地，巷通毛女浣花渠。","閒中每爱天台去，好与刘晨閒屋居。"]},{"t":"竹枝词 其一","f":"七言绝句","c":["一溪才顺一溪湾，一尺才过一丈还。","船子已愁箭括水，儿童又指帽儿山。"]},{"t":"竹枝词 其二","f":"七言绝句","c":["芦花枝上水痕新，南市东村打白鳞。","只在梁山山背面，梁山何苦不离人。"]},{"t":"竹枝词 其三","f":"七言绝句","c":["武溪葱翠独称梁，正望黄山一点苍。","三日风头两日雨，谢公昨夜拜梁王。"]},{"t":"竹枝词 其四","f":"七言绝句","c":["侬家生长在河干，夫婿如鱼不去滩。","冬夜趁霜春趁水，芦花被底一生寒。"]},{"t":"初冬夜同郝公琰龚散木閒谈","f":"七言律诗","c":["云树萧然丈石居，清罍遥夜荐霜蔬。","佳言屡似飞香屑，往事真如绎故书。","窗外影閒双睡鹤，灯前手冷一编鱼。","寒花瘦竹差相得，白首承明梦亦疏。"]},{"t":"乙巳元日","f":"七言律诗","c":["湖柳侵街水接门，东风缬缬澹微温。","久乘下泽无官韵，乍著红衫有摺痕。","皓首赪颜俱入市，碧芽新鸟又成村。","归来且坐梅花下，倒却鹅黄四五樽。"]},{"t":"得家报 其四","f":"七言律诗","c":["洗头盆下撷芝苗，古洞深松话寂寥。","仙迹久湮无后辈，游人逆数即前朝。","身轻眼豁肠皆换，月冷烟清梦亦遥。","见说乳泉甘似酒，扪萝亲与试云瓢。"]},{"t":"得家报 其六","f":"七言律诗","c":["玉井前头乳穴重，奚儿聊以一瓯从。","空崖壁冷长留雪，古屋云昏尚锁龙。","明月自升千尺岭，道人閒说五株松。","瀑帘洞下真官老，占断林泉是此峰。"]},{"t":"结客少年场行","f":"五言古诗","c":["结交遍四海，乡人无半识。","耻纳无意儒，宁结有心贼。","白手一布衣，喜怒关通塞。","将相每在门，望气如望职。","易卜天昏晴，难候君颜色。","头颅可掷人，一顾不可得。"]},{"t":"钓竿行","f":"五言古诗","c":["岩滩一丝名，渭水一竿势。","所钓非所求，巨鳞安得至。","不如无名子，心胸少根蒂。","朝随鸥保歌，夜引鱼蛮醉。","探水如探瓮，随手得鳊鱥。","鲜蔬煮活鱼，无盐亦有味。"]},{"t":"秋胡行","f":"古风","c":["堂上姑，待汝哺。","袖中虽有金，不堪赠彼姝。","妾怀如日，君情若泥。","路旁之心不自保，安保他国无蛾眉。","沙浩浩，水咽咽。","妾死情，不死节。","河水如可竭，妾肠当再热。"]},{"t":"有所思","f":"五言古诗","c":["人生如驿骑，往复无停勒。","胸怀无尽丝，漫天作虚织。","秋霜与春风，乘间递为贼。","哀老迫红颜，白髭传消息。","积雪填枯井，井深填不得。","眉棱万斤重，白日沉幽墨。","欲行戒崄难，欲飞防缯弋。"]},{"t":"善哉行","f":"古风","c":["今日相乐，式舞且歌。","鹍弦铁板，白面青娥。","食羔以七，盛酒以盆。","刀鲚亦厌，何必河豚。","儒迂墨俭，唔非尧是。","善哉诸君，请入裈里。","读书不成，学仙寡效。","鼷腹鷡枝，从吾所好。"]},{"t":"猛虎行","f":"五言古诗","c":["甲虫蠹太平，搜利及丘空。","板卒附中官，钻簇如蜂踊。","抚按不敢问，州县被诃斥。","槌掠及平人，千里旱沙赤。","兵卫与邮传，供亿灴知几。","即使沙沙金，官支巳倍蓰。","镰徒多剧盗，嗜利深无底。","一不酬所欲，忿决如狼豕。","三河及两浙，在在竭膏髓。","焉知疥癣忧，不延为疮痏。"]},{"t":"短歌行","f":"古风","c":["酌君易州之清酝，被君吴阊之纤缟。","男儿二十无所成，腰肢一半没青草。","趁轻健，买騕褧，哭声多，笑声少。","黄金荡尽君莫嗔，古来饿杀几贤人。"]},{"t":"青骢马","f":"古风","c":["青骢马，九尺强。","百金买，千金装。","双蹄不著地，影灭如飞翔。","借问冶游郎，何为在他乡。","下马立青捂，手提碧珊瑚。","千唤不知人，尽眼眄当垆。","当垆岂不冶，褰衣愁晓露。","五步一停骢，十步一回顾。","客从远道来，赠我青鸾带。","交颈复同心，白石青松在。","东家好女秦罗敷，西家荡儿冯子都。","鸳鸯只爱毛翎好，那知水底有鹈鹕。"]},{"t":"折杨柳","f":"五言古诗","c":["艳阳二三月，杨柳枝参差。","每逢双燕子，忆得别君时。","忆得别君时，遗君珊瑚枕。","君行佳丽地，何人荐君寝。","越女性如绵，吴妓情似纸。","夫君浪子心，吹作东西水。","前月父书来，道君游淮北。","今月见君字，知作江南客。","江水自清流，照君不照妾。"]},{"t":"短歌燕中逢乐之律作","f":"古风","c":["下马一言，不及暄寒。","昔年毛羽，今日肺肝。","我怀如痞，君怀几许。","登堂直视，无心可举。","明月浮空，清霜堕地。","将军北园，金吾西第。","罗屏昼掩，金罍夜开。","呼卢射覆，飞爵流杯。","吾为若舞，若为吾歌。","剑去龙沉，逝将奈何。","情长刻短，炉寒火青。","歌尊乱箸，谁是主人。","鹏飞九万，为鸴鸠笑。","我欲携君，连翩海峤。"]},{"t":"醉乡调笑引","f":"楚辞体","c":["无怀十六传，乃至酒圣人。","其道尚清净，无为而化成。","周公作酒诰，流言几祸身。","宣王不得已，乃为述酒经。","经曰：天有酒，则不倾。","国有酒，则不争。","有王者起，必世而后仁。","何用导以德，齐以刑。","但当引酒为河，累曲为城。","日月所照，霜露所坠。","凡有血气者，莫不醉酲酲。","死兮不知死，生兮不知生。","沃杀知巧鬼，何愁不太平。"]},{"t":"剑泉上","f":"古风","c":["剑泉上，山如黛。","剑泉下，水如佩。","一片青，阅人代。","鬼窈窕，山叆叇。","生公法，今何在。","真娘墓，遥相对。","一日计千舟，一舟计万钱。","宁负公家税，莫负少年年。","女可鬻，妻可徙。","石上歌，应不止。"]},{"t":"逋赋谣","f":"古风","c":["索逋赋，逋赋紫不得。","不是县家苦催征，朝廷新例除本色。","东封西款边功多，江淮陆地生洪波。","内库马价支垂尽，民固无力官奈何。","苏州旧逋七十万，漕析金花居其半。","安得普天尽雨金，上为明君舒宵旰。","嗟乎民日难，官日苦。","竹开花，矿生土。"]},{"t":"祝雨","f":"古风","c":["云缕缕，山絮絮。","寒欲来，暖先据。","洗山山骨新，洗花花色故。","寄言行雨儿，莫下山头去。"]},{"t":"宋帝六陵","f":"古风","c":["冬青树，在何许。","人不知，鬼当语。","杜鹃花，那忍折。","魂虽去，终啼血。","神灵死，天地膻。","伤心事，犬儿年。","钱塘江，不可渡。","汴京水，终南去。","纵使埋到厓山厓，白骨也知无避处。"]},{"t":"西施山","f":"古风","c":["西施山，一片土。","不惜金作城，贮此如花女。","越王跪进衣，夫人亲蹋鼓。","买死倾城心，教出迷天舞。","一舞金间崩，再舞苏台拆。","槌山作馆娃，舞袖犹嫌窄。","舞到夫差愁破时，越兵潜渡越来溪。"]},{"t":"入青口 其一","f":"古风","c":["入青口，青口山何直。","云老玻瓈天，鬼下空青壁。","一络罡风吹地起，神禹无功巨灵死。"]},{"t":"入青口 其二","f":"古风","c":["入青口，青口山何仄。","石人立而啼，云吼吼相逼。","蚶岩开老沉香花，飞仙失路虎无家。"]},{"t":"入青口 其三","f":"古风","c":["入青口，青口山何翠。","涧色吠琉璃，山花红玳瑁。","天荒地窘无行处，山头魍魉纷来去。"]},{"t":"王京洞","f":"古风","c":["深如谷，高如屋。","穴云心，穿地腹。","路荒唐，齿崄嶬。","石如病，天似痴。","黄者浆，白者髓。","云絮絮，出靴底。","白蝙蝠，大于鸡。","冲焰起，扑人飞。","突而高岭间之，忽而平溪限之。","龙欲言，闻人止。","涎沫流，腥风起。","鬼邪仙，烟欤雾。","炬无光，将安去。","海可通，江可涉。","灵威丈人难再得。"]},{"t":"别石篑 其一","f":"古风","c":["别石篑，石篑何忍别。","相知是相知，知处难容舌。","一等是肝肠，输君生死切。","烈火潦虚空，火尽空不灭。"]},{"t":"别石篑 其二","f":"五言律诗","c":["古今只四伦，大抵缺明友。","谁识楚越人，万里为奇偶。","我肠寄君心，君心出我口。","觅同本自无，异于何处有。"]},{"t":"别石篑 其三","f":"五言古诗","c":["一叶随东风，飘泊巳半载。","梯雪度深山，寒气铄孤拐。","三入净寺门，寺僧笑狂騃。","欲得不相讥，除非观自在。","是仙是凡人，请君是挥解。"]},{"t":"别石篑 其四","f":"五言律诗","c":["君携我如头，我从君若尾。","不是西看山，便是东涉水。","谁家薄福缘，生此两狂子。","受用能几何，苦他双脚底。"]},{"t":"别石篑 其五","f":"五言古诗","c":["学道不学禅，谈星不谈义。","爱曲不爱音，读书不读字。","人天收不得，贤智亦为祟。","不知何因缘，偏得同臭味。","每笑儒生禅，颠倒若狂醉。","除却袁中郎，天下尽儿戏。"]},{"t":"别石篑 其六","f":"古风","c":["南山有禽，其字曰希有，壮山有鸟，其名曰凤凰。","两鸟排云扶雾入虚空，虚空莽莽四顾绝稻梁。","下界岂无七寸之粳米，争奈网罗缬缬常高张。"]},{"t":"别石篑 其七","f":"古风","c":["不即凡不求圣，相依何觅性命。","三入湖两易令，无少长知名姓。","湖上花作明證，别时衰到时盛。","后来期不敢问，我好色公多病。"]},{"t":"别石篑 其八","f":"五言律诗","c":["归去寻阿宾，阿宾亦可人。","公家廿一弟，超脱是其伦。","天不孤生物，有必辀有轮。","狂态诚可取，其若头上巾。"]},{"t":"别石篑 其九","f":"古风","c":["气嘘为风，云流为水。","人之小人，人之君子。","鸭不能飞，蚓不能跃。","枭哭非愁，鸾歌非乐。","无曰升天，天卑于渊。","无曰瞰渊，渊高于天。","即佛即圣，非儒非禅。"]},{"t":"别石篑 其十","f":"五言古诗","c":["能再相从否。","若驾相思车，当问白门柳。"]},{"t":"酒正喧萧君席上作","f":"古风","c":["酒正喧，关吏言，请君秣马饬归辕。","巴川健儿豕成群，邀官挟吏通州门。","逐虎怯，逐飞蚊，倭刀吼室箭出鞬。","东坊西市榜明文，不严军律严司阍。","木门苍琅根，日未昏，断行人。"]},{"t":"坐王官谷朋石馆得石字","f":"古风","c":["林家梅，米家石。","荀家香，谢家屐。","鹤瘦带道容，松老入诗格。","竹子一万梢，十里屯秋碧。","杂花四五种，聊作琅玕役。","贮雪点梅汤，和香烧筝炙。","一分供调御，一分待幽客。"]},{"t":"洋溪湖嘲沈青平 其一","f":"古风","c":["家湖头，客湖尾，深盎浅瓮量鱼子。","大妇得白鲢，小妇得赤鲤。","天乾富马涝富鲊，鰸儿牧豕荻根下。"]},{"t":"洋溪湖嘲沈青平 其二","f":"古风","c":["湖头船，湖尾屋，丈人把叉婿收目。","朝餔乾鳖裙，暮脍鲜鲫丝，螺头蚌子送妇归。"]},{"t":"戏题道士洑","f":"古风","c":["道士名，髡其颠。","真石壁，貌假山。","阳户开北面，东流水西还。","采石蛾眉小姑鬟，苍瘦争似老黄冠。","江汉手覆三回乾，古凰遗尾青阑干。"]},{"t":"代青溪道士见招","f":"古风","c":["青溪月，和霜和冰发。","万仞沁寒潭，冷尽玻璃骨。","青溪花，傍水带烟斜。","东曲谢兰香，西曲萼绿华。","青溪水，云根洗清泚。","朝浸角里芝，暮烹王烈髓。","青溪雪，万顶千峰彻。","隔浦唤仙奴，夜舂云母屑。","君之来，猿鸟笑。","云为丹，风为棹。","鬼谷罢谈，孝先徙灶。","骖凰与驾鹄，知非君所好。","吾为君招赤城之化骨及绝逸之髯，君为我欢然而就道。","君不来，云山澳。"]},{"t":"嘲王以明先生","f":"古风","c":["王夫子，有书如郝隆。","何缘阿堵堆青铜。","君不见象头有心?夷甫，道上无人追楚弓。"]},{"t":"雀劳利歌","f":"古风","c":["雀劳利，雨雪至。","大雀悲，小雀悸。","黄鹄举千里，大鹏搏九万。","鹧鹄与杜宇，声声来相劝。","宇曰不如归，鸪曰行不得。","小大各有分，何用噌噌在我侧。","鹦鹉虽有舌，藏巧不如嘿。"]},{"t":"采莲歌","f":"古风","c":["采莲花，花开何鲜新。","映月为处子，随风作舞人。","深红浅白间秋水，妒杀麻姑与洛神。","采莲叶，莲叶连香楫。","一片青花古玉盘，持赠秦娥与燕妾。","采莲子，莲房劈破香且美。","纤手分来颗颗匀，何事经年沉湖水。","湖水深犹可，水浊情无那。","试问南溪二月泥，妾心辛苦知不知。"]},{"t":"戏别唐客客丰城人 其一","f":"古风","c":["年年为客向潇湘，楚泽烟云拾满囊，绵花如雪归故乡。","归故乡，应知青雀临流日，内人蟢子坠衣裳。"]},{"t":"戏别唐客客丰城人 其二","f":"古风","c":["年年为客向章台，面脂如珠红满䰄，短褐行缠归去来。","归去来，种得油麻如黍子，依旧风帆向楚开。"]},{"t":"浩歌","f":"古风","c":["云作雨，不成归。","箭离弦，无还期。","昨日犬，前日狮。","一番花，一番泥。","花有色，槛周之。","人有容，镜照之。","镜方新，容已非。","槛未敝，花先飞。","短可续，用何物。","一曲歌，三杯醁。","我欲长生天下人，拔刀斩断金乌足。"]},{"t":"诸衲送至江干自嘲","f":"古风","c":["油江渡，二十年中五番去。","餐云醉石几经春，毕竟驱上长安路。","油江上，柳如云，江若有知应移文。","隔溪老衲笑且话，塞耳喧呼如不闻。"]},{"t":"戏作三星行送曹子野归楚时予亦将归里","f":"古风","c":["石公先生，汝生以郑为宅，以水为度。","眠龙痴蛟鞭其尾而不飞，唯有蛰龙闻雷而起。","仰天潝潝如有诉，所乐者瘦壤清泉，所吟者溪风月露。","有窍无心何所郁以鸣，不过感时触机如风行于空而万窍自怒。","隐流缁客，目为山中之韶頀。","识者又以为偏枯冷，淡似于陵仲子之清，轩辕弥明之句。","石公抚几而笑曰：曹君汝岂敦煌之索，平原之辂。","长安冠带隘巷陌而相求，胡为乎逐西风而远去。","君既脂车，余亦戒路。","望江上之青峰，指湘皋之红树。","汉沔相踞，一衣带水，俟君于油口之渡。","左公城外绿刺天，便是巨擘高吟处。"]},{"t":"过中山见诸名迹题清风店壁","f":"古风","c":["中山酒可饮，塔可登。","辋川翠竹风棱棱。","东坡瘦墨如健鹰。","唐封古迹石崚嶒。","刺史爱民慈且能。","高看青山夜抱冰。"]},{"t":"石公解嘲诗","f":"楚辞体","c":["信美此土兮，乐而忘死。","彼国之人兮，爱贤好士。","彼国之王所与游者何人兮，华胥之君臣，西方之父子。","彼国无劫数等量兮，不知者以为自酉而开，至卯而止。","于是醉君闻石公名，乃召以为客卿。"]},{"t":"潼关题壁","f":"古风","c":["官道上，尘昏昏。","邮舍中，气煴煴。","夹道如火益膏薪。","枯鱼失水噞其唇。","华山君，岂不闻。","濡笔雨，和墨云。","十丈莲焦玉女嗔。","乘风自振潇湘裙。","夜半浇我洗头盆。"]},{"t":"赠李医者","f":"古风","c":["秋橘绿成行，方书白满架。","君非韩伯休，胡乃不二价。","去年短褐辞乡里，游来半载声名起。","参苓如山信手空，门前冠带若流水。","长安医士乱于府，个个乌纱似老鸦。","谁似丰城李公子，谈笑直揖五侯家。","朝卖药，晚致身。","大妇喜，小妇嗔。","席未温，呼先生。"]},{"t":"哭临漳令王子声 其一","f":"七言古诗","c":["穷冬夜冷兰烟黑，死字传来听不得。","白日谁昉鬼射人，昏荒颇怪天如墨。","忆昨与君发长安，白齿青眉吐肺肝。","小杯击筑大杯舞，优儿牙板角盘盘。","别来愁绝湘鳞字，蜡花笺子无高翅。","铜雀台边万缕肠，馆娃宫里千行泪。","麒麟蹶地青鸾叫，不得生书得死报。","帝前金管岂无人，何必如花一年少。","天公错注不回头，银匣沉沉地下愁。","漳水万年嘶石马，虎号龙愁两废丘。"]},{"t":"哭临漳令王子声 其二","f":"古风","c":["垂头再哭哭声哑，长夜幽幽悲逝者。","破玉锤珠可惜人，天何言哉无知也。","三哭眼酸泪枯欲流不得流，焚香告天愿天为我开咽喉。","颜渊鲁高士，胡为三十一而死休。","灵均楚直臣，云何枯槁江潭望君门而媒蹇修。","云何为而投阁，贺何为而赋楼。","渴何为而病马，癞何为而疾牛。","龙何愚而触网，鳌何细而随钩。","山何卑而成水，海何升而为丘。","圣者不能言，愚者不能忧。","释迦与老子，眯矇双白头。","即如王子声，高第十二秋。","穷年只淹蹇，低眉拜督邮。","谗言复间之，刺心如戈矛。","缠棺布三尺，栖身土一抔。","嗟乎子声，汝生不能一日牙牌黑须拱手长安道，又不能拂衣故园补缀先人草。","万里迢遥魄伴魂，一具瘦骨官送老。","福君何其薄，夺君何其早。","和氏空有泣，楚国无以宝。","天不平，地不平，吁嗟乎王子声。"]},{"t":"湘湖莼菜","f":"古风","c":["托恨西湖，沉质湘水。","鍊玉为脂，熬冰出髓。","松及苏人，皆云无此。","盛春而生，方夏而止。","何故季鹰，待秋风起。"]},{"t":"出燕别大哥三哥","f":"五言古诗","c":["长安二月时，阳缓北风厉。","霜刃割地皮，古木领寒气。","纷纷骡马尘，晓起如云辟。","置酒上南冈，别我好兄弟。","一母生三人，顶踵皆相类。","发愿穷无生，百劫相砥砺。","言前识锋机，死里寻关捩。","居身如竖铜，蓄口唯谈义。","兄性温而真，弟性坦而毅。","余性兼宽猛，弦韦时相济。","堕地便同根，飞天亦共翅。","一旦忽分首，能不添憔悴。","白马望吴门，惨淡无边际。","畏路如畏虎，猜官如猜谜。","长兄见老成，劝余勉为吏。","钱谷慎出入，上下忌同异。","小弟发狂谭，兄言胡乃赘。","胸臆自可行，荣枯安足计。","纵使挂弹章，亦只数行字。","八十日彭泽，独非男儿事。","言罢日西沉，强起各分袂。","马尾对马尾，东西倏异位。","欲哭近妇人，一笑飞寒泪。"]},{"t":"渐渐诗戏题壁上","f":"五言古诗","c":["明月渐渐高，青山渐渐卑。","花枝渐渐红，春色渐渐亏。","禄食渐渐多，牙齿渐渐稀。","姬妾渐渐广，颜色渐渐衰。","贱当壮盛日，欢非少年时。","功德黑暗女，一步不相离。","天地犹缺陷，人世总参差。","何方寻至乐，稽首问仙师。"]},{"t":"戏题斋壁","f":"五言古诗","c":["一作刀笔吏，通身埋故纸。","鞭笞惨容颜，簿领枯心髓。","奔走疲马牛，跪拜羞奴婢。","复衣炎日中，赤面霜风里。","心若捕鼠猫，身似近膻蚁。","举眼尽无欢，垂头私自鄙。","南山一顷豆，可以没馀齿。","千钟曲与糟，百城经若史。","结庐甑箪峰，系艇车台水。","至理本无非，从心即为是。","岂不爱热官，思之烂熟尔。"]},{"t":"赠汪咸池乃郎","f":"五言古诗","c":["不是干时客，零丁向吴越。","家贫访故人，吞声学干谒。","先鬼能文章，清新好气骨。","遗篇犹入梓，桂枝已摧折。","不忍念姓名，逢君滋哽咽。","哀哉勿复言，长风捲愁雪。"]},{"t":"别龚散才","f":"五言古诗","c":["梅雨濯江干，江风细吐寒。","红亭一杯酒，惨无宾主欢。","天风吹子堕，倏忽送子还。","游踪如电影，闪烁太无端。","子曰为官苦，予嗟行路难。","各自相慰劳，言言沁肺肝。","与子如林鸟，升沉各羽翰。","别子如湍水，东西异波澜。","何如一合并，白首臭春兰。","萍散有时聚，云老终还山。","江头风日雨，容易彫朱颜。"]},{"t":"陶石篑兄弟远来见访诗以别之","f":"古风","c":["五步一花开，十步一花飞。","不知谁中子，郁郁吐清姿。","恬淡僧标格，潇洒士威仪。","手提白玉尘，身披浅色衣。","徒步入闾门，挥羽上阶墀。","僮仆尽魁伟，一一晢而肥。","或言是山人，或言星相师。","或云乡里子，闻声始觉非。","通刺无姓名，短纸摺不齐。","一揖径登床，草草寒喧而。","执手不问病，捧腹但言饥。","设黍呼儿子，蒸鱼命小妻。","广长舌有象，突兀语难羁。","欲穷人外理，先剖世间疑。","五行何因起，天地何高卑。","鹄乌何白黑，日月何盈亏。","生胡然而至，死胡然而?。","天胡然而喜，鬼胡然而悲。","事无微不究，语无响不奇。","独不及臧否，一切细碎词。","玄旨穷三日，清言畅四肢。","爱君玺入理，恐我倦伤脾。","未作经年别，先为五日辞。","入宫寻西子，涉水吊鸱夷。","七十二螺髻，三万六坡璃。","山水既奇敌，相得永因依。","有如重瞳郎，配合皇英妃。","又如曹阿瞒，生逢大耳儿。","石公貌高古，林屋洞倾攲。","玉绕消夏湾，水齧十人矶。","浪头悬闾里，屋底腥蛟螭。","山鬼攀萝出，鲛人傍槛睎。","卑者如鼋鼍，立者如象犀。","幽者穿海底，高者蹑云梯。","绿橘黄柑树，青牛白马祠。","土人之新果，乡女贡山鸡。","胜事纷难记，名山到始知。","一朝尽缥渺，一雨负莫釐。","归来为我言，山水见须眉。","长公八九纪，叔子二十诗。","字字传寔迹，语语发光辉。","不独作者难，读者亦应稀。","谭罢理前问，愁未申后期。","还将赤金子，试我白绵锤。","拈花怜佛笑，摘叶止儿啼。","蹶杀紫胡犬，踢倒西河狮。","击石原无竹，悟桃空有枝。","一番铜铁语，万仞箭锋机。","病得发而减，客以乐忘疲。","流连十许日，情短六个时。","大夫一滴泪，错落贵珠玑。","今日若为别，相顾浩涟洏。","去去复去去，吴江落日低。"]},{"t":"初度戏题","f":"五言古诗","c":["碌碌复碌碌，浮生如转毂。","帝宏匝地罗，人窘弥天狱。","堕地三十载，强半是颦䠞。","算喜无十星，量愁有千斛。","十五岁以前，师傅苦拘束。","朝愁日上舂，暮愁书难读。","十五岁以后，龟手事场屋。","儒中卞去头，宦网又缠足。","千眄得一官，万眄得微禄。","谁知徼五斗，妻子转枵腹。","颜色低上官，肝肠枯案牍。","举止动得过，憎恚若相触。","月不十回圆，酒无三朝熟。","来者不可知，去者不可赎。","欲留色枯槁，欲归心彳亍。","一病觉昨非，万仞遂黄鹄。","勿以径寸荣，易兹寻丈辱。"]},{"t":"荅江进之别诗","f":"五言古诗","c":["横将一尺素，写出消魂别。","泪深笔波红，情苦绢文裂。","事君才两载，相期砺高节。","有过必直陈，无忧不共切。","密意臭兰旃，奇谈飞金屑。","案牍与文史，一一相商决。","对客语如绵，当机锋似铁。","喜怒性情真，缓急肝肠热。","所以小修言，江郎吴令杰。","官虽暂时离，交岂中道辍。","古井绝回波，深山无化雪。"]},{"t":"别江郎","f":"五言律诗","c":["江郎貌奇崛，文字多古质。","十三读父书，十五梦先笔。","父母怜爱之，保护常在膝。","何不从我游，扁舟访二室。"]},{"t":"雪夜感怀同黄道元作","f":"五言古诗","c":["孤馆寂无人，童仆三两辈。","白势压山来，云冷天憔悴。","灯寒字欲青，炉死灰相对。","流火掣空飞，错落如星碎。","可惜行乐场，都被微官碍。","歌喉络飞蛛，谁家佳姊妹。"]},{"t":"别黄道元信笔题扇上","f":"五言古诗","c":["千里负空囊，蹇足投吴令。","客子既数奇，主人复善病。","薄俗异临邛，好事乏程郑。","逆居垂半载，无化知名姓。","乞饭随白足，佣经皈大圣。","未免无鱼歌，能不驯龙性。","贫者士之常，达岂文章命。","舌在即王侯，文成之歌咏。","去矣莫徘徊，无官谁相敬。"]},{"t":"艳歌","f":"五言律诗","c":["鹊尾唾兰烟，灰冷烟不灭。","东风多少愁，吹落谢豹血。","郎寄鲳鱼子，妾寄西施舌。","花开不待人，青春忍相别。"]},{"t":"仲春十八日宿上天竺 其一","f":"五言律诗","c":["三步一号呼，十步一礼拜。","万人齐仰瞻，菩萨今何在。","欲寻真大士，当入众生界。","试观海潮音，不离浙江外。"]},{"t":"仲春十八日宿上天竺 其二","f":"五言律诗","c":["若以色见我，是人行邪道。","饶他紫金身，只是泥与草。","朝来白照面，三十二种好。","终日忙波波，忘却自家宝。"]},{"t":"山阴道","f":"五言律诗","c":["钱塘艳若花，山阴芊如草。","六朝以上人，不闻西湖好。","平生王献之，酷爱山阴道。","彼此俱清奇，输他得名早。"]},{"t":"雾中望山","f":"五言律诗","c":["雾是酲山酒，雾重山如醉。","登高气不清，万象争规避。","日无光而毛，天不昏而睡。","云影叠飞沙，风花洒空泪。"]},{"t":"贺家池","f":"五言古诗","c":["昔闻八百里，今来八百亩。","为问袁阿宏，何如贺监不。","黄冠吾愿学，其如多八口。","形体作仆奴，礼法成枷钮。","幸尔略知识，效颦辞五斗。","强作舒眉诗，学饮宽肠酒。","所以不脱然，为身非我有。","恩爱毒其躬，父母掣其肘。","未免愧古人，青山空矫首。"]},{"t":"禹穴","f":"五言古诗","c":["窆石立如人，鼻穿腰半折。","不看碑头字，那知是禹穴。","栏楯半摧残，古文尽磨灭。","山高仰瘦容，松老添孙鬣。","古屋闭狐妖，香台蹲豹迹。"]},{"t":"第一泄","f":"五言古诗","c":["踏人肩而行，次第乃得过。","射眼风丝飞，置足山毛破。","局身缒草移，定踹盘泥坐。","五水势高低，千峰身顿挫。","路荒雨气腥，树老班皮裹。","度岭羡猿轻，投崖愁虎饿。","常恐决性命，归来始相贺。"]},{"t":"志别种山阁作","f":"五言古诗","c":["楚国一段云，落地无根蒂。","偶尔置膻风，吹作尘霾气。","道逢三鹓雏，衔我入云际。","携手上仙山，长啸起天寐。","苍竿画古云，踏破春峦翠。","迂谷访长眉，空山顿龙辔。","胥潮隔湘祠，路满一鹏翅。","天长吴楚波，羁影入遥睇。","知心如冰焰，前程若神谜。","君看露上枝，无心也垂泪。"]},{"t":"湘湖","f":"五言古诗","c":["而我游湘湖，恰值湖水小。","湘湖旧有名，敢道湖不好。","辟彼如花人，必须眉黛姣。","一旦决洪流，山宁不枯老。","白鲤曝腮鳞，渔刀蔽深草。","水少已不堪，何况酒更少。"]},{"t":"姚叔叉","f":"五言律诗","c":["昔我吏吴门，冠带填门阈。","白发老山人，闻名面不识。","一朝弃官去，空山翻见迹。","何不嘘热官，而煨寒灰客。"]},{"t":"送王静虚访李卓师","f":"五言古诗","c":["天地愁结成，圣贤愁眷属。","举眼皆针锋，何处可容足。","儒生有毛病，道理充穷腹。","百虑堆作城，万想锻成狱。","突有大妄人，手持无羽镞。","欲解大地罗，先肆弥天毒。","扇海作洪炉，燎山煮精玉。","何不触其嗔，悬崖求所欲。"]},{"t":"馀杭雨 其一","f":"五言古诗","c":["不恨今日雨，却恨前日晴。","无端放隙光，诱我馀杭行。","馀行有何趣，败寺老和尚。","若使在西湖，亦得闲眺望。","出门无去处，袖手东西顾。","桑下见蚕娘，泥滓沾衣裤。","只是去临安，已觉步步难。","何况径山路，千盘与万盘。"]},{"t":"馀杭雨 其二","f":"五言古诗","c":["一心闲处忙，四体山行瘦。","荒吹破梦欢，孤枕逼檐霤。","山灵无好情，梅天多异候。","主僧嗔客留，仆子呼天漏。","云不十丈高，泥凡尺馀厚。","纵有健马驴，挥鞭岂能骤。"]},{"t":"于潜道中偶成","f":"古风","c":["出门二三月，客行常踰质。","问我亦不知，奔波为何物。","越鸟也嘲人，解问爹归弗。","爹岂不思?，山淫成痼疾。","百里一名山，一山须十日。","东南半壁地，十分未了一。","云霞朝到眉，魈鬼夜入室。","遇伴觅定方，逢仙谈飞术。","形体节节劳，心神?般逸。","名胜尚可穷，游子兴难毕。"]},{"t":"天目道中和陶石篑韵","f":"五言古诗","c":["万岭色娇荣，千松韵苍老。","溪锦新织成，云文初脱稿。","古屋系龙儿，幽崖聚仙媪。","淡冶天微醒，昏沉雾尚饱。","山灵如有情，游子暂舒恼。","梯石路渐高，踰岭天乍小。","微茫一带青，远远出山杪。","白云封其半，恍若衣轻缟。","山僧向我言，此是诸山考。","四顾尽儿孙，累累争围绕。","一乳作凤飞，一支学龙矫。","万络与千支，支支相萦搅。","山形虽浑成，石貌寔妍巧。","初视尚冥迷，策骑渐分晓。","何况陟其颠，遵途亦已好。"]},{"t":"天目书所见","f":"五言古诗","c":["菩萨与凡庸，不知谁正倒。","牛马若率真，形貌亦自好。","独有知见人，不食本分草。","拾他粪扫堆，秘作无价宝。","面上曲折多，腹内安稳少。","坐立皆成文，闲话亦打稿。","演出活法聪，难瞒俊阎老。"]},{"t":"浩歌登天目峰顶","f":"五言古诗","c":["一笑廓天笼，邈矣何空旷。","千山如藻萍，点点白波上。","世界无安置，虚空有等量。","茫茫戋虱人，妍丑分何状。","丘翟语曰知，舜会禅为让。","裈中闲是非，瓮里狂波浪。","十年学贡高，一朝色沮丧。"]},{"t":"宿幻住晓起戏题","f":"五言律诗","c":["咄哉袁中郎，胡不侵晨起。","百千大世界，吹作瀛海水。","披衣起视之，果然云在底。","弥天布琉璃，山神圣乃尔。"]},{"t":"玉上人","f":"五言律诗","c":["山下逢老僧，为我设斋供。","生断活埋关，醒却高峰梦。","空嫌毛孔多，瘦觉数珠重。","回首鸭子飞，归来鼻头痛。"]},{"t":"云上人","f":"五言律诗","c":["一喝二日聋，江西立宗派。","师瞆多少时，證得观自在。","不受喧寂尘，跳出声闻界。","笑杀观世音，圆通却成碍。"]},{"t":"徽谣戏束陈正甫","f":"古风","c":["掺履若云青，肝肠如日杲。","打脸坐黄堂，要把奸顽扫。","披霜夜书佥，戴星朝画卯。","移文四五张，禁约三两道。","拊心谈民穷，攒眉视金宝。","夏衣半疋葛，冬穿一领袄。","门子赤脚多，皂隶白牌少。","世人眼如豆，便道大爷好。","谁知大夫心，厌之如粪草。","本是俊男儿，扮作酸寒老。","慈悲心愈毒，粗豪胆乍小。","闭门录高士，留客杼愁抱。","所事皆明畅，无法不精晓。","只在一寸心，愈参愈不了。","人品高难?，佛法近难讨。","处脂不能润，徒劳伤枯稿。"]},{"t":"赠潘景升","f":"五言古诗","c":["弥天作旅人，著处为眷属。","新知与旧欢，凑集如云族。","堂上罗楚羞，堂下度吴曲。","东阶串仆奴，西阶悬马毂。","面缕大如柱，盘鲜高于屋。","鞭车行酒杯，犹恐欢不足。","咳吐寸寸肠，挥毫字字玉。","不过沈宋门，宁作李王役。","世人眼如盲，相牵入阱狱。","岂以瓮中鸡，而易云外鹄。","万事无奈君，难君只有贫。","转贫客转多，贫岂奈君何。"]},{"t":"梦中题尊经阁醒后述之博笑","f":"五言古诗","c":["壮哉尊经阁，缥缈入烟雾。","千山列鲁儒，拱揖不知数。","俗竞形家言，两塔遥相顾。","累土作尖峰，上有参天树。","海阳多贾人，纤啬饶积聚。","握算不十年，丰于大盈库。","富也而可求，执鞭所忻慕。","金口亲传宣，语在述而处。","师与商孰贤，赐与回孰富。","多少穷乌纱，皆被子曰误。"]},{"t":"喜逢梅季豹","f":"古风","c":["?里少冶容，邯郸无高步。","万耳同一瞆，活佛不能度。","摹拟成钝贼，七子递相误。","膻骨蚁回旋，驴脊苍蝇聚。","徐渭饶枭才，身卑道不遇。","近来汤显祖，凌厉有佳句。","宾也旷荡士，快若水东注。","丘肥与潘髯，俱置兄弟数。","越中有二龄，解脱诗人趣。","立意出新机，自冶自陶铸。","举世尽奴儿，谁是开口处。","我击涂毒鼓，多君无恐怖。","洗眼读君诗，披天抉云雾。","不独爱君诗，爱君心相顾。","众人嗔我喜，天下憎君慕。","鸡坛如可盟，旗帜为君树。"]},{"t":"戒五老峰题石","f":"五言古诗","c":["尝怪杨真珈，作俑飞来峰。","名山如有灵，请以一九封。","齐云富奇壁，题识遍空翠。","卷石亦不容，岳神有何罪。","碑文多谀辞，金壁增腐气。","所幸五老峰，笔灾尚未至。","珍重后来人，慎勿妄题字。","山神已證明，后生毋轻易。","好事倘不然，头骨随鞭碎。"]},{"t":"齐云岩","f":"五言古诗","c":["江滨有异石，好事持作供。","珊瑚木难珠，似者即矜重。","齐云天下岩，深壁连绀洞。","山山玛瑙红，高古复飞动。","只是作盆景，鲜妍已堪弄。","假饶置篚筐，岂不充奇贡。","幽崖鬼斧穷，玄壑飞仙恸。","帘两万丝飞，云采千年冻。"]},{"t":"石桥岩","f":"五言律诗","c":["天门即前阍，石桥即复户。","两门去几何，五五二十五。","石老易生云，山髡不藏虎。","岳神饶客情，阁起千峰雨。"]},{"t":"赠章子","f":"五言古诗","c":["越俗上形家，贵贱倚为命。","郭璞多于毛，谭者自神圣。","近来陶石篑，颇不遵先今。","独喜令亲章，议论能持正。","楚人无远谋，相地多任性。","不识到头龙，休贪书世盛。","愿得皇如金，不愿砂如印。"]},{"t":"严子陵滩限韵同陶石篑方子公赋 其一","f":"五言古诗","c":["一州数百里，山水半呼严。","先生高洁人，取名胡不廉。","宏也负奇气，气高心廉纤。","空有如绵腰，了无似戟髯。","稽首先生祠，自羞自弃嫌。","高迹如可履，乞我上上签。"]},{"t":"严子陵滩限韵同陶石篑方子公赋 其二","f":"五言古诗","c":["不是刘文叔，讵说严老子。","羊裘钓滩下，一渔户而已。","无用合退藏，非是退藏是。","谁知误得名，来者趋如市。","末世竞声称，藏丑翻成美。","与其作假龙，孰若真虫蚁。"]},{"t":"严子陵滩限韵同陶石篑方子公赋 其三","f":"五言古诗","c":["不肯助为理，咄咄严子陵。","皋夔与管商，问君能不能。","众狗逐膻羊，疾者业先登。","我才不如狗，妥用强奔腾。","明月虽有照，终不笑孤灯。","不见东阳殷，强出如冻蝇。","积溺以自监，效鸠勿效䴒。"]},{"t":"严子陵滩限韵同陶石篑方子公赋 其四","f":"五言古诗","c":["因山以为台，因水以为滩。","因草以为丝，因木以为竿。","因拙而辞世，因傲而弃官。","严翁诚自知，刘叔亦难瞒。","宁有同肝膈，而不可羽翰。"]},{"t":"赠李云峰 其一","f":"五言律诗","c":["西湖多奇山，其肤乃在水。","杭人伴妇游，嗜肉不嗜髓。","先生每追随，茧足穷其底。","何处识老髯，自虎跑杲始。"]},{"t":"赠李云峰 其二","f":"五言律诗","c":["追我于天目，因而上白岳。","葛衫芒草鞋，高坐享天乐。","败石齧鞋耳，罡风剪衣角。","一味恋冥鸿，何曾伴鸠鸴。"]},{"t":"孟生为尊慈索诗信笔题四韵","f":"五言律诗","c":["少年读孟书，长大更聪明。","他日逢滕子，井田行不行。","十年奉慈教，督子若先生。","将萱比轲母，知君未嫌轻。"]},{"t":"湖上别同方子公赋 其一","f":"五言古诗","c":["宁作西湖奴，不作吴宫主。","死亦当埋兹，粉香渍丘土。","一住二三月，天食供穷窭。","万五千树花，百二十回舞。","花为结子忙，人为别花苦。","辟彼一天云，时地吹作雨。","彼此俱黑头，一夜添霜缕。"]},{"t":"湖上别同方子公赋 其二","f":"五言古诗","c":["望望鄂公坟，石龟与人齐。","冢前方丈土，浇酒渥成泥。","虽知生者乐，无益死者啼。","如彼坟前马，张吻不能嘶。","天地入海劫，志士合鸾栖。","曷为近汤火，为他羊与鸡。","孤山梅处士，事业未曾低。","西陵倡家女，松柏夹广蹊。","红粉是活计，山花足品题。","奚折稣公柳，策马度花堤。"]},{"t":"湖上别同方子公赋 其三","f":"五言古诗","c":["一段青石堤，袅娜千垂杨。","十许种名花，红紫白成行。","借问此谁种，云是监中郎。","纱纹织作浪，文玉砌为堂。","安得冢子山，吹来置此傍。","醉中发狂思，醒后益周张。","吾身自可移，何必移吾乡。"]},{"t":"湖上别同方子公赋 其四","f":"五言古诗","c":["葛巾不束毛，纱祫常见肘。","无日不酲花，有时坐枯柳。","天地一排场，谁分旦与丑。","神仙既荒唐，富贵复难偶。","杭人有谚言，言卑趣则有。","雷峰变作糟，西湖化为酒。","藕花作美人，一歌了一口。","三万六千回，一回三百斗。"]},{"t":"湖上别同方子公赋 其五","f":"五言古诗","c":["天地如悬鹄，圣贤若藏阄。","万古愁茫茫，谁是的路头。","官者为利缚，隐者为名囚。","玄无点化术，禅有知见忧。","欲灭身旁影，终迷水底搂。","十年而一叶，枉自费雕鏉。"]},{"t":"湖上别同方子公赋 其六","f":"五言古诗","c":["年年负空箧，满贮不十金。","自知荷叶命，蓄水终难任。","抱牍苦不治，抱瓮苦不深。","安得清神药，止我狂华心。","苦吟终为病，不苦不成吟。","飞思入九渊，捃拾到虫禽。","闻说三天顶，别有无忧林。","何日陟其颠，洗耳听仙琴。"]},{"t":"湖上别同方子公赋 其七","f":"五言古诗","c":["龙井饶甘泉，飞来富石骨。","苏桥十里风，胜果一天月。","钱祠无佳处，一片好石碣。","孤山旧亭子，凉荫满林樾。","一年一桃花，一岁一白发。","南高看云生，比高见日没。","楚人无羽毛，能得几游越。"]},{"t":"舟中寄江进之得珠帘字 其一","f":"五言古诗","c":["一月探会稽，二月了西湖。","五日登西目，十日瞰天都。","醉中逢山神，长笑捋其须。","渴饮仙人浆，寒分王女襦。","奚囊虽小狭，所贮尽奇珠。","世无售珠人，欲开复踟蹰。","前者道新安，有客貌类胡。","发箧玩三日，略以宝其肤。","具眼非无人，要与慧眼殊。","持此试江郎，江郎售也无。"]},{"t":"舟中寄江进之得珠帘字 其二","f":"五言古诗","c":["一病袁小安，五载江犹淹。","宦味朝朝尽，乡思刻刻添。","有愁到眉棱，无工削爪尖。","枕书调倦眼，照影镊霜髯。","东斋草满径，西堂灰一帘。","鼠子溺书箧，侍儿匿牙签。","少妇乞画眉，双腕痛花佥。","管城头转秃，空闺笑无盐。","俗吏貌态工，末世礼法严。","饶他潘与陶，风流岂得兼。"]},{"t":"过吴戏柬江进之","f":"五言古诗","c":["少年作客时，浸浸慕若长。","干旄络长衢，一呵已神往。","前者为吴令，始复羡游客。","觉彼白衫宽，恨我腰带窄。","今日过吴下，客来官已了。","从头细忖量，客比官较好。","客是一尺雪，官是一窟尘。","欲得客兼势，同年作王人。"]},{"t":"答徐伯润","f":"五言古诗","c":["客径草许长，多君不忘故。","珍重品字书，斜封三尺素。","问我客何方，昨日西兴渡。","问我友朋谁，多半鸥与鹭。","东西南北人，飘落等飞絮。","一叶会冲风，再问知何处。"]},{"t":"赠沈飞霞","f":"五言古诗","c":["江上逢老郎，六月双重布。","瞳人戢电光，飞白写轻雾。","口不绝吟哦，喃喃若有诉。","不知肠几宽，容得许佳句。","黄金类雠人，抵死不相遇。","文章如可典，为君作诗库。"]},{"t":"听朱生说水浒传","f":"五言律诗","c":["少年工谐谑，颇溺滑稽传。","后来读水浒，文字益奇变。","六经非至文，马迁失组练。","一雨快西风，听君酣舌战。"]},{"t":"环翠楼曹平子吴平仲沈飞霞言别得送字 其一","f":"五言古诗","c":["一别能几何，花蹊密成洞。","白石与朱栏，举首即成梦。","一种好心情，都为愁所送。","别意如水寒，六月溪云冻。","聚首复何时，思来当一恸。"]},{"t":"环翠楼曹平子吴平仲沈飞霞言别得送字 其二","f":"楚辞体","c":["归思如奔马，千夫不能控。","溪飞潮雨凉，柳络烟条重。","来时皂盖迎，去惟白云送。","铜章聊一戏，已醒不重梦。","莫以潜之龙，而易衰兮凤。"]},{"t":"潘景升谷日生同诸公小集得谷字","f":"五言古诗","c":["山雪泮冰鳞，江风起罗谷。","十年九羁旅，萍海聚骨肉。","白藕雪冻丝，红鱼剖腈腹。","主人前置罍，醉语颠相属。","华发不回根，羲规无返毂。","只此七尺五，无两三万六。","世儒罟礼乐，为我导君谷。","岂惜一徽言，为君筹已熟。","导君以达生，达是君所足。","导君以忧生，忧非我所欲。","泽广定生龙，山高岂碍鹄。"]},{"t":"过高邮","f":"五言古诗","c":["白浪先孤隍，万室鱼虾气。","居民若水族，来往波间戏。","晓风龙子斗，夜雨蚌精至。","垒石作湖堤，竖栅塘水势。","官家一丈石，民间一斛泪。","治渠如治虏，智士无中计。","千里筑黄金，犹恐西风厉。"]},{"t":"过露筋祠","f":"五言律诗","c":["铁索界黄沙，石羊吹古道。","下有露筋祠，荒螭卧深草。","夜月水花香，西风杉叶老。","空房聚牧儿，蒿根食邻媪。"]},{"t":"过彭城吊西楚霸王","f":"五言古诗","c":["一骓渡江东，猛气不可触。","只手挈河山，英王尽奴伏。","鸿门放亭长，肝肠何煜煜。","猛虎快吞啖，终不噬伏肉。","刘项敌道棋，一先成陨覆。","亚夫真圣眼，西楚亦王局。"]},{"t":"济宁舟中","f":"五言古诗","c":["河口三十仞，悬水如横嶂。","一夜粮船风，送我至南旺。","离家日几何，倏忽易弦望。","水邮无定程，一闸隔天上。","百里飞黄沙，乾风裂绵纩。","蚤与人争席，泥波充五脏。","三十何所成，劳劳密虚望。","如彼上水船，进尺而失两。"]},{"t":"德州舟中清明","f":"五言古诗","c":["俯仰一小笼，焉知弦朔易。","空里跃红妆，始觉清明至。","累累乌角丸，浊香满唐肆。","麦苗鬖马騣，高低叠青翠。","柳嫩碧芽馨，泉煖土膏腻。","空郊逢醉娘，鞦断红衫坠。","客中觅旧题，开卷省前事。","梦里别杭州，一枕西湖泪。"]},{"t":"夜深同伯修月下观梨花","f":"五言古诗","c":["凉月浸梨花，空庭雪数武。","皓质而丰肌，有似京城女。","物忌太鲜明，能保不风雨。","一夕百眄望，眼中生芒镂。","蓟酒鸿空罍，移榻坐阶午。","瓶瓮卧树根，儿童僵柱础。","天攲月渐沉，微微动街鼓。","袖里索讲童，徘徊出亭户。"]},{"t":"暮春同黄无净曹季和黄昭质家伯修游高梁桥","f":"古风","c":["东风织溪面，细纬叠春罗。","长波将人影，直直入宫河。","一万树垂杨，无枝不系珂。","阉贵马嘶风，挟弹睫前过。","精蓝如兜率，朱碧鲜且多。","微沙障西山，罗縠中青娥。","随荫即张席，礼法捐烦苛。","高车载美酒，倾泻若洪波。","?路及严更，门尉稍谯呵。","宪今禁肩蓝，醉卒控疲骒。"]},{"t":"三月二十八日曹季和邀游岳祠置酒灵慧寺中","f":"五言古诗","c":["一缝纳倾城，江河倒瓶瓮。","人肩承马蹄，百里接飞鞚。","神妆金粉鲜，璜壁嵌飞栋。","天家出名香，梅檀作薪用。","掖廷千许人，绯罗刺文凤。","常年三月终，宫监恣献贡。","庭中百怪陈，歌呼殊万众。","趋走稠人场，昏荒如昼梦。","禅寺稍空旷，置酒罗鲜供。","尘埃不到唇，高议窥鸿洞。","席终陈雅戏，钩发每奇中。","西日沉未魄，归鞅尚不动。","醉馀踏高阁，俯视听雷閧。","万古同一裈，安问知与懜。"]},{"t":"宿西山碧云寺水亭上","f":"五言古诗","c":["凉夜水浸梦，枕上吹寒雨。","屡变而失真，江行闻篙橹。","倏然听松风，天月半山许。","举首见仙人，云中捉松鼠。","醒时月桂帘，穷阶流一缕。","石窦激寒淙，空水互吞吐。","日日居朝市，合眼见尘土。","始悟山中人，梦境亦清楚。"]},{"t":"出城观柰子花遇大风至韦公寺而还同游为顾升伯李酉卿家伯修","f":"五言古诗","c":["终日惜奈花，一身苦牵羁。","半月始得行，垂老玩姜姬。","飞鞭出重城，修途会封姨。","扑面吹砂砾，熟马昏路岐。","白日恣狂霾，弥空塞琉璃。","举头触横柳，乌纱罥高枝。","一步一摧折，歇马憩仁祠。","山僧出慰劳，白水泛枪旗。","诸馀小比丘，目腓心刺讥。","未闻看花人，罩眠对春姿。","马疲人亦困，酌酒却宽脾。","不独负花约，兼亦怖天威。","自我入京来，无日不沙飞。","四月双重绵，立夏无春时。","司尹省惟日，愚贱安敢知。","长歌击流水，惊起双鸬鹚。"]},{"t":"古树","f":"五言古诗","c":["树老亦如人，骨劲皮皱裂。","百卉争繁华，一枝冷坳铁。","强阳发空心，红芽吐枯节。","有若老翁醉，赪颐照头雪。","姿态虽寡妍，根株免摧折。","百遍阅春风，冰凌傲石碣。","不似夭桃花，容易与春别。"]},{"t":"送刘都谏左迁辽东苑马寺簿","f":"五言古诗","c":["三年忧国计，髸发飘霜霰。","世事阅飞波，场偶观时变。","辽阳虽左谪，前箸可借便。","昔时风闻者，眼可得而见。","倭奴逼朝鲜，虚费百亿万。","竭尽中国膏，不闻蹶只箭。","东虏近乘胜，虚声震京甸。","我兵折大将，腹背两受战。","辟如相扑人，举手先救面。","弃远固不可，失近岂为善。","公宿负奇策，下马可措办。","志士立功名，不在麒麟殿。","卑官如冶场，英椎听锻鍊。","奇谋若可展，簿尉何足厌。","胸臆不得行，三公犹为贱。"]},{"t":"夏初黄无净邀同项玄池诸公及家伯修泛舟三忠祠","f":"古风","c":["京师百戏都，所少唯舟筏。","御水落漕渠，淙淙流一发。","凡目未经先，虽少亦奇绝。","何况集棠舟，游遨似吴越。","茭蒲得水长，凫鸳避沙热。","朱碧好亭子，稀疏出抹樾。","双航无定质，随波作周拆。","遇树即停帆，因风或回楫。","闸水高十仞，百斛量珠屑。","骏马下危坡，疾雷震空碣。","西门亦有水，宽丈深寸尺。","计较今昔游，居然分胜劣。","长跪谢主人，举酒旌劳伐。","朝日照来骑，?途见微月。"]},{"t":"贞寿诗为冯太史母","f":"五言古诗","c":["宝髻暗尘灰，只凤啼晓额。","举眼望愁空，苍苍不如石。","箧装能几何，典发买书籍。","孤灯瘦形影，寒帏风雨夕。","廿年立孤成，名字照丹册。","宫锦到地红，霜心与头白。"]},{"t":"古诗为杨中翰母中翰生十日而亡其母","f":"五言古诗","c":["十日无知识，那知有慈母。","稍长听人言，一言一酸楚。","辟如少唐儿，原不知乡土。","从人问闾庐，悲咽泪如雨。","哀怨本由衷，焉知涕无从。","一封黄纸诏，十里白杨风。"]},{"t":"别方子公","f":"五言古诗","c":["霜天客病难，何况千里去。","空囊唯败锥，饥程如何度。","客店指煤烟，穷乌啄冰树。","丁丁羸马铃，终夜相伴住。","怀刺二十载，毕竟无一遇。","泻泪忆黄金，相仇复何故。","聪明百倍人，百算百成误。","日日扶摇风，不肯吹飞絮。","天高画戟门，谁是思深处。"]},{"t":"大人寿日戏作","f":"五言古诗","c":["堂前冬青树，霜至叶婆娑。","鸡鸣起衣冠，儿郎盛绮罗。","八十两大家，鬓发如鹭蓑。","微笑动赪颊，鸠秋手摩挲。","平明启扉闼，戚党相经过。","白马系垂杨，云冠高峨峨。","或呈履与襦，或盛练与䋪。","纷纷贫族子，趋走供鹭鹅。","门下诸术人，谀口若悬河。","命宫直田宅，晚子更高科。","东邻老书塾，儒衫衣败荷。","方丈诗一篇，高声自吟哦。","社中诸法友，勉力事禅那。","光阴如电掣，温言相切磋。","二婿白湖来，青衫夹两骡。","入门疾奔趋，不顾坎与坡。","庖丁脍鱼肉，蛮奴治酒醝。","瓮开一径香，决口溜江波。","金绿灿俳优，艳绮列青娥。","开场演蟠桃，牙板随高歌。","袖钱出龚李，浓酒唾曹何。","兰膏尽一斛，上马五更多。","京华宦游子，朝夕思旧窠。","梦中听笑声，一寤出云萝。"]},{"t":"冬夜集顾升伯斋中剧谭偶成","f":"五言古诗","c":["荆火激焦声，釭焰吐红腻。","吴酒贮杨妃，幽香泻荷芰。","格外发狂谭，一呼醒群睡。","凉飔入檀林，败叶皆香气。","人间尘土事，了不关肠胃。","百年深障习，一分留文字。","抽空出妙丝，劈天展高翅。","碌碌彼人奴，馀膻蔽天地。","铅刀笑鱼肠，枭毛遮翡翠。","铸金哭坡仙，百世想标帜。"]},{"t":"戊戌除夕","f":"五言古诗","c":["余夕何所除，匝地除寒气。","除却好年光，不曾除世味。","石小聚香多，垆焦听酒沸。","供佛洗频婆，插瓶鲜老卉。","脱箧理新装，藤纸万馀字。","蜡火照铅丹，如欲见肠胃。","时事不堪书，下笔每惊悸。","道书参谜机，禅理供嘲戏。"]},{"t":"己亥元日晨起","f":"五言古诗","c":["鸡鸣拜圣人，同官六七辈。","绛衫如葛絺，垆香起青蔼。","古柏老于儒，拱揖向庭内。","花气熏一城，沙毂市茫昧。","官卑心亦暇，骑马看年对。"]},{"t":"灯市和三弟","f":"五言古诗","c":["摩肩尽冠簪，呵呼接留酂。","空天蔽帏裳，高衢泥马汗。","古肆列商周，异物穷番汉。","瞠目不能名，横陈失真赝。","僻书与蠹迹，种种觅心玩。","突然发一编，如穷归里闬。","轻纱障朱楼，烟衷露微粲。","笑韵自空飞，幽香度帘蒜。","不觉履綦疲，唯愁眼光慢。","众中虑相失，一步几回唤。"]},{"t":"二月十一日崇国寺踏月","f":"五言古诗","c":["寒色浸精蓝，光明见题额。","踏月遍九衢，无此一方白。","山僧尽掩扉，避月如避客。","空阶写虬枝，格老健如石。","霜吹透体寒，酒不煖胸膈。","一身加数毡，天街断行迹。","虽有传柝人，见惯少怜惜。","惜哉清冷光，长夜照沙碛。"]},{"t":"偶成","f":"五言古诗","c":["入秋寒已来，将夏春未至。","暖气与寒官，相值如相避。","麦田无寸青，山容添老悴。","古梅不敢开，何况桃李媚。","京师重拜客，酬荅有成例。","强起出西街，天风吼涛势。","飞沙涩齿牙，雾眼挥酸泪。","未必诸高官，不省尘霾气。"]},{"t":"看月","f":"五言古诗","c":["良月下空窗，秋水浸缃帙。","寒气迫衣米，垂帷禦风入。","驱风月亦驱，转若麾旧识。","端坐不可忍，强起下檐立。","苦酒呼一杯，聊以宽风力。","不惜待阳和，三春光景失。","永夜伴清晖，寒士寒亦得。"]},{"t":"游满井","f":"五言古诗","c":["出东门子城，古道二五折。","破石蹶荒丘，云是故元碣。","烧柳发柔条，卧槎吐红节。","石沟注涓水，寒鉴泻空洁。","燕女竞游骖，罗袜带春雪。","梅花堆鬋髻，波影动文缬。","青山酣远客，新鸟困啼舌。","红尘视此地，如秽与迷迭。","汲泉烹一杯，肺腑沁香冽。","不惜看频频，可消奔竞热。"]},{"t":"裕陵陪祀示潘尚宝王太学弟小修","f":"古风","c":["长陵一声钟，百官?革厉。","雷鸣集簪裳，空山醒龙蜕。","明月度攲峦，凹影落虚砌。","炬光烁松枝，千鸟展平翅。","红绶老史官，閒语先朝事。","屈指鼎湖年，仙人几回泪。"]},{"t":"崇国寺葡萄园集黄平倩钟君威谢在杭方子公伯修小修剧饮","f":"古风","c":["入门似出门，莎畦布平远。","十亩蕃草龙，垂天棼鬘鬋。","古根老巉石，凉荫厚深巘。","茫茫三夏云，有舒而无卷。","分栋理孙枝，凿泉通小畎。","树上酒提偏，波面流杯满。","榴花当觥筹，但诉花来缓。","一呼百螺空，江河决平衍。","流水成糟醨，鬓髭沾苔藓。","侍立尽酲颠，不辨杯与?。","翘首望裈中，天地困沈沔。","未觉七贤达，异乎三子撰。"]},{"t":"端阳日集诸公葡萄社分得未字","f":"五言古诗","c":["榴花飐清渠，潋潋红波沸。","十里菖蒲风，一幄芰荷气。","行年三十馀，辟若午将未。","乐事竟虚无，劳劳长世味。","试把朱砂觞，一洗滞肠胃。","野性发云岚，粲若新开卉。","世事本閒閒，无端生怖畏。","无论失算非，得算亦无谓。","不有出世人，焉知酒杯贵。"]},{"t":"和钟君威花字","f":"五言古诗","c":["官贫僻冶游，僧贫僻种花。","两贫戏问取，身困意何奢。","数亩葡萄棚，下马如到家。","良朋递指引，佳会屡停车。","竹石能几何，使我心忽遐。","自来悭饮者，咽酒亦如茶。","瓮瓶高累累，腹罄卧平沙。","欢呼达迄半，一里无栖鸦。","藻文沾白帢，禅榻倒乌纱。","衫栏沽酒尽，或恐到袈裟。"]},{"t":"和黄平倩落字","f":"五言古诗","c":["诸君且停諠，听我酒正约。","禅客匏子卮，文士银不落。","酒人但盆饮，无得滥杯杓。","痛饮勿移席，极欢勿嘲谑。","当杯勿议酒，屈罚无过却。","种种皆欢候，违者三大爵。"]},{"t":"和伯修家字","f":"五言古诗","c":["京师盛重五，所在竞繁华。","空庭唯竹石，胜之以清嘉。","藤阴代帷幄，禅板代笙笳。","荷筒当酒盏，药草当名花。","栝柏四五株，胜彼百髻丫。","风篁数枝响，陋彼百淫哇。","彼歌此呕喁，质朴类田家。","区区起免俗，白酒渍红砂。"]},{"t":"和方子公童字","f":"五言古诗","c":["方生老为客，往往狎青童。","下马揖平头，兴发如飙风。","瘦骨载野心，一饮百馀钟。","微波照颠影，线偶系虚空。","十阄七负觥，脱冠语篁丛。","从君文字饮，辜负石榴红。"]},{"t":"和小修扫字","f":"五言古诗","c":["禅客恶花繁，引水植香草。","迸阶多子篁，栖树无凡鸟。","碎日摇空庭，波纹如可扫。","鹦鹉与凫鹥，自邻自社保。","客来非习静，偶然合大道。","一味出林风，销尽诸尘抱。","止酒但止甘，聚朋先聚老。"]},{"t":"吴人求别诗","f":"五言古诗","c":["闻名不识面，胜于识面者。","未晤先惜别，形骸翻是假。","京师沙砾场，风光少秀冶。","乐事尽输吴，蓟酒独难舍。","空囊何所恋，身轻等飞瓦。","夜雨潞河风，秋郊吴苑马。"]},{"t":"节寿篇 其一","f":"五言古诗","c":["三十年藐诸，一顾一呜咽。","泪湿琐窗花，红紫也成雪。","穷巷苦书声，孤釭语寒铁。","敝帙三五箱，字字殷痕血。","垂老课儿官，霜花冷白发。","湘湖千顷莼，不敢饷儿侄。","母贞益子廉，源清者流洁。","辟如干霄筠，稚笋亦高节。","翚锦落天花，万古水潭热。","乡邦传盛事，似作昔贤说。","试检孀娥编，女史难为烈。"]},{"t":"节寿篇 其二","f":"五言古诗","c":["立孤丈夫难，何况妇也只。","裹泪看零丁，忍作山头石。","熊窗闭孤影，几曾见天碧。","夜雨丝络声，穷巷丘轲籍。","尺楚起雏皇，长风老劲翮。","五载萧山令，空斋类禅客。","近雪无缁流，何况霜自白。"]},{"t":"七月二十一日有忆偶题","f":"五言古诗","c":["雾月晓花啼，柳冷莺梦怯。","石枕刻相思，秾香散幽帖。","清思如静水，红从笑颊起。","背灯换溽衣，倩郎收珰珥。","别泪浸兰被，恩爱等蝉翅。","银箸拨香灰，写作天长字。","塔灯绕层橑，红阑对大道。","昔时合欢场，今见高冢草。","枫根闻鬼语，乡音带淮楚。","淰淰女鬼神，吹作何山雨。"]},{"t":"伯修斋中同汪参知诸兄共谭","f":"五言古诗","c":["石瘦盆池清，竹冷秋窗茜。","只数本蓼花，亦复添幽艳。","贤朋三五人，肝胆皆如面。","宝月舍琉璃，无心不可见。","摩砻若许年，宦网增尘罥。","学道不出缠，如以䞓加茜。","辟诸生矿金，渣汁少陶鍊。","毛孔薰旃檀，庞公以为鉴。"]},{"t":"赠王以明纳赀归小竹林","f":"五言古诗","c":["读书三十年，何曾效一字。","九万里冲风，不能起蝉翅。","人间龙子藏，天上司文睡。","质书典青山，勉就冬官例。","凤老泣枯梧，强作回翔计。","低枝无伟巢，聊减冲云气。","掷巾簪笋皮，脱衫买荷芰。","万竹中栖身，崖风吹远唳。","销心白传诗，遣老庞公偈。","铁锥题令篁，画破千竿翠。"]},{"t":"十景园小集","f":"五言古诗","c":["一门复一门，墙屏多于地。","侯家事整严，树亦分行次。","盆芳种种清，金蛾及茉莉。","苍藤蔽担楣，楚楚干云势。","竹子千馀竿，丛稍减青翠。","寒士依朱门，索然无伟气。","鹤翎片片黄，丹旗榜银字。","鳀锦裹文石，翻作青山祟。","兑酒向东篱，颓然索清醉。"]},{"t":"崇国寺同王章甫小修看月","f":"五言古诗","c":["凉月白霜阶，光腻平于砥。","古木坐寒禽，写影空窗里。","牙刀劈沉心，云母熏红纸。","茶垆藏古云，一叶寒吹起。","角灯抽紫焰，冻花老瓶水。","滑波映琉璃，一片冷光死。","灰心伴夜弹，寒猧吠行履。"]},{"t":"宿千像寺柬钟刺史","f":"五言古诗","c":["诘曲攲呕路，皱秀透瘦石。","飞岩绣铁花，螺子点云额。","平生米南宫，耽幽穷鬼迹。","石根搜古云，踏遍秋空碧。","豁眼见新峦，长笑落巾帻。","贪看不知晚，悬石布奠席。","回首神仙吏，青嶂达门阈。","侍史朝焚香，秋云几回白。","棱棱怪石供，聊以施游容。"]},{"t":"盘山","f":"五言古诗","c":["分明真山子，的的有画意。","风霜匀粉丹，云霞缀锦地。","一皴一百仞，雕镂入空际。","瘦骨间青脂，苍劲有馀媚。","天绅秣项垂，仙蕊披裆被。","虬松百万株，粘石无根蒂。","峰峰有活石，石石挟仙气。","一石玉一山，一山一点翠。","散作诸峦岩，分身可千计。"]},{"t":"盘山顶","f":"五言古诗","c":["摩天抽碧篸，俯不见鸟背。","西日照塔轮，影落重边外。","峨髻瘦仙人，玉冠苍水佩。","貌古骨奇青，见者肃而拜。","浮空日嬲云，足底呈光怪。","或聚或披丝，或舞或澎湃。","千里听风铃，飞花落膻塞。","一萍一青山，一点一人界。"]},{"t":"游天门关","f":"古风","c":["发足自髻石，湾还可四里。","一步一惊魂，路荒不容趾。","粘壁行刀脊，下视深无底。","狂锷搆虚空，痴石缀瘢?。","其沙生以坟，其骨污而泚。","其草油以丝，其树糟而圯。","忽然硗确岩，忽然崩腾水。","忽而没九天，忽而九渊起。","健夫引长绳，半日一移趾。","四肢互相用，臂行足以视。","或如鸭折身，或如丁旋尾。","或如鷇出壳，或如蟹引跪。","又如研古绘，虫蠹蚀丝理。","又如读殷盘，聱轧饤奥诡。","当其快心意，虚空跃绳妓。","少焉筋力疲，蚊虻撼犀兕。","须发生烟岚，肌肤碎荆杞。","百苦到天门，相对惟口哆。","双壁削青铜，飞鸟不能止。","一匣衔古光，方空如水洗。","阴阳工刻轹，霜雪恣摩砥。","万古贮云霞，石纹绣青紫。","鉃桐蛇腹段，古钮蛴螬蠡。","诘曲史籀画，斑驳朱砂蕊。","僧言三十年，兹石未沾履。","往时戚将军，架空一游此。","长老传白猿，今来猿亦死。","是时七月初，寒肌如粟子。","引指人人危，回身面而鬼。","归来问僮仆，髭须白馀几。","破网取珊瑚，判命竞奇傀。"]},{"t":"赠大宗长老","f":"五言古诗","c":["鬡发茁霜根，精神出骨上。","能令见者心，自发幽岩想。","西山万螺青，得意即孤往。","履崄若平陂，宽衣不持杖。","道逢破衲人，长跪必合掌。","除却身口外，一钟无馀镪。","经行达曙鸡，念珠长五丈。","净月含宝瓶，彻底皆澄朗。"]},{"t":"初入红螺崄","f":"五言古诗","c":["凿天出古空，意匠穷刻露。","赎取长吉魂，幻作鬼工赋。","霜岩透斑锷，石骨竦清怒。","历劫至于合，彫镂不曾住。","无石不巧心，转眄殊态度。","一种老健中，自发嫣媚趣。","阴巘夹琉璃，飞仄窘仙步。","一死直青山，梯足于悬树。"]},{"t":"真定大悲阁同王六宇年兄及小修弟登览有述","f":"古风","c":["一盘三十级，低窗平鸟翅。","空里约数盘，始尽金色臂。","碑文深藓痕，历历隋唐字。","树老北朝根，霜绣生古翠。","飞题接绮疏，斑驳有奇致。","斗古不斗鲜，真丹无两寺。","凭虚吊古人，触眼伤新事。","拥?一谈空，稍蠲忧时泪。","忆初直省时，把手青卿地。","光华若春条，白面青丝髻。","尘土十年馀，䰄毛添老悴。","面皮堆浪纹，阴忧如有蒂。","少年可喜谭，入口皆无味。","相延低两眉，但欣?林计。","莲花求主人，长誓作兄弟。","沐猴暂衣冠，了却开箱戏。"]},{"t":"游石洲","f":"五言古诗","c":["江神发幻思，十里金沙变。","白波荡琳球，云灿复霞溅。","头头螺甲青，点点妖唇茜。","殷殷玛瑙云，丝丝交背面。","风沙谁刻画，霜雪几陶炼。","暴精万馀年，今始叹光绚。","乡人陋莫知，骚客远难见。","付之蛮贾儿，凿火激流电。","辟如倾国人，埋没在乡县。","灵壁与将乐，下质得高荐。","荔枝未登科，百果争娇艳。","开卷读云林，续作石潭传。"]},{"t":"和官谷馆字","f":"五言古诗","c":["云以竹为邮，雪以梅为馆。","君看竹多处，无阴云亦满。","将雪近柳条，柳意自疏缓。","一种漠漠思，尽属寒花管。","侬与君亦然，气味同老懒。","冷澹足生活，不向睛处暖。"]},{"t":"雨久初晴","f":"五言古诗","c":["梅花吐冷魄，竹子舒烟尾。","晞影落寒檐，微微苔甲起。","向虚置楷床，卧听鸠妇喜。","发垆熨古灰，一片沉心死。","乍闻邻塾言，儿童摊润纸。","乳鸟背窗啼，花间掠红紫。"]},{"t":"题伯学斋居","f":"五言古诗","c":["竹子居数梢，且有干云势。","斋居足丈馀，迂回有馀地。","閒花不用多，一株两株腻。","闭户矣沈心，石眼通云气。","卷中秋水波，画里春山意。","晞影生浪纹，衣光沈冷翠。"]},{"t":"游庐山初入东林雨中","f":"五言古诗","c":["穷天刻冷翠，浓雨洗幽青。","湿云坼西岭，坐见武吕晴。","远公昔庵此，莲花漏初成。","岩窦列宗雷，石梵彻天清。","想像醉五柳，颠颓望釜铛。","旷心闻法语，啼儿畏锦嫦。","达哉远师鉴，礼法怜祼裎。","客儿虽百醒，不以易一酲。","千二百岁后，白藕无根荣。","莲宗启未社，唐子惭道盲。","掬流浣尘貌，寒潭吹古腥。","山僧如石瘦，莲堂空几楹。"]},{"t":"天池寺","f":"五言古诗","c":["山以云为邮，云穷山身见。","石貌呈巧心，瘦妍竞奇变。","暄凉隔下天，葛絺易柔练。","一石一狂呼，前石翻为殿。","万仞瞰畸云，倏缕倏飞片。","抚松坐枯岩，一往谢尘罥。"]},{"t":"游佛手岩至竹林寺","f":"五言古诗","c":["以手摩苍霞，终古搏秋碧。","掬取九江流，浇空洗云魄。","茫茫竹林人，斑花生古额。","坐断沧海烟，日月如穷客。","引领见长眉，及至化苔石。","一往号菁林，髭须如云白。"]},{"t":"途中怀大兄","f":"古风","c":["十宵九入梦，明明知已逝。","识得中阴来，未审寄何位。","前者四月初，恍忽上忉利。","光容若平昔，天服粲游戏。","伸纸与我读，奇文千馀字。","梦中了了知，醒后都不记。","曾闻释子言，天乐稍浓腻。","若非道种深，未免天色醉。","记兄初生时，大姑兆奇瑞。","丽人跃空飞，姑也承以袂。","苦旅思乐宅，返促亦何异。","但恐冶心多，减却道人气。","少日念欢场，鸣泉奔渴骥。","一卧三年茵，肌消如寒猬。","从兹稍谭仙，习静学观鼻。","朝坐一丝香，暮禅半幅被。","閤门杜色声，精神转强锐。","蒙庄不去手，卓有出尘志。","几年客金马，渐识宗门事。","乞差既里还，刻苦相摩砺。","旦寻复昏披，研惟空有谛。","有如群婴儿，搩手量鹏翅。","突闻物格言，石火掣飞燧。","惑魔虽暂歼，狂使方为厉。","挈疑过龙湖，息求而得刺。","一自直东华，先鸡每戒睡。","日夜抱一编，形神俱焦瘁。","眼涩如有沙，舌乾无厚味。","国本既艰危，臣也难为退。","余时官闲局，弟也负书至。","每当聚首时，言必穷幽邃。","毒语攻沉疴，当机无回避。","俱悟昔时非，驰马歇狂辔。","净侣偕数人，结期向北寺。","下直即停车，六时声如沸。","合掌化如来，白毫与青髻。","东林十八贤，高举标奇致。","披此尘劳衣，缚人如鸟罻。","便欲脱簪绂，指彼青山誓。","或假或休沐，次第作?计。","余也先群飞，入山选幽翠。","结茆四五间，日日眄归帜。","梦魂总不及，逝也一交臂。","严亲头触石，聚哭空里肆。","海内学道人，千里缄酸泪。","弟也冒雪行，十日走枭骑。","不忍见京华，何况旧邸第。","寡妇一屋声，天地为阴曀。","立后以祈年，殷哀方小替。","传闻四月终，白旐出淮泗。","余也偕诸衲，奔帆如云驶。","念公闻我来，追至寻阳际。","十日抵瓜仪，南北舟相次。","肝肠恸一割，石火迭相谓。","富贵竟何成，金毛不如薙。","十载无生学，劈莲微见意。","痛呼隔闻尘，天高日西坠。","前者潘去华，梦中忽见示。","生平四良友，君家得其二。","赖兹切摩力，今亦生善地。","信我同心人，冥墨亦相缔。","祠之柳浪馆，凡与白苏四。","天上虽酷乐，勉来一竖义。","破矿出精金，刬却知见祟。","携手入莲邦，沙劫为兄弟。"]},{"t":"汉阳萧仲子参知山亭清话","f":"五言古诗","c":["平平数点岫，大水发妖倩。","鳞鳞万室瓦，以山增奇艳。","檐际织波纹，盌里落霞片。","风樯对岸出，人影隔江见。","是日云态繁，薄阴与晴战。","漏光缬水花，净眼生微眴。","三山五湖舫，只此大江面。","几人厉霜刀，割尽闲尘罥。","无发可留青，何绳堪系电。","为问橘皮仙，江渚几回变。"]},{"t":"舟中偶成 其一","f":"五言古诗","c":["何云贱胜贵，贱死悲易止。","何云顽胜智，顽者多寿死。","暗女与妍天，相去不盈起。","欲得截忧愁，先须断欢喜。","行年三十馀，稍稍窥兹理。","视官如舍邮，等子于衣履。","舍邮非不住，断不悲移徙。","衣履非不著，无心计华侈。","深谷既悭缘，闹途且停趾。","出世我不能，免作劳薪尔。"]},{"t":"舟中偶成 其二","f":"五言古诗","c":["冶媱岂不见，见之如青峦。","丝肉岂不听，听之如鸣湍。","听水无荡思，爱山无热颜。","辟如怀抱儿，絜手弄金丸。","山鸡眩其影，竟死白波间。"]},{"t":"人日同度门发足上玉泉 其一","f":"五言古诗","c":["烧却门符纸，匝地竞如蚁。","青眉稚齿儿，堂上诵夫子。","余也亦皇皇，趁时治山水。","瓢笠共山僧，缁衣附行李。","是壑即吾居，是云即吾市。","逸思触东风，吐若争春蕊。","冒霜遵脩途，十里黄埃起。"]},{"t":"人日同度门发足上玉泉 其二","f":"五言古诗","c":["西眉东衡匡，天公赐我履。","道远不能从，玉泉且经始。","几年说堆蓝，未语颊先起。","梦中见青溪，石泉带雪洗。","叠身智者洞，和我先乡里。","乡人说乡事，真切弥可喜。","问我氏伊何，作讲堂者是。"]},{"t":"白香山二十四岁作感时诗余今正其时矣仍次其韵","f":"五言古诗","c":["少年沐新发，郁若青莎地。","一朝盆水中，霜缕忽三四。","辟如百里途，行行半将至。","视老犹壮容，比少已憔悴。","是身如肉邮，皮毛聊客寄。","微宫复寄身，寄与寄为二。","浮云崎太空，种种非作意。","鳞鬣及鬘鬟，散时等一气。","为乐供朱颜，及时勿回避。","青山好景光，花木饶情致。","我有战老策，胜之以无累。","胸中贮活春，不糟自然醉。","虚舟荡远波，从天作升坠。"]},{"t":"天柱峰谒帝","f":"五言古诗","c":["除却善法堂，人间无此丽。","甍题铸黄金，玉版花纹地。","羲和曳长轮，锐碧返笼辔。","霞里召仙官，飞断青溪翅。","茫茫诸夏人，绡绮被山翠。","号呼夹笙镛，醒却天娥睡。","燔珠薪水沉，千里薰燎气。","长髯老真人，晓畅天家事。","逸典绝云亭，功高七十二。","鞭山驾鼋鼍，一笑秦皇帝。"]},{"t":"南岩","f":"五言古诗","c":["珠题嵌绝辟，人巧依天匠。","峭绿叠颓岚，青天怯磨荡。","濛濛太始云，旷劫相酝酿。","一自辟玄宫，斧作仙家障。","苍峦夹攲窦，高天入盆盎。","终古容清虚，诸仙几回丧。","真人将上升，先此规图样。","十二楼五城，某天如某嶂。","宫成付黄冠，仙邮侈供帐。","道装俗须眉，只此输天上。"]},{"t":"游玉虚岩","f":"古风","c":["一壁绣烟霜，石老??露。","蜕骨留空岩，青山也仙去。","或纤削而清，或高古而怒。","瘦过必成妍，喜极多由怖。","咽者为奔白，沽者为杉树。","种种出天成，幽奇互遭遇。","翘首告仙真，此地好流寓。","未必三神山，有此奇绝处。"]},{"t":"月下","f":"五言古诗","c":["明月照我身，宿鹭熟吾貌。","床几落柯文，临风忽一笑。","净月贮空潭，如以照衔照。","递互发光明，幽阴洗晴耀。","面石张枯桐，自发凄寒调。","疾风传远林，万类振清窍。"]},{"t":"薙苇","f":"五言古诗","c":["柳塘三十亩，茭苇翳其半。","寒毛与垢瘢，蚀却青娥面。","童子厉镰刃，飞光激流电。","疾风卷残枯，倏忽青天见。","照我池上人，露髻白团扇。","芰荷一族风，碧水千丈练。","送能入东溪，招鳖过西堰。","鳞介授族行，知有蛟龙遁。"]},{"t":"秋夜坐月水轩同龚散木刘绳之赋","f":"五言古诗","c":["一线露云棱，微光漾青树。","空翳与庭昏，总被风吹去。","虚栏当水心，是月流连处。","频夜厌清光，衣衫浣花露。","世间浓冶物，到眼即成故。","无地不追随，只似如今遇。","空阶攲瘦石，寒影清而怒。","试问月中妃，鸡皮凡几度。","抛却射乌儿，亿载牧寒兔。"]},{"t":"谷日小集五弟春草堂得谷字限韵","f":"五言古诗","c":["七尺捐酒杯，一笑三万六。","红袖间缁衫，烟水叠丝肉。","花光薰冷云，溪纹纬春縠。","宁为去水鸥，不作在樊鹄。","帘波捲青天，高空堕寒玉。","铁板鹍鸡弦，长歌倚脩目。","柳浪千本柳，腰肢舞不足。","诞傲胎众讥，达者以为谷。"]},{"t":"舟中望黄山","f":"五言古诗","c":["识面二十年，登临才半次。","濡雨出层岚，未曾留一字。","青山笑主人，何事近相易。","墨潘汗巉岏，数尽他家事。","主人忽沉想，为君搆幽丽。","兀然三四峰，反覆无可记。","孱陵一万家，家家立生翠。","倍远倍高寒，淡冶如秋睡。","昔我登郡楼，微芒见葱髻。","越三峡而南，千里尽平地。","见培塿则喜，何况发姿媚。","见色不见山，此是山三昧。"]},{"t":"九日登高河洑山","f":"五言古诗","c":["高阁俯苍崖，下有花源路。","料得避秦人，入山从此去。","潭水洗山肤，肤尽红霞露。","老蛟挟瘦石，千古盘涡怒。","溪上尽渔郎，谁识花流处。","事往白云新，人去青山故。","挂却茱萸囊，长啸倚丹树。"]},{"t":"穿石","f":"五言古诗","c":["溪上望穿石，攲悬如瓮子。","石底望溪山，山山如镜里。","平平翠叠中，一峰夭矫起。","淡与奇相值，幽艳忽无比。","鬼斧凿天真，刻意出新诡。","一处幻玲珑，千崖灿花蕊。","虚空不受云，飞仙无停趾。","唯有地籁风，终古来游止。","时时随落花，飘渡秦人水。"]},{"t":"水心崖","f":"五言古诗","c":["狞龙负巨山，一往冰潭睡。","春沬与秋澜，洗尽青山蜕。","石肤鉴水光，递互发清丽。","转盻分瘦妍，生动各有意。","我欲举铁网，拔出珊瑚翠。","付与种桃人，置之花深地。","他时携枰来，石上聊一戏。"]},{"t":"桃花源和靖节韵","f":"古风","c":["一笑叩烟岚，白云今几世。","桃花不肯流，溪水无情逝。","?开浑沌亡，朴散羲黄废。","青山一舍邮，仙家偶来憩。","白头老黄冠，茧手事耕艺。","呵呼随里胥，鞭笞了官蜕。","岫老鹧鹄斑，溪流琉璃吠。","日供冠裳驺，宁晓芰荷掣。","缅想紫芝人，骖云几相诣。","洞府帘堂深，云霞空凛厉。","天人一昏旦，人间百馀岁。","宇宙何不有，谩劳作聪慧。","迂儒饱世情，俗肠非境界。","纷纷辨伪真，等为方内蔽。","常闻列子风，可以驾烟外。","长驱入仙林，编觅心所契。"]},{"t":"集小修筼筜谷偶成","f":"五言古诗","c":["东家贷蜲屏，西家贷华烛。","髻鬟错巾冠，欢场稍秾缛。","虚窗淅沥风，四围遮被襆。","凉月荫丛枝，十亩莎庭绿。","主人季次贫，衣马欣驰逐。","三秋客渚宫，百金倚吴肉。","归来双羞囊，风枝扫空屋。","徵伎列樽罍，情侈欢不足。","幸有万竿篁，寒梢泻春渌。","荡尽管弦心，豁开烟岚目。","何处觅清歌，微风戛修玉。"]},{"t":"夜坐读少陵诗偶成","f":"五言古诗","c":["尝闻工书人，见书长一倍。","每读少陵诗，辄欲洗肝肺。","体格脩六经，古雅凌三代。","武库森戈戟，庙堂老冠佩。","变幻风云新，妖韶儿女黛。","古鬼哭幽冢，羁游感绝塞。","古人道不及，公也补其废。","他工有遗巧，代之以覆载。","仅仅苏和仲，异世可相配。","剪叶及缀花，诸馀多琐碎。","纷纷学杜儿，伺响任鸣吠。","入山不见瑶，何用拾琼块。"]},{"t":"十二月十七日五弟初度","f":"五言古诗","c":["任运阅年光，不识支平易。","但闻蜡梅香，知弟生辰至。","二十八番花，一开一回丽。","读尽古人书，识遍天下事。","家世安国学，铁砚工文字。","无射不穿杨，一往看联辔。","屈指兔目花，黄时甫再岁。","千里宿舂粮，养就天池翅。"]},{"t":"人日自笑","f":"五言古诗","c":["是官不垂绅，是农不秉来。","是儒不吾伊，是隐不蒿莱。","是贵著荷芰，是贱宛冠佩。","是静非杜门，是讲非教诲。","是释长髸须，是仙拥眉黛。","倏而枯寂林，倏而喧嚣阓。","逢花即命歌，遇酒辄呼簺。","一身等轻云，飘然付大块。","试问空飞禽，澄潭影何在。","旷哉龙屈伸，颓焉方外内。","下惠本介和，夷逸乃清废。"]},{"t":"新晴","f":"五言古诗","c":["鸡鸣听远钟，凄清入寒峤。","晓枕气微暄，纷纷檐鸟笑。","花香乍袭人，窗涌一痕照。","温风泫露光，尘敛青天耀。","逸思如系鹰，系解心浩浩。","出门见平湖，流水清面貌。","村酤白瘿杯，沿堤呼所好。"]},{"t":"初春暴热过静者居限韵","f":"五言古诗","c":["花气郁春蒸，下马脱吴绫。","坐看缃格下，时有朴纱蝇。","罄口与木笔，非时联作朋。","雏篁茁垐齿，冶叶被苍藤。","间蝶趁风廊，香须沾其膺。","似彼青娥子，梦亦恋花缯。","盆池供瘦石，斜幌隐龛灯。","回风逆香缕，袅袅青烟腾。","研丹窜今文，时轨裂轲曾。","云山刻骚士，秾香恼定僧。"]},{"t":"庵中阅经示诸开士","f":"五言古诗","c":["乘急参媱女，戒急怯闻钗。","香象截河流，一非刬众皆。","闷观百喻经，奇胜十齐谐。","八十翁怜儿，庄语间诙俳。","我愿作书鱼，死即藏经埋。","胜彼火坑子，以身殉粉娃。"]},{"t":"喜王以明自村中来宝方官谷限韵","f":"五言古诗","c":["骨交削浓茜，气交和水盐。","魂交破幽石，空天彻捲帘。","十日九缄题，秋水扃方奁。","锐毛刻云山，巧镂百戈铦。","东风鼓蚓窍，发义小言詹。","勉自角妍媸，青娥突老髯。","樱桃本凡品，况乃经燎腌。","高枝荫寸毛，贞名滥宫阉。","铸铜哭瘦岛，一往何李纤。","摇头钝优孟，竖儿口可钳。","女态非瘦肥，茶韵出香甜。","泻我倾肠波，蛲蛔如可拈。","应龙乘高云，细鬣舞盆噞。"]},{"t":"别王以明用前韵","f":"五言古诗","c":["一室闭冷云，花月摈无盐。","兀坐生泉石，榻风吹水帘。","花斑绣青铜，夜夜吼红奁。","微言破尘缕，厉彼昆刀铦。","野梦牵墟落，松寮丽省詹。","空潭侣水影，垂竿揖枯髯。","往往抽栗尾，拾鲜弃其腌。","当其隽发时，叱盲排马阉。","秀句传活水，死语遭夷歼。","骚家心恍惘，玄子口吃钳。","异物乖今直，时味饱软甜。","穷怪铸九鼎，等以一毛拈。","尺水昂巨鳞，吐沫聊自噞。"]},{"t":"五弟新卜园居余笑曰柰物力不敷何社中遂以为韵作诗嘲之仍限四章各四韵 其一","f":"五言律诗","c":["斫红裁粉竽，作意缀春物。","长短称身难，贫儿贷朱绂。","百畹贮虚空，买破秋烟郁。","莫似杂花林，卜庵典古佛。"]},{"t":"五弟新卜园居余笑曰柰物力不敷何社中遂以为韵作诗嘲之仍限四章各四韵 其二","f":"五言律诗","c":["凿地出方空，日费十蛮力。","东溪招鹭鸶，西溪捕锦鶒。","束腹耨青畦，图租云母食。","墙屏列胸中，日夜几雕刻。"]},{"t":"五弟新卜园居余笑曰柰物力不敷何社中遂以为韵作诗嘲之仍限四章各四韵 其三","f":"五言律诗","c":["螺子洗春云，空塘系瘦鹄。","柳烟不蔽条，遮得鸦雏不。","裁剪湘波纹，苍根删古玉。","附僧觅紫绵，筠笼客西蜀。"]},{"t":"五弟新卜园居余笑曰柰物力不敷何社中遂以为韵作诗嘲之仍限四章各四韵 其四","f":"五言律诗","c":["石钥扃春风，篱棘森戈殳。","閒云不隶馆，任意逻门窬。","天花烂僧祴，逼眼霞纹敷。","缊衣裹小蛮，茆茨享淳母。"]},{"t":"迎春日舟中宴坐限韵","f":"五言古诗","c":["妖靓乐芒神，荆俗乃不典。","缩头乱牍中，通身如藏茧。","面窗理瓶梅，幽香度前艑。","野心似绿梯，一夜遍春畎。","劲风破长云，飞片落如剪。","霜管刻春容，铁心寄婉娈。","信手抹溪藤，霞舒而云卷。","生俟山翠浓，青天策疲蹇。","花草与翎虫，作意为敷演。","梦里题玉泉，枕上百回辗。"]},{"t":"入春屡作雪不见梅花仍用雪中韵作古诗悲之","f":"五言古诗","c":["寒花如古玉，未出屡遭刑。","幽魂欣冷石，怨入楚骚经。","置驿报花安，未晓心先听。","梦到讯不到，浇炙瘦园丁。","雪心胶蜡蒂，乱结如顽硎。","安得鹤膝枝，一洗龙脑腥。","扫室待天女，㓗水贮空瓶。","枕上见罗浮，诸仙门反扃。","菊格与兰韵，于汝犹鹡鸰。","纷纷缛桃李，奚啻渭与泾。"]},{"t":"采桑度","f":"五言古诗","c":["姊妹行四五，朝朝行采桑。","素丝络笼底，光艳大道傍。","去年采桑迟，今年采桑早。","只愁蚕不熟，误我嫁时袄。","采桑复采芝，照水湿罗衣。","欢自不吞华，牵侬百丈丝。"]},{"t":"过二酉师旧斋","f":"五言古诗","c":["士老不曾官，女老不曾媒。","无媒知真性，不官见隐才。","守道七十载，寂寞类寒灰。","逢山遍瑑句，得黍即衔杯。","笔绝知麟获，人亡为国哀。","科斗馀文字，残书化草莱。","马鬣封三尺，文翁安在哉。","空斋遗杖履，长叹续归来。"]},{"t":"从军行","f":"五言古诗","c":["百金装宝刀，千金买骏马。","投鞭瀚海陲，系马阴山下。","骆驼吼如云，黄羊阵满野。","胶劲弩牙酸，霜重角声哑。","虏女貌如花，提刀向空耍。","白乳滴葡萄，千钟一时泻。"]},{"t":"道傍柳","f":"五言律诗","c":["浓叶藏晓鸦，青条挽游骑。","天株大道傍，阅尽行人泪。","风搅玉蛾翻，烟亸长眉醉。","本无别离心，行人自憔悴。"]},{"t":"寄子髯","f":"五言古诗","c":["结发治诗书，交情沥肺肝。","十年事熊胆，何止千馀丸。","文字挟飞霜，千顷跃波澜。","白发秃似冢，青云路转艰。","举网珊瑚易，投珠明月难。","闲情寄鱼鸟，小筑避暄寒。","过雨常移竹，当窗学种兰。","兴来摹柳字，愁至裂囚冠。","蹶足怜骐骥，冲天羡凤鸾。","愿借扶摇力，为君送羽翰。"]},{"t":"过毛太初见二甥","f":"五言古诗","c":["朝见卫叔宝，朗朗来照人。","髻发若青丝，楚楚足精神。","作对才五字，遽有惊人辞。","下筹读左史，酌酒诵唐诗。","阿舅无长处，素心差足师。","居官万不可，谈艺一无知。","尔父敦俭朴，山居伴鹿麋。","郗公诚晚令，育长恐情痴。","似之非贤者，不肖乃佳儿。"]},{"t":"述怀","f":"五言古诗","c":["少小读诗书，得意常孤往。","手提无孔锤，击破珊瑚网。","香象绝众流，俊鹘起秋莽。","淫僻畏仁义，竹止羞罔两。","灭火事长途，何处税归鞅。"]},{"t":"梦子髯","f":"五言古诗","c":["渺渺山行路，青石荷盘盘。","男儿念同袍，诀绝伤肺肝。","同袍入我梦，展转忽无端。","欲言不能陈，俛首但长叹。","踏雪穿松径，长笑倚朱栏。","四顾无僮仆，云气黑漫漫。","挥手辞我去，突发无巾冠。","出门三两大，当道吠君还。","前日送君行，君言举体酸。","今宵梦若此，得无小未安。","觉来三叹息，举首泪阑干。"]},{"t":"狂歌","f":"五言古诗","c":["六藉信刍狗，三皇争纸上。","犹龙以后人，渐渐陈伎俩。","嘘气若云烟，红紫殊万状。","醯鸡未发覆，瓮里天浩荡。","宿昔假孔势，自云铁步障。","一闻至人言，垂头色沮爽。"]},{"t":"答李子髯","f":"五言古诗","c":["若问文章事，应须折此心。","中原谁掘起，陆地看平沉。","矫矫西京气，洋洋大雅音。","百年堪屈指，几许在词林。","草昧推何李，闻知与见知。","机轴虽不异，尔雅良足师。","后来富文藻，诎理竞修辞。","挥斤薄大匠，裹足戒旁岐。","模拟成俭狭，莽荡取世讥。","直欲凌苏柳，斯言无乃欺。","当代无文字，闾巷有真诗。","却活一壶酒，携君听竹枝。"]},{"t":"为官苦","f":"五言古诗","c":["白羽落青松，玄霜化秋草。","燕市多冲飙，日暮红沙道。","男儿生世间，行乐苦不早。","如何囚一官，万里枯怀抱。","出门逢故人，共说朱颜老。","眼蒿如帚长，閒愁堆不扫。"]},{"t":"丽阳驿题壁","f":"五言古诗","c":["近驿辩语声，人驿如而貌。","昔当岁祲时，驿人奔浩浩。","牵爷负男女，南出荆门道。","公安弹丸地，饥儿相号召。","佣力及赁舂，经历几寒燥。","幸尔值稔年，次第还井灶。","乡音半相杂，衣服宛然肖。","道傍垂白翁，昔见年犹少。","见我感且泣，壶浆相迎劳。","垂头语老翁，邑中今苦涝。","洼田无寸收，高乡有虫耗。","部符搜宿逋，县家敢迟鷔。","鬻田田不售，儿女输官钞。","壮者思逃移，沟壑生难料。","此乡小有年，敝邑敢相告。","愿作庑下儿，驿人勿嘲笑。"]},{"t":"邺郡梦中诗","f":"五言古诗","c":["枕上见青天，明月光流地。","空水色相函，千里无停翳。","微云起天末，缭绕忽成字。","或散或披丝，或累若椎髻。","属思尚未竟，候人催解辔。","携梦入征途，马上犹啽呓。","翘首望漳河，停鞭思魏帝。"]},{"t":"夏日过葡萄园赋得薰风自南来","f":"五言古诗","c":["移席就佳荫，萧散去巾带。","南风倏然来，令我意通泰。","是风如好语，妙契心所会。","又加渴时泉，一吸沁肝肺。","是风何所有，凉云与清濑。","虽然经市嚣，冷冷意自在。","禅宫有废圃，植槿以为柴。","虚旷多容风，雨具不须贷。","尔我虽云贫，尚能施扫洒。","更施无系心，鼾声震地籁。"]},{"t":"三教堂诗为杜总戎日章","f":"五言古诗","c":["支公好骏马，俗以为不韵。","头陀手铦戈，标格乃白俊。","将军起马上，铁腕风雷迅。","朝踏雪山冰，夜眠青冢燐。","豁然悟无生，心花见锋刃。","辟如担夫争，见者笔意进。","关捩偶相触，石火不容瞬。","归来读诗书，如暗得灯烬。","堂堂三圣人，同宗偶异胤。","刻影求飞鸿，雾耶自生晕。","白水涌冰轮，千江同一印。"]},{"t":"方子公自真州入燕客死清源诗以哭之","f":"五言古诗","c":["贫死何足悲，所悲为贫死。","奄奄一息身，奔驰二千里。","泣辞钟山云，梦渡吕梁水。","百死到凊源，闻歌犹蹶起。","新诗四五帙，函封寄杨子。","蛇蚓不成书，获麟止于此。","世相簿屡空，冥官岂相礼。","气类自呼召，往见东野鬼。","赢博即故乡，首丘端可已。","肥马轻裘魂，谅非君所喜。"]},{"t":"秦中杂咏 其一","f":"五言古诗","c":["荒草披秦殿，秋花缀汉城。","我行南山道，如阅古图经。","遗迹依稀是，长老失其名。","一步一伫思，断垒谁缔营。","又如稽蠹简，冥搜损心精。","虽以意推求，边傍非故形。","西都赋所载，一一尽歌倾。","飞燕旧舜处，田夫扶来耕。","沉香旧亭子，湖石尚娉婷。","清风发虚窍，其中有性灵。"]},{"t":"秦中杂咏 其二","f":"五言古诗","c":["吊古意不禁，披搸倚断枝。","道逢雪岭叟，笑我真情痴。","尔从京师来，习见汉官仪。","未央即宫阙，金马即铜墀。","团营即细柳，绮陌即庄逵。","西山千万髻，终南同崔巍。","下有高梁河，即古曲江池。","瑶台与金屋，所贮即妖姬。","残棺断火垄，即今金紫儿。","辟彼膏烛光，前者已灰飞。","后火续新火，焰焰同一辉。","若以天眼观，青草生蛾眉。","飘风遇轻云，无事哭荒碑。"]},{"t":"靳尚祠","f":"五言古诗","c":["骨谗犹可忏，舌惺岂不悔。","佞鬼亦相容，始知佛如海。","至今篱落下，不忍种兰茝。"]},{"t":"别无念","f":"五言古诗","c":["五年一会面，一别不惨然。","只消三回别，便是十五年。","念我志参学，黄杨木子禅。","百遍听师语，终不破纠缠。","辟彼生肓人，生不识紫朱。","告以朱何似，转告转模糊。","别师既不忍，留师复苦难。","十月江风多，留毛盖脑寒。"]},{"t":"别丘大","f":"五言古诗","c":["世人等閒聚，亦复等閒别。","我辈会非常，别宁不痛切。","天荒古木寒，愁老石皮裂。","十月江上风，酸却行人辙。","常年别妻儿，道我肝如铁。","今夕送君去，化作红炉雪。","荆树掇皮真，竹子到头节。","万里黄州程，一步一心折。"]},{"t":"白乳泉","f":"五言律诗","c":["一片青石棱，方长六大字。","何人妄刻画，减却飞扬势。","泉久污泥多，叶老鎗旗坠。","纵有陆龟蒙，亦无茶可试。"]},{"t":"送梅子马督木北上","f":"五言古诗","c":["男儿但得志，何必知阶级。","往者三殿灾，梓人进公秩。","督木数万里，杞梓被天黑。","长年千许人，餐餐损邮食。","目今事戎马，公私敝已极。","减得一丝毫，便是竭心力。","雀飞无劲毛，不若蛟有翼。","爱君才调好，部署有规则。","气猛而肠刚，幕府中难得。","此是有用人，终堪事绝域。"]},{"t":"别袁中夫","f":"五言古诗","c":["梁鸿伯通桥，中夫陆家带。","都是失意人，一般滞吴会。","汉水虽方广，不能浮一芥。","孤桐既以摧，穷凤复何赖。","回首吴松江，冲风折车盖。"]},{"t":"哀殇 其一","f":"五言古诗","c":["弱腕系金铃，青丝绾偏髻。","胸前两绣囊，犹作长命字。","欠尔三斗乳，偿汝一升泪。","稚魂半尺馀，荒荒投旅次。","我尝静坐思，生死同一例。","子既光我行，即是鬼先辈。","如彼排场人，尊卑乃相递。","一去与一来，孰知非天戏。"]},{"t":"哀殇 其二","f":"五言古诗","c":["逆旅投主人，不待卸鞭箠。","颜尘尚未浣，已渡向他之。","来如风过林，去若鸟辞枝。","细鬼胜巨人，量汝必有知。","吾欲痛哭汝，恐汝笑吾痴。","辟彼筵宴时，朱紫栉巾綦。","一宾偶先去，诸客尽歔唏。","去者固太早，歔者亦何迷。","转眼即天明，请君听鸡啼。"]},{"t":"梦诗","f":"五言古诗","c":["梦国不离枕，枕上觅不得。","当其在梦时，有枕亦不识。","醒里梦元空，梦中醒亦灭。","安知醒天地，无枕在其侧。","梦醒若循环，谁幻复谁实。"]},{"t":"大游仙诗","f":"五言古诗","c":["朝菌羡蟪蛄，既为物所诮。","众庶慕长生，道宁不窃笑。","仙视人则长，道校仙则夭。","长短埋归尽，计量抑何小。","千秋万岁后，人事殊可晓。","无非霜露代，及以日月杲。","天如覆口铛，民若浮根草。","礼法厮牵缠，干戈叠搅扰。","百年犹恨多，矧歌不衰老。","所以过量人，希心无上道。","不贪绝粒方，唯贵虚无宝。","外身而身存，此是长寿考。"]},{"t":"经太华 其一","f":"五言古诗","c":["天地如文人，精华不可刊。","而其秀杰气，常在水与山。","华山翠天表，五岳让高寒。","当其匠意时，百灵穷肺肝。","琢以月天斤，洗以银浦澜。","抺以洪濛烟，照以日月丸。","十二楼五城，处处映青鬟。","尝恐诸仙人，鹤辔憩此间。","天风刷毛羽，千里佩珊珊。"]},{"t":"经太华 其二","f":"五言古诗","c":["昔闻华山名，今见华山貌。","何时陟微茫，遍偿宿所好。","手搴青芙蓉，玉女隔花笑。","数尽仙掌文，唤醒希夷觉。","少时耽子墨，颇识徐熙妙。","幅绢对青山，临崖亲写照。","不取色态妍，唯求神骨肖。","俗黛与凡霞，无事点幽奥。","断岩著孙登，虚空发清啸。"]},{"t":"邢州道上大风","f":"五言古诗","c":["南风捲地昏，拗折道傍树。","吹面如有痕，欲拔髭须去。","此地足黄沙，易作风神怒。","冈陵忽变迁，老马不知路。","日暮憩邮亭，颜面都非故。","盆水贮渗泥，双眼出烟雾。","诘旦过沙河，未至心见怖。","何事太行山，酣沉了不寤。","岂无一掬波，浣此秋空污。","梦中排九阍，芒履沾云絮。","投箠击眠龙，惊起如飞骛。"]},{"t":"饮方渭津斋中","f":"五言律诗","c":["山斋多快事，弹棋角杯斝。","卫水齧墙流，瓶中鬼帆泻。","鱼鹰窥笔床，溪花乱枰马。","开帘触新韵，高吟对梧槚。"]},{"t":"避俗","f":"五言律诗","c":["一朝见俗子，三日面生尘。","所以薰修客，长年如畏人。","买丝绣高士，栽松作比邻。","不有沧溟水，马得横海鳞。"]},{"t":"送峨嵋僧清源时源请有檀香佛刻镂甚精","f":"五言律诗","c":["师从峨嵋来，往返经几宿。","兹山闻最高，几许到天竺。","师行遍天下，无乃是神足。","竦身入梵宫，镂此旃檀佛。"]},{"t":"黄梁祠","f":"五言律诗","c":["八番邯郸道，半世卢生枕。","滚滚枕中人，渴名如渴饮。","羲皇北窗下，所乐唯甘寝。","祗恐纷竞多，敝坏我席衽。"]},{"t":"可道人影赞","f":"五言律诗","c":["生既将不来，灭岂将得去。","欲识师真身，问取阶前树。","手中枯木枝，脚下芒草屦。","面皱而神清，是师苦心处。"]},{"t":"白鹿泉","f":"五言律诗","c":["方池一尺馀，池复深无几。","一双金鲫鱼，旷若游海底。","小骨冻秋云，波面香石髓。","但论活不活，安问浅深水。"]},{"t":"戏题飞来峰 其一","f":"五言古诗","c":["试问飞来峰，未飞在何处。","人世多少尘，何事不飞去。","高古而鲜妍，杨雄不能赋。"]},{"t":"戏题飞来峰 其二","f":"五言古诗","c":["白玉簇其巅，青莲借其色。","唯有虚空心，一片描不得。","平生梅道人，丹青如不识。"]},{"t":"感兴 其一","f":"五言律诗","c":["白日不可晚，黄金不可为。","夙心探玄理，幽与白云期。","众芳经春歇，秋草过时萎。","富贵非所欲，经丘以为师。"]},{"t":"感兴 其二","f":"五言律诗","c":["贪夫竞荣利，不顾头上霜。","书生谈不朽，眉宇争昂昂。","生前秦项鹿，死后臧谷羊。","所以逍遥叟，栖志沉墨乡。"]},{"t":"感兴 其三","f":"五言律诗","c":["道逢一古叟，开唇论紫朱。","方上而锐下，将无是鲁儒。","鲁国有微言，儒者窃其肤。","家家飨五城，谁辨鱼目珠。"]},{"t":"感兴 其四","f":"五言律诗","c":["俗尘近不得，远之亦为弋。","扰扰色界里，具足清净人。","何边超梦幻，无法过贪嗔。","曹丘一滴水，自然智慧津。"]},{"t":"别黄道元","f":"古风","c":["驿路柳条如鞭，江上奔帆似马。","两荡聚首许时，兴阑各自归也。","明春有事天台，便过龙湫度夏。","公家半宦半儒，卜居在城在野。","雁场或东或西，双门之上之下。"]},{"t":"叹镜","f":"七言古诗","c":["湖州镜子开生练，昨日红颜今皱面。","只道镜子不长情，谁知我面时时变。","背文回合双蛟戏，千钟粟锦藏鸳翅。","阔眼方鼻浅翠纹，古籀盘屈乌银字。","拂拭旋生缕缕烟，摩挲喜得重重翠。","古往今来半尺铜，人间多少伤心泪。"]},{"t":"东阿道中晚望","f":"七言律诗","c":["东风吹绽红亭树，独上高原愁日暮。","可怜骊马啼下尘，吹作游人眼中雾。","青山渐高日渐低，荒园冻雀一声啼。","三归台畔古碑没，项羽坟头石马嘶。"]},{"t":"少王郎为王幼度作","f":"七言古诗","c":["寒气如山压霜重，珠阁银金连晓动。","吹笙十五少王郎，手搦青梧拴綵凤。","秃衫浅揖无宾主，满握青烟喷白麈。","金炉霍霍狮子鸣，腻烛双双芙蓉吐。","乳花如雪滴春香，百刻无多情则长。","西施入越夷光死，鹦鹉无魂鸳断肠。","丽娃宫里苔三尺，旋拂遗綦嗅蚕迹。","古井晶瑩恼杀人，梦里行云谁到席。"]},{"t":"惠山僧房短歌","f":"七言律诗","c":["山骨连墙粘碧筱，穴苔自种吉祥草。","茶到三钟也醉人，花无百枝亦藏鸟。","少年长老姿格清，竹炉莲卷古先生。","东风不道禅心定，吹入山头环佩声。"]},{"t":"迎春歌和江进之","f":"七言古诗","c":["东风吹暖娄江树，三衢九陌凝晓雾。","白马如龙破雪飞，犊车碾水穿香度。","铙吹拍拍走烟尘，炫服靓妆十万人。","罗额鲜妍棼綵胜，社歌缭绕簇芒神。","绯衣金带印如斗，前列长官后太守。","乌纱新缕汉宫花，青奴跪进屠苏酒。","采莲舟上玉作幢，歌童毛女白双双。","梨园旧乐三千部，苏州新谱十三腔。","假面胡头跳如虎，窄衫绣裤搥大鼓。","金蟒缠胸神鬼装，白衣合掌观音舞。","观者如山锦相属，杂沓谁分丝与肉。","一络香风吹笑声，十里红纱遮醉玉。","青莲衫子藕荷裳，透额垂髻淡淡妆。","拾得春条夸姊妹，袖来瓜子掷儿郎。","急管繁弦又一时，千门杨柳破青枝。","独有闭门袁大令，尘拥书床生网丝。"]},{"t":"江南子 其一","f":"七言律诗","c":["鹦鹉梦残晓鸦起，女眼如秋面似水。","皓腕生生白藕长，回身自约青鸾尾。","不道别人看断肠，镜前每自销魂死。","锦衣白马阿谁哥，郎不如卿奈妾何。"]},{"t":"江南子 其二","f":"七言律诗","c":["白玉蒙沙花出泥，东家老汉得娇妻。","少年不道妾心苦，夜夜门前乱乌啼。","妾心甘作井底水，郎君错走路旁蹊。","谁家门前无鹞子，归去且自看家鸡。"]},{"t":"江南子 其三","f":"七言律诗","c":["蜘蛛生采解织罗，吴儿十五能娇歌。","旧曲嘹厉商声紧，新腔啴缓务头多。","一拍一箫一寸管，虎丘夜夜石苔暖。","家家宴喜串歌儿，红女停捘田畯懒。"]},{"t":"江南子 其四","f":"古风","c":["湖蚕吐练光如水，叶娘夜织金阊里。","熟作绫绒生作纱，桃尽虫鱼与花蕊。","年年宫样换新机，一虫能作几?丝。","父当解户兄塘长，官家头运五月时。"]},{"t":"江南子 其五","f":"七言律诗","c":["白面青髭美少年，朝役五木暮摊钱。","百千一注不洗手，赢来赌取少娃眠。","男儿作事勿偃蹇，黄金博尽终当转。","莫道腰间无一文，闺中少妇犹堪典。"]},{"t":"美人睡起词","f":"七言律诗","c":["莺舌般般学人语，隔溪唤醒厌春女。","宝枕花酣龙脑云，粉香晕透猩红雨。","花前软步询鹦鹉，欢醉归来时几许。","开妆重点圣檀心，夜明帘外金沙吐。"]},{"t":"兰舟引","f":"七言律诗","c":["东风染就蓝花水，刀鲭十寸青带子。","鵊鶄衔母下滩眠，闻歌一翅冲烟起。","入扇风香白芷苗，钩衫刺短迷阳蕊。","尽船楼橹䠞波来，美人一茇虾须里。"]},{"t":"西阊女儿歌","f":"七言律诗","c":["西阊女儿芳菲早，秾华一树为君老。","根株憔悴可惜人，和枝生折鸳鸯草。","东风一夜䠞娄水，又逐王家双燕子。","莫道杨花无定踪，吹来还入旧窠里。"]},{"t":"巷门歌","f":"七言古诗","c":["猫竹为墙杉作城，白日赤丸盗公行。","官军防禦无计策，逐户排问乎土兵。","卫尉呵持急如虎，老弱十家充一伍。","本是市上佣工儿，身无尺籍在官府。","东家黄金高于天，食指盈千皆少年。","朝朝门前科子母，何曾饶得半文钱。","富见积财贫儿守，父老吞声叹未有。"]},{"t":"春晓曲","f":"七言律诗","c":["兰灯蕊绽白光残，隔花呼起夜歌鸾。","琵琶转捩娇无力，博山欲炷龙脑寒。","眉稍散黛重重拨，额角轻黄正正安。","侍儿不语流莺语，海棠沉睡赤栏干。"]},{"t":"述内","f":"七言古诗","c":["世人共道乌纱好，君独垂头思丰草。","不能荣华岂大人，长伏蓬蒿终凡鸟。","富贵欲来官已休，儿女成行田又少。","盈箧算无千个铜，编衣那得一寸缟。","陶潜未了乞儿缘，庞公不是治家宝。","玉白冰清欲何为，不记牛衣对泣时。"]},{"t":"答内","f":"七言古诗","c":["少年读书求富贵，白手青云能自致。","屈首空云事已成，到头转觉官无味。","一尺刚肠五尺身，我非儿女宁拜人。","莱子有妻终是隐，原宪无病莫忧贫。","我腕如绵面似纸，未得一钱先羞死。","书生无才不解贪，不是将身比秋水。"]},{"t":"湖上","f":"七言律诗","c":["流莺舌倦语初歇，画峦微点梨花雪。","茶叶白抽四五旗，竹孙班裹两三节。","芳草如绵陷归辙，花气薰人醒不得。","落红雨过更愁人，六桥十里猩猩血。"]},{"t":"第五泄","f":"七言律诗","c":["银河夜长天堤绽，空中现出琉璃变。","电布云奔一派垂，山都昼吼白龙战。","四壁阴阴吹雨足，画峦活舞玲珑玉。","天孙夜夜踏歌来，一曲飞珠二万斛。"]},{"t":"赠模上人","f":"七言律诗","c":["头发如霜气如虎，栏杆十路挞生虏。","手挈头颅百颗归，不曾半粒食官府。","而今老来无气力，县家明文防镰贼。","空房夜雨刀瘢寒，儿孙骄呆去不得。"]},{"t":"沈母篇为萧山令沈广乘年兄赋","f":"七言古诗","c":["女霜五月流空槛，碧海无波白日敛。","赎得遗编苦教儿，泪作笔花血作点。","头白眼酸轲名立，部疏得报温纶及。","转将深痛畏儿知，当面堆欢背面泣。","湘湖水白萧山青，花光云片满公庭。","惭无一钱将供母，闭门亲写法王经。"]},{"t":"过云栖见连池上人有狗丑韭酒纽诗戏作 其一","f":"七言律诗","c":["钱塘江上云如狗，一片顽石露粗丑。","苦竹丛丛本岭烟，毛松落落千行韭。","道旁时榜赵州茶，室中不戒声闻酒。","更问如之与如何，便是颈上重加纽。"]},{"t":"过云栖见连池上人有狗丑韭酒纽诗戏作 其二","f":"七言律诗","c":["少年曾盗子胡狗，父母不容亲戚丑。","每到僧房索布衣，更向佛头种葱韭。","读书十年未识字，持戒三生不断酒。","恁有一般可笑人，逢著师尼便解纽。"]},{"t":"题潘生小像生嗜酒时将别","f":"七言古诗","c":["潘生肉颊权微起，面貌长在酒杯里。","何人倾出酒波来，洒向溪藤五尺纸。","忆昨逢君黄山道，窄帽单衫立深草。","江上追随又一年，缸面瓮头几回倒。","殷勤留取箧中身，别后看谁先瘦老。"]},{"t":"漂母祠","f":"七言律诗","c":["刘宗火冷寒灰灭，浣衣墩上蘋花热。","一饭王孙直许钱，消得鸾刀几回血。","荒街日夜走黄尘，西风酸断石麒麟。","笑他白手女天子，不及沙头愚妇人。"]},{"t":"燕子楼","f":"七言律诗","c":["空窗画掩红纱隔，一夕温风长葵麦。","秋去春来双燕儿，年年衔粉扮妆额。","芍药死枝不死根，焉知黄土不青春。","幽魂异日逢杨柳，应悔生前别舍人。"]},{"t":"子房山谒子房","f":"七言律诗","c":["莲花冠子红犀导，雪面风髯一年少。","梦里山河博几场，抽身笑拈长松道。","英雄老尽故交稀，眼底修毛几翅飞。","功成辟谷或有以，未必神仙须布衣。"]},{"t":"为杨粉署题小像","f":"七言古诗","c":["鹅溪冷绢花纹涩，四尺春波次粉墨。","幼舆岂非丘壑人，笔底潇疏谁貌得。","高人气韵不在似，如写寒松与幽卉。","宽眉廓额信手涂，疏淡只似铺山水。","马迁文章杜公诗，此意却许徐熙知。"]},{"t":"花朝日伯修初度","f":"七言古诗","c":["红花点点灼青树，开尊正值花无数。","不知庚甲是何年，但道桃花开几度。","玉堂署里课葵蔬，鸳鷟池边领鸥鹜。","新年诗兴更勃勃，墨汁淋漓染绢素。","惊雷忽发万山芽，俊鹰陡落平原兔。","一束牛腰足自骄，九陌飞尘何所慕。","花下兄弟睦州禅，梦中烟月油江渡。","拟把天竿随丈人，不向天家作师傅。"]},{"t":"长陵","f":"七言古诗","c":["长髯真人别天上，鹄驭龙骖辔千丈。","毵毵风鬣滴烟香，空山夜语姚和尚。","霜街寂历吰松子，皂衣落落穿十里。","小臣有语叩龙鳞，地老天荒呼不起。","溪藤瘦石碧昂藏，马蹄踏水炬煌煌。","千年山骨凭搜取，当日龙沙战几场。"]},{"t":"夏日同江进之丘长孺黄平倩方子公家伯修小修集葡萄方丈以五月江深草阁寒为韵余得五字 其一","f":"七言律诗","c":["落花点地成重五，香翠熏泥粉沾雨。","买将安石伴炎官，鬼书未燥花先腐。","当窗一榻卷琉璃，下方五月吹寒楚。","姬公且自却门檐，茗椀沤花生白缕。"]},{"t":"夏日同江进之丘长孺黄平倩方子公家伯修小修集葡萄方丈以五月江深草阁寒为韵余得五字 其二","f":"七言古诗","c":["下里诗人唤阳五，酒肠窄窄无一缕。","空拳往往博欢场，如以孤羊角群虎。","一蕉入口即槃姗，浪言欲作糟丘主。","天幸酒伯多知音，嵇阮贺李相推许。","酂留岂必解披坚，不饮何妨建旗鼓。"]},{"t":"和丘长孺","f":"七言古诗","c":["藤荫朵朵碎光白，古寺閒房坐佳月。","白家曲子规如珠，沉宫棹羽吹香雪。","五言七言信手成，刻雾裁风好肌骨。","节根处处觅糟丘，逸思迸如春草发。","世人三十进愁乡，眼睛直视胸怀结。","天生荡子惯穷途，客囊冰冷心犹热。","官既无门名不有，尔纵不言我心折。","眼中知己尽青云，不能拔汝一毫发。","七尺身材五尺臂，雕弓往往穿金铁。","贫贱熬人亦自难，许身何苦太高洁。","埋却中山十斛毫，猎尽撩天千里鹘。","射虎韝鹰一健儿，无成何用空吻舌。","莫辞低头拜大人，溺间胯下真豪杰。"]},{"t":"和方子公","f":"七言古诗","c":["酒困伤脾色昏沉，下马呼水煎人参。","皆云昨宵倦苦极，动以狂药相规箴。","须臾瓮香扑鼻来，初犹矜持渐浸淫。","尊隤罍决不可止，突若一群狂猩猩。","脱帽掷天呼石语，苍旻不高海不深。","至我酒人天下乐，宁有醉死无醒生。"]},{"t":"和江进之","f":"七言古诗","c":["一尊相对叹枯老，出囚人逢他乡道。","但令脱梏即华津，宁论官高与官小。","剡溪藤纸百匹长，渴骥惊蛇惟一扫。","霜根忽地破东风，千山万岭生青草。","閒水閒山处处行，刻尽云烟与花鸟。","娃宫胥庙武丘山，别后新函寄多少。"]},{"t":"和伯修","f":"七言律诗","c":["西风罥藤如罥索，急雨穿棚如穿幕。","树梢投地水溅珠，葛衫吹上毗卢阁。","乍黑乍丹云态多，骤寒骤燠天公疟。","热席得雨亦快人，愁杀山僧卖花萼。"]},{"t":"和黄平倩平倩有文君盘出以行酒","f":"七言古诗","c":["临卬酒垆卓氏盘，携向禅堂醉里看。","橘皮蟹瓜未足云，分明远山秋水寒。","残膏剩馥沾唇吻，引得青娥入肺肝。","世远物微不可知，且欲借此为乐瑞。","百盘一吸无遗沥，奔注有若顺风湍。","醉中逸思不可止，援却老僧新竹竿。","书空卜丈作凰字，平地跃跃飞生鸾。"]},{"t":"显灵宫集诸公以城市山林为韵 其一","f":"七言律诗","c":["仙人杰阁俯王城，西山见雨北山晴。","高云直接薰炉气，去宫百里闻铃声。","古柏石干青虬枝，烟绡千尺屋十楹。","东边奈子结老友，却忆往年梅客生。"]},{"t":"显灵宫集诸公以城市山林为韵 其三","f":"七言律诗","c":["琳宫高处见西山，浓翠隐约高低鬟。","几年桑孔算云烟，人间峦石无苍颜。","白云向我意潸潸，欲从平地乞休閒。","东郊西陇皆官亩，判取虚空任往还。"]},{"t":"显灵宫集诸公以城市山林为韵 其四","f":"七言古诗","c":["松棚不阔浓浓阴，池沼不宽滟滟深。","宾朋不众尽同心，言语无多足知音。","三伏自然消暑气，何用深山嘉树林。"]},{"t":"显灵宫夜归","f":"七言古诗","c":["云头黯淡色如铁，扑衣打面旱沙热。","六街泼墨气腾腾，几点风灯鬼明灭。","铃铎当当辨古寺，走入衲僧蚕纸被。","堕瓦抛椽雨阁眉，雷公腕脱车轮碎。","长风捲地天吹坼，一星透出层云额。","马蹄依旧送冲飙，炬火不光天路窄。","电光熠熠谱华缯，细如姬发粗如绳。","云山花鸟各呈态，天女飞丝绣不成。","人言闪电是天笑，天翁何事频欢叫。","嫦娥归魄织女藏，顽墨昏肓有何好。","北安门外水沉路，溜点在檐雨在树。","果然隔辙分晴阴，雨师似亦相回护。","归来门巷无灯烛，北奴鞭婢旋煮粥。","墨花一泻满吴笺，残雨疏疏滴檐竹。"]},{"t":"丘长孺醉歌和黄平倩","f":"七言古诗","c":["广陵细酒真珠沸，瓮花决决倒河渭。","研朱泼面火生肌，离身一里闻糟气。","初如渴骥奔鸣泉，渐如怒虎吞脔胾。","乍如山石压一丝，又如云絮泊空际。","须臾变幻如偶儿，乍孤乍末恣俳戏。","又如分身作数人，口耳心神不目制。","旋风著树刺钩藤，郭郎舞袖张颠字。","口中牵丝舌力蹇，千言不能达一义。","酒人讳醉强惺惺，容貌矜持礼法赘。","强将拜跪学常人，不觉攲身落崖砌。","千扶万拥不能支，吻中微闻呼白二。","檐溜丁丁滴到唇，举手推屋若辞醉。","一酣三日昏如泥，齁声吼若惊涛至。","天然一幅浑沌图，人间械路争回避。"]},{"t":"德胜桥水轩集诸公诗","f":"七言古诗","c":["西山去城五十里，紫巘青逻见湖底。","一泓寒水半庭莎，赚得白云到城里。","茭叶浓浓遮雉朵，野客登堂如登舸。","稻花水渍御池香，槐风阵阵宫云凉。","一番热雨蹙波沸，穿檐扑屋生荷气。","乍时泼墨乍清澄，云容闪烁螭蛟戏。","帘波斜带水条烟，北窗雨后梦清圆。","兑将数斗薏仁酒，赁取山光不用钱。"]},{"t":"避雨崇国寺三日纪事","f":"七言古诗","c":["湿云涨山雨不止，一酣三日葡萄底。","天公困雨如困酲，醉人渴饮似渴水。","东市典书西典几，团糟堆曲作城垒。","明知无雨亦不行，权将雨作题目尔。","仆夫安眠马束尾，大瓮小瓮来日起。"]},{"t":"戏赠死心和尚死心以秀才出家","f":"七言古诗","c":["铁城焰里热忙身，几人能掷头上巾。","题将百八金刚子，辞却东家老圣人。","少年意气非等閒，精悍之色在眉间。","镕取鱼肠一匣水，铸作胡僧双耳环。","往年湖上逢开士，藻月规烟说文炜。","但知北海是大儿，谁识南宗印真子。","海内学士闻行履，半说颠狂半惊死。","东方先生代解嘲，秀字何妨竖却尾。","瘦岩百尺突寒松，冰谷千年贮古水。","落花红洗入溪澜，请看风吹起不起。"]},{"t":"月夜登良乡塔冈与子公诸友作别","f":"七言古诗","c":["秋水潋潋滴青雾，城外人家城里树。","白埃一道冲红亭，正是马蹄离别处。","荒垣残叶几家村，千厓洗尽月波痕。","乡关十路九貂虎，未知托钵向何门。","惊禽一羽分烟去，云路沉沉安可论。"]},{"t":"赵州观水壁忆真际和尚","f":"七言古诗","c":["幻士幻入水三昧，博取天河作手戏。","跳珠回沬五尺馀，王成草木掀涛势。","古佛堂前柏树子，半裂空心半髡死。","荒檐龙钟几病僧，日暮空垣拾菌耳。","堂头老像如冰冷，寒碑月写风枝影。","石栏狮子向东啼，夜深唤却虚空醒。"]},{"t":"赋得斜风细雨不须归","f":"七言古诗","c":["莫釐山上亭如盖，纽取蒲梢作衣带。","丝烟细雨著罗窗，墨树浓山泻生绘。","农家閒记月毛生，贾舟怕见江猪拜。","是处皆将笭箸行，谁家不得刀鲚卖。","云脚才封马迹山，轻雷忽过吴淞界。","湖州万户入青煤，七十二峰如钱大。","餔糟一枕钓竿眠，不觉风波在船外。","派派烟岚刺眼眉，折折云山锁心肺。","誓将白水洗缨尘，何用浮云生肌疥。","为君屈指开元年，高冠大纛几人在。","一湾艇子一竿丝，不学成都先生卦。"]},{"t":"夜卧青王峡看月","f":"七言古诗","c":["渴虹饮石夜蛟哭，寒屑霏霏洒蕲竹。","一湾净月趁斜峦，堕向龙宫写幽独。","鹍弦断尽铁槽平，石韵高寒谱不足。","头毛索索罥人长，几时买断青崖腹。","五更凉梦泊孤云，以手扪天如苍玉。"]},{"t":"出城至大别寺题壁","f":"古风","c":["汉阳山上閒峦少，汉阳城中人又老。","娟眉雪齿竞浮荣，几人头上无青草。","荒坟如粟秋山下，嗷嗷鬼母诉长夜。","山中老矣头佗行，白骨堆中起精舍。","汉阳城，如掌大，壮士激矢穿城过。","试登高阁数行人，阔帽青衫凡几个。"]},{"t":"舟中夜话赠马元龙","f":"七言古诗","c":["十年不作沙头客，旧时昵好头尽白。","偶然湖海订新知，久语寒泉落幽石。","白沙著月水澄天，一面吴绡滑令碧。","垆声沸尽火销灰，不觉西窗堕寒魄。","世儿啾啾弄吻舌，豆火不光他自窄。","等閒搩手量青天，枉把虚空记寻尺。","天池九万自乘风，不以蜩鸠损劲翮。"]},{"t":"荆州前苦雪引","f":"七言律诗","c":["鲛民老困输绡苦，私向龙宫贩云母。","百驮夜经瞿唐门，峡鬼骑鱼诉天府。","鲛户十窜九囚虏，泪不成珠天帝怒。","骨白粉焦委黄泥，至今荆州唯白土。"]},{"t":"荆州后苦雪引","f":"古风","c":["东皇放晴亦不恶，何事飞雵巧穿凿。","入市不填万井饥，积峡推助江神虐。","蔬盘日日嚼冰丝，岂有羊脂充??。","扑窗打幔十日落，千门无路贷金错。","厨断烟销牙齿阁，下方自苦天自乐。","玉娘斜坐抱双脚，仙官云吏供嘲谑。","东海盛醑黄姑酌，天狸夜窃九关钥。","倒骑狞龙捶金络，羲和上书翻见缚。","丁令无官化飞鹤，吁嗟天公待民何其薄，野人扶曰觅沟壑。"]},{"t":"春江引","f":"七言律诗","c":["浓烟抺尽春沙暖，锦云炙日鸳鸯满。","斜岚扑地夜鬟香，较取卓家黛深浅。","苔光匀绿堆春简，尺阑题尽折枝短。","桂桡一划破青天，办取藤鞋踏山眼。"]},{"t":"哭刘尚书晋川","f":"古风","c":["记相识，相识黄鹤楼。","当时椎齿青衿子，平揖方伯古诸侯。","书司曹佐敛手愁，公也置几头拄头。","饮我酒，庭幽幽，千秋如火烧红榴。","东眺晴川西鹉洲，少年桃达躁如猴。","枕肱叠膝百自由，攲杯画箸恣嘈休。","尔时山翁问余言，乘兴遂作洪山游。","中间离合苦不定，长别已经十春秋。","去年三弟山东来，道公貌腴骨力遒。","百八串珠不离手，言谈清简风飕飕。","未几传公病，又传已小瘳。","昨者度门从淮返故里，亲见白旐黄肠出济州，使我泪眼如江流。","三日欲语不得语，枯咽喉。","海内学道几人在，转眼辄为天所收。","去年哭潘去华，又哭我先伯脩。","河枯岳折星辰死，凤凰不鸣鸣鸺鹠。","天公于世岂相雠，或者精光透泄不宜久，高贤大才理当归一丘。","呜呼既知归一丘，何为银章绯袍白头恋著不得休。"]},{"t":"和东坡梅花诗韵今年雪多梅开不甚畅为花解嘲复以自解云耳 其一","f":"七言古诗","c":["世人斗丰不斗槁，瘦而能立胜肥倒。","世人相喜不相愁，浊快岂若清烦恼。","寒花遒逸花典刑，不与天乔论繁早。","艮株虬曲干横斜，总令无花格也好。","山茶肥腻鸾腮红，蒲柳轻微娼黛扫。","孤清妁月婢春云，白石苍崖相对老。","只将黄发领芳菲，忍令高姿伴花草。","山中夜逢萼绿华，骑著么凤上青昊。"]},{"t":"和东坡梅花诗韵今年雪多梅开不甚畅为花解嘲复以自解云耳 其二","f":"古风","c":["花神一夜色枯槁，主人八门愁绝倒。","夜深花叹似人言，主人百事重花恼。","一者庸工剪束繁，二者丑女折戴早。","三者头上宁著老鸦啼，不愿俗子相怜好。","晒裈遗失主不知，花落青苔任帚扫。","算缗立券坐花前，无酒无诗送花老。","孤山事我若仙妹，君之视臣如芥草。","主人百拜谢花神，过不即芟如春昊。"]},{"t":"和东坡梅花诗韵今年雪多梅开不甚畅为花解嘲复以自解云耳 其三","f":"古风","c":["主人被谑如摧槁，空庭百匝愁颠倒。","抗颜也作花忠臣，摘叶披枝恐花恼。","贮君玉照金谷之堂，山骄石佞君开早。","贶君和羹驿使之辞，调卑格弱君言好。","我无红碧为君妍，莎台莓榭躬除扫。","宋砚蜀纸李廷圭，折枝貌得花韵老。","荣枯开落等一观，自觉与花非草草。","月沉风止两无言，一方积雪照冥昊。"]},{"t":"虎耳岩逢不二和尚","f":"七言古诗","c":["幽岩幻出支公面，瘦壁玲珑点葱茜。","百年一室锁青烟，涧石霜松几回变。","师言少日住西山，南内风光眼曾见。","武皇七年四月时，搭衣曾上戒坛殿。","白头等死入名山，四十三年若流电。","榔梅插得大十围，又见曾孙头似霰。","夜深屈指数朝贤，青山阅人如邮传。","元美伯玉今在无，可惜聪明死编撰。"]},{"t":"隆中偶述","f":"七言古诗","c":["苍藤老蔽幽溪石，瘦锷棱棱网苔迹。","想得山中抱膝时，凉云如水树纹碧。","山莎满地刺花红，草堂斜掩一池风。","杖声跕跕冲山鸟，道是鹿门庞德公。","开尊叠唱梁甫吟，黄头丑妇拔钗篸。","踏花趁石穷幽崄，行尽溪桥闻怪禽。","一朝龙甲腾色水，尽泻清江浇玉垒。","西连邺虏东狡吴，坐策行筹几回死。","晚年只手扶庸主，文泣鬼神战风雨。","炎火不光汉数穷，消得英雄愤几许。","五丈原头石辗尘，烟霜薮却白纶巾。","始知伊吕萧曹辈，不及餐云卧石人。"]},{"t":"黄平倩至玉泉以书见要倍道趋之马上感旧有作","f":"古风","c":["晓枕浓和发清嚏，知是佳人呼我字。","翩然一鹤自东飞，衔得巴江笺子至。","蜡花满幅堆明峦，要我共踏青溪翠。","怒帆一掣截长波，马不待?捶以辔。","颓蓝叠绿泻平田，缬林稠叶点清腻。","当时京国好兄弟，射堂佳月城西寺。","几年抛没叹吹云，又作飞鸿留爪地。","老去怕逢缘熟人，梦回每说金华事。","欲知销折几番心，看我衣衫重叠泪。"]},{"t":"赠陈正夫","f":"七言古诗","c":["学书不成去学剑，抛却铅丹买弓箭。","六韬不直一文钱，穰苴终作灌园汉。","稻黍不收收莠荑，勉将方口救穷贱。","古纸烟黄书一通，赤日方街磨大砚。","涔波只沬濡枯鱼，十年不识孔方面。","记得魁梧美少年，手把牙签颂书传。","花前月下几吟哦，颠书自扫白团扇。","高冠大袖走文场，身经大小百馀战。","几年面上堆紫烟，直腰曲背走乡县。","家园卖尽子依人，不及西家老曹掾。","身宫磨蝎命驿马，五行劳碌君自见。","诗能穷人穷者工，瘦岛寒郊无饱顿。","新诗字字挂人口，不与妻儿充饥咽。","如今贵者不读书，腹中犹如酒食店。","自来好语出饥肠，一字堪酬五十绢。","我亦辞官作乞儿，他时同入歌妓院。"]},{"t":"和谷字韵","f":"七言古诗","c":["江波日夜鸣颓绿，眼底屏山青六六。","茶花冷茜烧春云，酒晕生腮红照肉。","先生吟诗新履道，儿童觅砚旧纱縠。","只觉营生让怒鹏，未许卑飞夺倦鹄。","水响风枝伴楚吟，浓烟淡月随燕玉。","竞奇角险建骚场，彻夜灯花守鱼目。","规红缕碧惟好手，入地搜天快神足。","诗成佳恶自平章，除却莨稊留嘉谷。"]},{"t":"看梅用前韵","f":"七言古诗","c":["海上佳人字萼绿，一笑曾倾三十六。","古来相女如相士，莫使精神掩丰肉。","洗却东家恶朱粉，不御人间闲绡縠。","一枝素艳倚苍云，夜夜诸仙返龙鹄。","骚魂冒雪走三湘，客梦随风堕群玉。","气条繁蕊乱高清，引得时流妄标目。","咏物写生同一肖，不貌而工神已足。","抓山昨岁附诗筒，千里函题寄不縠。"]},{"t":"代广陵姬用前韵","f":"七言古诗","c":["低鬟染就宫云绿，麝裙晓展潇湘六。","杨子桥东梅岭西，归魂几夜销香肉。","轻妆淡抺浅规眉，爱著生衣弃纨縠。","一身飘落等吹花，千里家乡任白鹄。","东邻移去复西邻，那得王昌与宋玉。","梅花终作处士妻，海棠暂试诗人目。","卖珠补屋是何人，方领长环穷也足。","但得夫婿不从军，同向沙田种麻谷。"]},{"t":"偕崔晦之过二圣禅林时诸衲子出纸索书戏得猪字","f":"七言古诗","c":["柳澜滴沥溜春渠，牡丹已老木香初。","黄蕉白纨蔽香庐，唾云沫月课空虚。","剡溪十丈雪不如，长眉辟支手自舒。","波折瘦硬结浅疏，细如春蚓浓如猪。","书成诘曲不能读，牛鬼蛇神者谁欤，天竺胡儿解我书。"]},{"t":"甲辰会榜题名至时旧友及诸弟在场屋者皆被落因及之","f":"七言古诗","c":["无翼而飞无胫走，辰发幽都巳南斗。","一丸红蜡半通函，喧杀青童与白叟。","珊瑚未尽铁网愁，霜蹄暂蹶麒麟吼。","了知妍丑任瞳人，未必枭卢真好手。","柳浪千顷雪粘天，月下洼尊花下臼。","隔年兄弟校眉髭，面上浮纹添八九。","南郭种蔬西郭田，山前著屐山后酒。","少年爱惜等佛名，今日公然破敝帚。","幽窗日上簟纹红，绝胜朝参与卯酉。","颠毛那许更乌纱，花鸟云烟共白首。"]},{"t":"和东坡聚星堂韵","f":"古风","c":["冻乌无语僵寒叶，晓起漫阶五尺雪。","穿帘扑慢缀斜风，楯碧纱红景幽绝。","垆膏乍涩紫绒生，研冷煤枯霜金折。","千梢摆压凤翅垂，万瓦齐铺乌鳞灭。","近墙老鹄不知人，却立氋氃如被掣。","月团三百沸温瓶，盈碗沤花泻文缬。","高禅满坐?毹床，佳言冲口栴檀屑。","杨岐偈子再三题，庞老机锋时一瞥。","东坡先生写雪真，不用烦言与喻说。","杜老梅花诗亦然，广平空有心如铁。"]},{"t":"送惟长先生归窆途中偶成","f":"七言古诗","c":["板桥丝柳黄泥路，曾是从公送人处。","麻衫扫地额沾沙，蒿里一声公又去。","长堤雨暗血滋衣，幡旐遥遥捲飞絮。","白杨无数鬼啼风，三十六人唱烟雾。","人生要死何用愁，白日红轮攀不住。","赤髭黄卷忏他生，皓齿清歌乐朝暮。","薄留风雅驻欢场，高筑糟丘驱大怖。","一斗憨憨睡宝池，大士心许佯赪怒。","少日倔强老更颠，料公拍手庵罗树。"]},{"t":"午日沙市观竞渡感赋","f":"七言古诗","c":["金鳞圻日天摇波，壮士麾旄鸣大鼍。","黄头胡面锦魅额，疾风怒雨鬼神过。","渴蛟饮壑猊触石，健马走坂丸注坡。","倾城出观巷陌隘，红霞如锦汗成河。","妖鬟袖底出巾冠，白颠髯下立青娥。","朱阁玲珑窗窈窕，轻烟倩语隔红罗。","北舟丝管南舟肉，情盘景促欢奈何。","云奔浪激争抚掌，亦有父老泪滂沱。","渚宫自昔称繁盛，二十一万肩相磨。","西酋中珰横几载，男不西成女废梭。","琵琶卖去了官税，健儿半负播州戈。","笙歌沸天尘捲地，光华盛校十年多。","耳闻商禁渐弛缓，努力官长蠲烦苛。","太平难值时难待，千金莫惜买酒醝。","君看至德中兴后，几人重唱天宝歌。"]},{"t":"彭长卿自武陵至公安游甚困便欲由梁之鲁入都歌以送之","f":"七言古诗","c":["瘴雨溪烟痕满面，去日北风打霜霰。","青鞋踏遍武陵山，溪流不泛桃花片。","千崖霞错绣盘盘，自是羁人眼不见。","归魂夜夜搅春云，梦里黄金醒后变。","宵寒枕上叠征衫，晓雨街头典行卷。","囊空难买沙头春，一骑秋风走淮汴。","袖里慵开北海书，匣中自洗端溪研。","杜甫南池李白楼，兔园台馆灵光殿。","七十老翁健如铁，骚场尚可背城战。","大耳红颊酒百盏，醉来犹枕桃花扇。","朱家门外季布髡，信陵席上侯嬴贱。","碣石天高晓月寒，潞河水滑秋云溅。","幕府若逢裴相国，一字应偿一匹绢。"]},{"t":"病中短歌","f":"七言古诗","c":["吁嗟我生年十九，头发未长颠已朽。","病寒三月苦沉吟，面貌如烟戟露肘。","赢枯博得妻儿怜，七尺浪为鬼神有。","箧里残书别故人，几上龙钟斗老叟。","无情莫问囊中钱，有狇还克床下酒。","虫臂鼠捍彼何人，嗟来子桑真吾友。"]},{"t":"北邙","f":"七言律诗","c":["苍松老鬣风掀舞，垒垒孤烟问无主。","铜驼陌上旧王侯，吹作行人面上土。","山头白杨化为姥，夜夜田中驱石虎。","衣冠北向拜寿陵，树上乌鸦能汉语。"]},{"t":"自从行别袁水部","f":"古风","c":["自从龙门称千里，天下风流属袁氏。","以兹仙郎复檀名，依然弹冠粉署里。","我见行馆沙市傍，市上桃花照春浪。","章华绕路幽兰笑，巫峡趋门玉练长。","主人经年忽回首，父老相赠一卮酒。","游今争勒羊公碑，商妇共挽遗爱柳。","龙洲江上一片石，髣髴留君向君揖。","甲帐开时云不流，锦帆过处香犹袭。","傲然一舸下江浦，直到浔阳九折处。","湘娥绿粉扫晴烟，小孤云鬟逗秋雨。","三湘九江昔所悲，长沙曾此别东篱。","我今与子忝同谱，别意悠悠谁与吐。","君不见四世五公声名极，青眼望君君努力。"]},{"t":"长安秋月夜","f":"古风","c":["长安城中秋月明，六街九陌无纤尘。","先入楼台喧戚里，次经池馆趁游人。","游人宛转无穷已，千门万户秋如水。","处处笙歌玉树傍，家家箫管澄湖里。","汉家天子幸平阳，金蛾宝炬列成行。","吹箫蹋鼓留天女，斫玉烧金煮凤凰。","才子后庭竞度曲，念奴别馆伴诸郎。","铜龙轧轧乌啼早，金屋沉沉秋漏长。","秋漏渐深歌渐阑，感此如何不倚栏。","愿得长侍君王宠，愿得长随玉辇看。","又愿君心如月皎，那知妾貌比花老。","玉盌难收覆地流，东风不著断根草。","可怜今夜长信殿，含酸饮泣悲团扇。","未买相如学阿娇，难将赤凤比飞燕。","香销金鸭妾自烧，泪破红绡君不见。","十回看月九回颦，手把轻纨绕月行。","盘花蜀锦伤心色，子夜吴歌断肠声。","红闺紫塞三秋恨，碣石潇湘万里情。","年年先向离人满，岁岁还依愁处生。","年年岁岁秋自好，独怜娇黛无人扫。","未有容颜斗月华，自分弃掷同秋草。","桂魄有恨不长圆，嫦娥无药应先老。","愿得秋光守翠帏，愿随流景送君衣。","与君并蒂原并吐，与君双凤不双飞。","江南荡子无消息，龙城征成几时归。","胡风刁斗愁闻雁，闺月帘栊懒上机。","亦有当垆敛青娥，授色留宾态转多。","双燕有雏辞社去，孤鸳无偶奈秋何。","已见回文传锦字，更闻尺素托流波。","不道人间恨洛浦，定知天上隔银河。","愁来白帢连巾温，泣罢青衫挟瑟歌。","歌已阕，月西倾，一年看，一度新。","汉武秦皇消不得，却寻方士学仙人。"]},{"t":"赠黄道元","f":"七言律诗","c":["海内奇士如君少，双眼识君恨不早。","纷纷俗士尽轻肥，嗟君短褐长安道。","男儿有骨不乘时，处处相逢荐福碑。","请君试秘丰城剑，他年倘有张华知。"]},{"t":"白铜儿","f":"古风","c":["白铜儿，白铜儿，闭眼不观书与诗。","积玉辇金游帝里，买得乌纱绣补衣。","归来白马嚇儿童，黑纻满堂金字红。","炙牛锤马邀乡里，青丝华馆闹春风。","越女吴娃娇侍侧，又欲凌空生羽翼。","房中素女术无成，汞里金丹采不得。","洪都老道术最奇，龙虎真人张天师。","宝箓一箱金百两，牛头可作门前厮。","击大法锣鸣大鼓，百馀道士挥白麈。","门外幡幢引雷公，江上芙蓉灯竞吐。","后门逼债前门舍，乞儿歌郎趋满野。","方士行来眼欲穿，山僧醉后颜如赭。","儒生读书书总多，白发无官可奈何。","生乏白金献天子，死无黄纸赂阎罗。"]},{"t":"长卿内子无如氏绣佛及诸人物行楷精绝诗以记之","f":"七言古诗","c":["湖丝细嫩婴儿发，水光滟滟春云洁。","凭将圣手劈秋毛，巨斧划开枯筒节。","十日一眼九日眉，幻出白毫光满月。","衣摺瘦健貌清古，笔墨无功畦径绝。","白描设色种种工，活夺龙眠与松雪。","横见侧出灯取影，有意无意鸿没灭。","绛州淳化老定武，针锋摹出无差别。","谁能纸上卧王濛，要使赝充走殷铁。","堂上传视色生动，四坐欲言口无舌。","唐钩森紧损神情，宋绣阿娜无筋骨。","长卿秀句夺云烟，佳儿指上现青莲。","一家净侣团圞语，大胜诗人王辋川。"]},{"t":"宫簟","f":"古风","c":["并刀剪出淞水纹，黄琉璃滑净无尘。","华清日高海棠睡，一片温玉沉秋云。","花房昼脱守宫的，珊瑚反挂潇湘裙。","掖庭展转出坊肆，馀脂犹在香氤氲。","腐儒白首青蒲荐，十度摩挲眼惊见。","寒色平铺四丈馀，虚堂尽敛白纨扇。","骨冷魂清抱雪眠，梦回每出松风院。","少陵广厦千万楹，白家大被盖遍洛阳城。","安得此席如此被，眠尽西华道上尘土热中人。","肺腑如冰舌不鸣，三空九陌殷雷声。"]},{"t":"夏日刘元定邀同顾升伯沈仲润李长卿丘长孺集城西荷亭是日热甚得暴雨乃解","f":"古风","c":["火龙吐燄烧青槐，繁鳞挟日战雌雷。","黑云蟠墨湿崔嵬，雨头未展风脚回。","羊角直上旋飞灰，鸣阶稀点大如杯。","泼天猛溜破枯苔，千荷叶翻净绿颓。","跳珠排沫纷喧豗，飞瀑出厓车齧街。","髯虬十，部影䰄，鳞甲鏦刃相摩推。","匿床抱柱走童孩，舌腭虽张耳不谐。","破屏障身肌粟堆，半臂未到声频催。","高堂虚冷无馀埃，蝇冻不飞栖梁煤。","平头次第陈罂罍，黑岑牟进羯鼓开。","胡粉假姬上场米，宫纱浅袖雀头钗。","当筵一笑红玫瑰，莲花过酒香流腮。","错觥沓筹迭排诙，馀枝滴沥落生梅，门外青波没马台。"]},{"t":"万寿寺观文皇旧钟","f":"七言古诗","c":["先皇举手移天毂，无冠少师鬓发秃。","已将周孔一齐州，更假释梵庇冥族。","锤沙画蜡十许年，冶出洪钟二千斛。","光如寒涧腻如肌，贝叶灵文满胸腹。","字画生动笔简古，矫若游龙与翔鹄。","外书佛母万真言，内写杂花八十轴。","金刚般若七千字，几叶钟唇填不足。","南山伐尽觅悬椎，诸葛庙前刈古木。","震开善法忉利宫，撼穷铁网莲花狱。","鼎湖龙去几春秋，二百二回宫树绿。","蒸云炙日卧九朝，监寺优官谁敢触。","大材无用且沉声，吠蚓啼虫满山谷。","今皇好古录断沟，琬琰天球充黄屋。","十龙不惜出禁林，万牛回首移山麓。","沧海老霆行旧令，洛阳遗耇开新目。","西山但觉神奸潜，易水不闻金人哭。","道旁观者肩相摩，车骑数月犹驰逐。","翠色苍寒欲映人，当时良匠岂天竺。","万事粗疏谁不然，今人不堪为隶仆。","兴悲运慈又一朝，万鬼如闻离械梏。","几时谏鼓似钟悬，尽拔苍生出沟渎。"]},{"t":"蛙饮叹","f":"七言古诗","c":["众蛙强饮角雄雌，怒腮鼓腹入清池。","池面不减一涓滴，千众蹒跚醉淋漓。","学宫老儒课童子，长头短项叫相随。","蒲根荇底互嘲笑，我吻犹燥汝不支。","白龙鱼服过而语，汝辈虽饮奚以为。","众蛙曹怒呼其侣，波心跳掷如熊罴。","前驱大腹后丁尾，鼓角虽雄剑戟疲。","白龙一呷池水渴，诸蛙骇愕号且驰。","聚族隐姓人污泥，羞教东海见涔蹄。"]},{"t":"赋得朱华冒绿池","f":"七言古诗","c":["曾见云锦光明地，花采虽繁无生气。","又见杨妃出浴图，未离宫粉香奁意。","花意高洁水清冷，色态两绝非浓腻。","坐看风晓月斜时，柳妥烟沉天欲醉。","不放玻璃光潋滟，高窗低箔如茜染。","辟如新晴水碧天，也要红云乱妆点。"]},{"t":"云起楼为彻如赋","f":"七言古诗","c":["白云缥缈如仙客，只在轩前人不识。","高人兴云若故知，近固追随远亦得。","鬘鬟人物偶尔成，岂有神情与香色。","治然一以气类从，如磁与铁自相即。","主人玉女潭边住，楼居正直高崖处。","赤栏翠竹与山平，便是孤云来去路。","朝随马迹渡头风，暮宿罨画溪上树。","云耶君耶递为主，茶烟湿处飞泉怒。","雨中自有徐熙山，秋来忽遇王维句。","只今长安浩浩尘，云亦随君马上去。","西山逼眼万螺青，是中应有云流寓。","东华举首即重霄，垂天漠漠如飞絮。"]},{"t":"毕少参舟中见武录知丘长孺被落诗以悲之","f":"古风","c":["鞭策麒麟柴车下，疾走不能先驽马。","客座见书身毛寒，泻水高谈为君哑。","穿杨万辈岂易君，胸中奇丽如春冶。","早知大黄亦误人，悔卖囊中未央瓦。","嗟乎长孺臂在身、韬在腹，弹射百家蒐九流，驱使兔毫如箭镞。"]},{"t":"宿迁道中阻风和方子公","f":"七言古诗","c":["黄河水浊如泥注，晓起颠风欲断渡。","白头舟子敛手愁，黑雾龙竿大王怒。","黄熊庙倾庚辰死，潭底狝猴锁不住。","龙骧万斛掀一毛，怪鸦作语湾头树。","我告舟人亦偶然，神灵未必苦相怖。","驱风走浪乞羊豕，神若有知神亦恶。","僧伽古塔向米灵，月下心香聊一炷。","假宠乞怜非我心，何以供养唯无惧。","人生祸福有前期，辟若古邮亭上路。"]},{"t":"中山观长公雪浪石","f":"七言古诗","c":["银钩错落绕盆唇，遭时燬禁石仅存。","峨嵋积雪裹玄云，坐令灵擘羞季昆。","黑山夜渡蛟波翻，飞涛挂壁天迷昏。","旋流入眼风生痕，一洗河比印板纹，石中应有道子魂。"]},{"t":"天开岩","f":"古风","c":["不到天开岩，不见此山奇僻趣。","辟如读书不读石鼓与丘坟，不知古人幻变突兀处。","石下常生有蒂云，石旁粘著无根树。","骨格遒劲毛爪寒，山鬼吞声巨灵怖。","灵隐寺前万窍风，石公山上一方雾。"]},{"t":"观音庵为一心隐斋上人题","f":"七言古诗","c":["古鎗百斛沸春雪，衲子如云谢不得。","堂头拊脾饭头饥，军持每注珠泉竭。","室中夜语秋花坠，举世三写乌焉字。","难将真药苦投人，衲衣偷裹菩萨泪。","宴息六度万行场，敷演水月空花戏。","观音妙法最难思，山僧功德不可议。"]},{"t":"千佛堂为玉轮上人题","f":"七言律诗","c":["千佛堂中千个佛，眼底诸君皆髣髴。","旁边突立千佛岩，绀朱剥落千年物。","寒风十月枯青嶂，短尾饥猴跳枝上。","毗卢帽子茶褐衫，道是堂头老和尚。"]},{"t":"般若台为无怀上人作","f":"七言律诗","c":["般若禅人晓禅味，辟如屋底看山翠。","又如人持京师书，虽不是香有香气。","荒台老骨一片青，风吹日炙石文腥。","携将三百溪藤纸，摩取四十二章经。"]},{"t":"西林庵为从石上人题","f":"七言古诗","c":["西林禅人东林弟，朝作新诗暮作偈。","将禅比诗不争多，色里胶青水中味。","室中枯坐一绳床，窗风吹出沈香气。"]},{"t":"集张园分得对字","f":"七言律诗","c":["秋芳老尽枯香在，缸花夜煖朱丝佩。","洞庭橘子割霜寒，碧椀青盘雅相对。","钓月半窗吐薄晖，长眉小史换宫衣。","金炉火急焦声碎，杯面鱼珠点点飞。"]},{"t":"步小修韵怀景升","f":"七言古诗","c":["江涛日夜锁梅冶，长髯仙人在其下。","歌楼夜雨蜡灯红，袖压金厄点筹马。","箧中时有青铜泪，宾客无欢神色醉。","欲将心腹苦干人，前门投刺后门避。","世人眼塞开元钱，郡能读得贞观字。","百万抛来李白穷，十千唾手袁羊戏。","沟水至清河至浊，汉宫不重东方朔。","火池老尽垂天翼，斥鴳公然乘羊角。"]},{"t":"从军行赠程生","f":"七言古诗","c":["留都十月九塘报，程生拍手向东笑。","三百斤石一手提，自典冬衣买乌号。","玄霜十月道途难，雪花如石打马鞍。","敝衣三尺不掩体，尚说淮南飞不寒。","自从和议成反复，正使羁囚尚书戮。","天子咨嗟发帑金，经略提兵过鸭绿。","材官猛士气如云，玉刻腰带金麒麟。","朝廷岂无胡都堂，人问不少戚将军。","往闻倭奴寇浙时，义乌贵者至千人。","倭奴机关亦易与，结羊挥扇驱妇女。","十步一伏九步连，八尺神刀吼秋雨。","程君切玉如切肉，倭刀虽强不过玉。"]},{"t":"达磨影石","f":"七言古诗","c":["禅月罗汉天下绝，螺烟渗石光不灭。","面纹漆黑眼生棱，衲衣袖展秋云洁。","幅巾谈道老先生，以刀割影影愈彻。","如虫蚀木偶成文，镜花岂必生枝节。","中山废圃石如铁，白浪缠身捲飞雪。","移向山中作一盆，飘然乘风苇可折。"]},{"t":"过斮胫河","f":"七言古诗","c":["北风浩浩吹酒池，万娥夜舞糟丘堤。","飞廉手把火旗麾，少师局天不敢啼。","是时独夫眼方缬，古鼎排庭沥豹血。","妲己颓红倚曲栏，野人霜下踏冰裂。","须臾縳致轩墀前，皴肌凛凛颠垂雪。","斮胫传视血淋漓，仰天大笑璎珠绝。","已见愚臣心孔多，又见耄叟骨如铁。","殿外执圭声唯唯，圣度如天鉴似水。","西方罪臣老更尪，口衔枯草谈阴阳。","朝披雨雪夜眠霜，哀茕瘗朽目汪汪，何异爝火仰三光。"]},{"t":"绿云庵为苍麓禅人题","f":"七言律诗","c":["天女乘空洒蓝水，秋云染就层山里。","泻地稍天万尺长，客雾邮风二十里。","筼筜谷前君山侧，水冷山枯行不得。","藤花格子竹方床，眼里丛梢如旧识。"]},{"t":"河阳","f":"七言古诗","c":["潘郎种花如种麻，百里霜锄耘锦霞。","扫香少女红没丫，东渠西沚浮落花。","潘郎去后委泥沙，春风如旅归无家。","道傍瘿树怒槎牙，明星木者时老鸦，鸟鬟三尺衩裆斜。"]},{"t":"骊山怀古","f":"古风","c":["薄云浅照玫瑰红，一笑君王三举烽。","羯鼓楼头鼓一通，霓裳夜舞玻璃风。","赭山梁海老英雄，凿地出天开幽宫。","月珠如炬衔两龙，三泉照澈白日同。","蓬莱方丈远不逢，方士谈仙如镂空。","?舸满载稚芙蓉，堆珠积玉海波中。","千岁老狐穴深丛，阴厓占断石帘栊。","飞乌吐火烧青松，鸣雨鸣风怪哉虫。"]},{"t":"泾阳驿见王子声壁间韵怆然有述","f":"五言古诗","c":["只合临漳死，曹家鬼好文。","枫根犹有绣，夜壑岂无春。","研乞铜台瓦，姻求洛浦甄。","歌遗涂粉客，衣逐卖香人。","客鬼轻残蜕，骚宫重楚魂。","死生旦昼理，夜乐胜朝颦。"]},{"t":"赋得野竹上青霄拈三江韵","f":"五言古诗","c":["烟势分层岫，寒稍泻绿泷。","鸾毸拔地洗，龙羽扑天降。","雨押钗头重，飙回个字双。","随根来北舍，递影入西窗。","翳日巢幽鸟，敲风吠小庬。","檐头悬渭水，屏里绘湘江。","曲路通斜阁，交枝覆断矼。","微霜天女粉，幽语梵仙腔。","椽笛知遗族，渔竿识旧桩。","染成云泛泛，匝以碧淙淙。","自起掺三弄，时来倒一缸。","主人那得比，唯有鹿门庞。"]},{"t":"和五弟韵","f":"五言古诗","c":["覆地苍云湿，垂天绿沈浓。","窗开生翠叠，箔卷腻烟重。","妥尾千梢凤，拿空万部龙。","入风旗纛乱，敲月佩环从。","嶰谷追遗律，筼筜墨旧踪。","高寒排雨气，潇飒冷云胸。","漾壁颓蓝水，遮门浩碧峰。","湘娥斑潋滟，庄叟籁于喁。","铜干平欺柏，霜髯欲傲松。","横分清偃蹇，侧亸醉龙钟。","铁画唐钩锁，粗村杜刃锋。","帚书豪蔡格，箭栝美吴侬。","碎影琉璃榻，鲜香琥珀钟。","他时裁笋箨，规制取芙蓉。"]},{"t":"王回先一夕尚痛饮叫笑如常时侵晓三弟来云回病且革以为戏也急往观之回奄然逝矣遂为长律哭之","f":"五言古诗","c":["道病犹疑谑，那知毕竟非。","命轻殉粉黛，形老惫甘肥。","事业凭唇立，家园信手挥。","分身冲酒阵，一笑解愁围。","黑白人人是，恩仇面面辉。","牢笼心入窍，轻巧语当机。","望节朝团社，闻歌夜款扉。","乍来乾鹊喜，忽去饱鹰飞。","六月绫纹裤，三冬葛缕衣。","预愁酤少值，不畏室啼饥。","面古堪描画，耳顽耐刺讥。","甑中无糁粒，袖里有珠玑。","世法猿愁槛，欢场马脱鞿。","醉犹喧夜月，死不待朝曦。","破屋遮遗荐，寒蒿倚素帏。","一城俄冷落，四众半歔欷。","在在盘飧减，门门笑语稀。","襟怀诗客尽，气运酒家微。","貌熟人频梦，名轻鬼不威。","鸳亡魂宛娈，蝶死蜕芳菲。","猫胜西邻叟，黄金带不归。"]},{"t":"法华庵同诸开士限韵","f":"五言古诗","c":["送云归老岫，荷蓧量幽潭。","古榻连池损，痴禅著谜参。","閒胶踏石屐，小立探春骖。","竹路编龙子，花时过长男。","草侵红版谷，蕉短绿天庵。","角焰抽寒穗，垆丝吐睡蚕。","农人占九九，童子契三三。","溪鸟藏深滟，涧毛露浅鬖。","疏经通老衲，书额过精蓝。","欲访东林去，陶家借竹蓝。"]},{"t":"又次前韵","f":"五言古诗","c":["怪石含斑藓，幽云抱古潭。","茶勋凭水策，诗理入禅参。","白帢纷春社，红衫过筱骖。","纨书沈箧笥，纸笔付儿男。","鼷鼠全河饮，蜗牛一壳庵。","有冠徒似范，自茧可悲蚕。","瘦削山容独，酣沉柳梦三。","近烟红淡泊，著雨绿䰐鬖。","香腻煎云母，溪光泻蔚蓝。","僧来伸纸看，一幅古鱼篮。"]},{"t":"旃檀馆雨中限十一韵","f":"五言古诗","c":["卧观残帖蠡，閒拨冷池灰。","洗碗供梨汁，分垆炙芋魁。","雉班穿砌笋，兔目长官槐。","谢草吟三复，支堂看几回。","思深泉透石，吟苦将衔枚。","敝册胶春卤，花笺污晓煤。","鵁飞频带子，鸠雨不通媒。","种药愁沙涩，增栏值岸颓。","茜衫宫长过，小服野人推。","木壁涂番像，丹房裂净苔。","菘菁欲放满，自起斮旁莱。"]},{"t":"香光林即事用前韵","f":"五言古诗","c":["宦网弛三面，禅心积久灰。","岁功听瓦卜，天纽问杓魁。","老蠹穿香节，寒虫叫古槐。","江花排岸出，沚木到门回。","割裂穷巴衍，俳优畜马枚。","沉思竭废井，久语堕梁煤。","子鹤难为父，妻梅不用煤。","立窗石皱瘦，困雨竹隳颓。","花社僧来讯，鸥邻长可推。","附舟求洞药，置槛养盆苔。","作意为农去，湖田怕长莱。"]},{"t":"法华庵雨中诸公以诗相角限得六韵","f":"五言古诗","c":["苦发寒垆窍，閒书折股钗。","琢云裁月遍，俪白粲红皆。","笔误翻缸落，金清入梵谐。","分阄时一赛，驱闷几回徘。","古砚文全蚀，废铛耳半埋。","毗耶多口老，閒引散花娃。"]},{"t":"雪中限韵时寓沙市同度门作 其一","f":"五言古诗","c":["天女皇新缬，寒梅著典刑。","熨烫温冻局，拥罽读仙经。","苍迹纷残篆，枚涛怒远听。","鹭饥卷似猬，虫窘字如丁。","一国琉璃观，千枝发刃硎。","镜开古木照，涎热老龙腥。","漏迹埋番夹，寒澌结胆瓶。","禅心降槁木，僧梦怯岩扃。","卧客全肖蛰，寒姑早验鸰。","皓姿三十里，清远隔吴泾。"]},{"t":"雪中限韵时寓沙市同度门作 其二","f":"楚辞体","c":["苍茫沉地魄，吼怒峭花刑。","垆冷荒参谱，年丰验稻经。","王正书法首，国令免庸听。","入树占男女，候晴卜丙丁。","冻毫书破字，古绣结残硎。","岩闼魂先入，水窗梦亦腥。","分笺疏白事，温水护青瓶。","拨闷频呵局，思山屡启扃。","归兮耘旧圃，馁矣忆原鸰。","欲访佳人去，寒舟阁浅泾。"]},{"t":"雪霁后仍用前韵","f":"五言古诗","c":["帝女传花信，阳官布省刑。","帘霜淋故额，窗彩烂残经。","轧轧声初乱，乌乌乐可听。","题书邀宝月，祝面忆添丁。","薰帖防新润，磨烟散古硎。","茗花香后滟，艇子过时腥。","少树波千溜，寒梅月一瓶。","彩光匀水市，青黛扑门扃。","玳瑁噞盆鲫，连钱玩小鸰。","面暄酣白战，决口泻河泾。"]},{"t":"舟中看月仍用前韵","f":"古风","c":["阴?如不扫，风伯有常刑。","楼阁云初坼，玻璃魄乍经。","沙容兼雪看，垆响入泉听。","近阁梅题逊，横江鹤姓丁。","诗魂将化石，霜颖发于硎。","河鼓呈天练，蛟宫匝冷腥。","夜光辞岭蛤，舍利泻吴瓶。","窈窕宫腰国，仓琅帝子扃。","穿林眠冻兕，触苇叫寒鸰。","濯足求清濑，刚肠恶浊泾。"]},{"t":"舟中风雪迟苏潜夫游玉泉不至和客韵 其一","f":"五言古诗","c":["立尽寒枝影，佳人窅不来。","掀帷抛断梦，拨箸写残灰。","南郭频愁籁，东林每忆雷。","树髡啼獝狖，云冻失丘魁。","江潝奔澜叠，山流腻绿颓。","精灵凭化骨，神力假于䰄。","一扫狂霾去，千峰万岭梅。"]},{"t":"舟中风雪迟苏潜夫游玉泉不至和客韵 其二","f":"五言古诗","c":["积阴负故腊，莽莽压天来。","白马酸冰渡，苍猊死冻灰。","祝晴频梦大，诅雨孰鞭雷。","拨闷凭毛氏，浇寒命草魁。","垂头花拥肿，裹絮衲隳颓。","看帖遮愁眼，嘘天鼓怒䰄。","青娥隔带水，负我一窗梅。"]},{"t":"题曾太史退如憨斋用十三覃韵","f":"五言古诗","c":["底事欲名憨，百城卧老蟫。","愚公溪正北，痴叔舍偏南。","罔象珠悬幕，无怀藉满函。","花头羞艳艳，燕口怯喃喃。","庭匝空心树，窗凝太古岚。","侍儿修浑沌，稚子学沉酣。","杜口非无舌，忘情似不男。","巳甘中散七，未害虎头三。","乞巧楼全卸，醉乡路可探。","知亡如守墨，想尽类修昙。","兀兀迦陵鷇，茫茫瓮茧蚕。","无弦琴亦弄，不语谜须参。","一枕庄周化，多方惠子惭。","盲方医后见，黑味饱时甘。","坐挈云将去，神行不用骖。"]},{"t":"小斋有隙地植花木数本同孝若寓庸赋得松字","f":"五言古诗","c":["一曲莓苔地，风光属老慵。","稍除疏冗蔓，略植典刑松。","徙石云纹出，移花月影从。","买时才数本，我处已三重。","红叶刚遮砌，高枯未掩筇。","干唯求老健，姿不取纤浓。","雏笋犹呼凤，稚藤也学龙。","夜阶云淰淰，晴槛雨淙淙。","障日聊铺苇，防窊且益封。","公然藏小鸟，亦自集间蜂。","分翠来屏扇，流香扑酒钟。","折攀愁楚女，浇剔倩吴侬。","景入单条画，清连怪石供。","幽奇无大小，袖里九华峰。"]},{"t":"夏五望日兴德寺纪游得兴字","f":"五言古诗","c":["曲侣为前导，僧雏接后乘。","城中十里水，世外一行朋。","似眼初除翳，如禽忽去矰。","摩苔因看碣，敲盏为呼冰。","松老前朝在，编遗手记曾。","倦来披数快，兴去跃孤藤。","邻竹幽堪借，古槐醉可登。","溪光时载郭，杯影忽沉僧。","云片轻绡敛，天容定水澄。","稚儿行趁蝶，髯客坐驱蝇。","蒙密苍枝覆，晶瑩皓魄升。","瓮开新易水，瓶煮旧宜兴。","梵集诸方磬，波然万室灯。","月尤增潋滟，风小露威棱。","乍入宫荷气，斜分雾树层。","凉衫轻鲁缟，时品荐吴菱。","互立谈门户，旋刊酒准绳。","杜康将佛事，庄叟作魔惩。","近水终怜鹜，飞枪且笑鹏。","思光空任诞，求郡复求丞。"]},{"t":"集元定行记斋再赋得原字","f":"五言古诗","c":["净绿无馀地，鲜芳缀满盆。","风回香出苑，雨洗碧澄轩。","满壁长林字，盈襟易水痕。","客来谈白传，书去觅青原。","托疾常浇药，无忧亦树萱。","幽弦清入润，淡墨远成村。","见酒猩猩态，怜花栩栩魂。","阶前三石瓮，座上五方言。","难至穷仙朔，杯行谑赘髡。","闻歌半晷静，得采一堂喧。","怒若乘秋鹘，竞如渴水猿。","瞑朝时错乱，醉醒客更番。","户小停诗罚，筹多欣酒冤。","语深僮仆寐，觞苦教条昏。","入树河垂没，亚枝鸟渐翻。","归途传远炬，鸾卫已呵门。"]},{"t":"元定斋不甚宽而布置有态器具亦精馀兴未已仍用原韵赋赠兼订后来之约","f":"五言古诗","c":["莎径荒才剪，丛稍影渐繁。","山苗分杞菊，乡信觅兰荪。","碧蓧蟠为几，黄蕉挂作门。","卷中流峡水，屏里识湘源。","引月来阳树，邀风入净轩。","摩钟丝蠡出，洗砚墨蛟翻。","户识王恭隽，家怜次道温。","清谈还正始，近体杂开元。","问衲骑频去，呼儿鸟忽言。","莲苞收茗叶，绮石养蒲根。","官长衙参少，山林奏记烦。","团参充午饮，瑶柱出常飧。","殊琙皆邻里，时贤尽弟昆。","酒鎗贻子晰，石墨往平原。","算口常先鹤，餔糟不忌豚。","思光鹭羽扇，弘正犊皮裈。","庭卉非时烂，垆波澈夜喧。","星飞银不落，炷老铁昆崙。","采药朝朝舌，登山夜夜魂。","易求王烈髓，渐了尚平婚。","会意成三笑，归怜买一村。","他时烟壑底，洗足听清猿。"]},{"t":"夏日城西月张园看荷花得莲字","f":"古风","c":["晓起闻儿说，隅西已有莲。","帻犹悬壁上，屐已跃门前。","树接宫云近，花藏庙市偏。","鱼行清冷涧，人语绿沈烟。","露叶无多绽，风香绕一廛。","偏呼荷蕙侣，驰与蜡纹笺。","任意巾衫去，随身酒盏传。","题诗新涤砚，洗茗自浇泉。","有垒微添石，因洼小作田。","凉风吹面尽，明月到阶全。","鸥鹭归閒地，杯捲属冗员。","聊为避暑饮，?了月支钱。"]},{"t":"游金山寺见旧作有述同游者两谢君方子公张明教及童子二仲也","f":"五言古诗","c":["壁上苔痕字，回头十二年。","方平犹眼底，江令是生前。","童子来扶杖，山僧试煮泉。","浪中惊准出，塔下古蛟眠。","骇目洞心处，危滕峭石边。","无栽慈竹地，有纵怒鹏天。","一壁云皆碎，千沟瓦忽县。","波涵万里月，石老六朝烟。","杨子来歌吹，南徐阅井廛。","萍飘建邺镇，豆许海门船。","鲨鬣遮晴岛，珠胎射绿渊。","云堂招贾客，盐豉供朝贤。","夜火朝岚市，风枝水响禅。","山中无印老，休举带因缘。"]},{"t":"过三桥庄庄在真州城西余旧游地也属潘稚恭","f":"五言古诗","c":["江上喧阗甚，城中乍解骖。","坊趋芹祉北，水过石桥南。","丫路今犹识，枵杨旧亦谙。","未曾添屋舍，稍觉足云岚。","鹤立琴台石，乌巢画舫庵。","长廊安棐几，斜幔隐书龛。","碎影柯枝乱，疏行竹柏参。","异花防鹿践，细果畏禽含。","奕客频留势，骚人每过谭。","解空犹负堕，高户也沉酣。","幽意关鱼鬣，新思类茧蚕。","起居凭邺架，来往借陶篮。","地暖溪毛翠，日和林鸟諵。","江南山信美，隔水看堆蓝。"]},{"t":"重九日登钓鱼台限韵","f":"五言古诗","c":["卧柳侵官道，长堤楼古墟。","宫斜十里粉，画壁一枝芦。","白果将垂砌，红蕉半掩庐。","僧贫茶具废，兴发酒瓯虚。","怪鸟鸣空院，寒花伴野蔬。","阶前云后岫，床下水平渠。","净业莲花社，乡思柳浪居。","道玄唯有发，中敬竟无书。","去矣云中鹄，知之濠上鱼。"]},{"t":"至日集山响斋送陶孝若谕祁门限韵 其一","f":"五言古诗","c":["时节回燕谷，家山问渚宫。","头颅将化雪，腰领渐成弓。","郑草终为带，杨经竟是虫。","瓶无濡鬣水，笔有怒鹏风。","古道水添石，寒崖翠倚枫。","门前端木过，瓢里子渊空。","白脯聊从俗，青襟解恼公。","四箴书两壁，二礼语诸蒙。","皱瘦多盈袖，芎藭尽入笼。","廪人供麝墨，月俸买肌红。","小史髭皆皓，邻斋耳未聪。","萧然心澹远，自振乃孤蓬。"]},{"t":"至日集山响斋送陶孝若谕祁门限韵 其二","f":"五言古诗","c":["梦回青草峡，人远细腰宫。","意气争欣锷，文章宝大弓。","白头耽月露，苍简注鱼虫。","墨老研秦土，衣宽变鲁风。","苔文镌翠壁，兰楫十丹枫。","山市烟如滴，溪潭影似空。","饮猿知接臂，言鸟解呼公。","门下疑夫子，吴中怪阿蒙。","异书搜古穴，珍茗出筠笼。","北海林中白，彭宣座上红。","拔钗妻子怒，识字小儿聪。","著述门常掩，微风语断蓬。"]},{"t":"至日集山响斋送陶孝若谕祁门限韵 其三","f":"五言古诗","c":["马上千盘岭，中山数仞宫。","词场犹负弩，文战忍韬弓。","韵减石家醋，仙成脉望虫。","长官天子谚，乡里大王风。","水影皆涵岫，人家尽树枫。","烧松云满市，登阁翠流空。","山鸟呼閒客，奇峰礼上公。","鱼胞真自别，龙尾珼相蒙。","谢屐常移齿，张髯免入笼。","夜泉频点白，晓露自研红。","古鼎时留目，蛮音每塞聪。","读书师仲蔚，三径任高蓬。"]},{"t":"上元日同王遗狂过灯市得来字","f":"五言古诗","c":["无复他时意，春灯试一来。","寒株陪艳蕊，老女上歌台。","疾雨檀槽闹，温风玉斗催。","西邻波滟潋，东市火崔嵬。","丝竹情终在，樽彝眼乍开。","梁园逢故侣，老矣旧邹枚。"]},{"t":"别恨篇为方子公赋","f":"古风","c":["种得油麻未长，撇他李子何安。","宝枕鸳离丝断，金炉鸭死灰残。","忍啼一语两语，缠肠千端万端。","总角痴儿騃女，接命朝饔晚餐。","独自弓形吊影，谁人知煖知寒。","天上人间地下，死难鬼难妾难。"]},{"t":"丹中与诸上人谈亡友潘雪松事诗以记之","f":"七言古诗","c":["为向山僧述老狂，这番清泪又沾裳。","薄红腮颊秋生腻，湛碧瞳人夜有光。","阮籍一杯浇磊块，徵君千顷泛汪洋。","方言故事閒编集，白水青霞洗肺肠。","玄理每将参国是，冥谭直抇作家常。","终年问道忘人我，老去论交绝辈行。","五十金闺才挂籍，八年符玺尚称郎。","虚心圣主惮词正，侧目权臣避矩方。","大易传成王弼死，小桃园就洞仙亡。","蒲萄方丈新莲社，首帕街坊旧燕梁。","司马也须杨恽在，广陵终作孝尼伤。","极知实落栖真地，不是荒唐渺嘿乡。","魂魄若归先洞府，平生开口说天堂。","地年京国西州路，动杀羊昙哭几场。"]},{"t":"卢沟道中","f":"古风","c":["驿路风尘苦，殊方伴侣稀。","马犹思并辔，鸟也厌孤飞。","树老春无态，云生山有衣。","红亭?一醉，留著斗寒威。"]},{"t":"良乡道中忆弟","f":"五言律诗","c":["同调古无有，相怜今亦稀。","如何万里去，又作两行飞。","孤塔冲人立，寒云并马归。","长安三月里，好得看轻肥。"]},{"t":"宿涿川","f":"五言律诗","c":["旅馆侵霜气，疏题度月明。","侍儿偎大语，黠鼠背灯行。","别弟心常楚，离家梦不清。","相去未半载，马足几千程。"]},{"t":"河间逢北去人寄书口号","f":"五言律诗","c":["为报东征使，行行路若干。","长途虽厌倦，弱体幸平安。","逆旅春无况，离亭梦亦寒。","愁心挥不断，日暮几千端。"]},{"t":"夜行","f":"五言律诗","c":["野暗毛精土，天昏太史河。","阴林晴见火，山店夜闻锣。","独树疑人立，冲风似鬼过。","仆夫前慰我，官路已无多。"]},{"t":"邮亭小餐","f":"五言律诗","c":["独上长亭憩，溶溶水泊堤。","庖人供薄饼，童子荐香梨。","朱鬣鱼三寸，白花酒半提。","黄昏人欲去，窗外马频嘶。"]},{"t":"高唐道中","f":"五言律诗","c":["好似苏季子，辞燕又向齐。","乡心随日暮，望眼尽天低。","古道荒人影，寒沙重马蹄。","如何愧小鸟，休占一枝栖。"]},{"t":"过滕赠令尹赵年兄乾所","f":"五言律诗","c":["乘月过滕子，踏沙度薛城。","山云封去马，野葛翳行旌。","官舍栽花遍，民家种柳成。","停车门父老，之子有能声。"]},{"t":"舟中","f":"五言律诗","c":["白鸟当窗坐，青山映水行。","看云诸态冷，吊古百愁生。","近海鱼争大，邻淮酒欲清。","长亭不可数，回首吕梁城。"]},{"t":"舟中同黄绮石沈广乘汤陆赋","f":"五言律诗","c":["天上飞王舄，人间附郭舟。","霞光晴入市，云气晚成楼。","肝胆皆知尽，腰肢各未休。","浮生尚五斗，空复念沧洲。"]},{"t":"往有误传龙君御死者作诗哭之，后读塘报始知君御方立功塞上，喜不自胜，因并前诗存之以识之情","f":"五言律诗","c":["舌簇分明巧，情钟分外痴。","传君无妄死，累我断肠诗。","掷果娇胡女，从军小健儿。","阴山三丈雪，千里白旌旗。"]},{"t":"哭龙君御诗 其一","f":"五言律诗","c":["可怜千片玉，竟作一堆尘。","住世灯前影，居官浪里身。","从来善饮啖，颇亦健精神。","曾不得四十，伤哉如此人。"]},{"t":"哭龙君御诗 其二","f":"五言律诗","c":["不分成迁客，那堪掩夜台。","人应销朽骨，鬼亦溺寒灰。","海阔羁魂度，天昏怪雨来。","高堂悬爱子，早晚若为哀。"]},{"t":"哭龙君御诗 其三","f":"五言律诗","c":["多少人间死，于君特怆神。","玄言从此尽，白日奈何春。","礼法雠狂士，乾坤侮俊人。","再来如有意，莫见宰官身。"]},{"t":"鹤林寺和尚","f":"五言律诗","c":["竹里逢开士，花间觅著书。","禅观今果足，文字往因馀。","听雨知鱼乐，开轩任柳疏。","自怜婴世网，敢复事空虚。"]},{"t":"舟中","f":"五言律诗","c":["莫自夸强项，逢人且折腰。","微生信坎止，作吏也逍遥。","山月领归棹，江云凑晚潮。","古来差快意，唯有一王乔。"]},{"t":"同江进之登金山 其一","f":"五言律诗","c":["白浪三千顷，苍岩二十盘。","鲛人分夜火，龙女给晨餐。","潮涌天难定，地孤石也寒。","由来多胜迹，草里读碑残。"]},{"t":"同江进之登金山 其二","f":"五言律诗","c":["宝楯千年碧，炉烟镇日青。","穿藤逢石怒，倚险嗅波腥。","鼋过吞人影，潮来念佛经。","幽期如可订，住此学沉冥。"]},{"t":"渡太湖","f":"古风","c":["野树澄秋气，孤蓬罥晚晖。","渔舟悬网出，溪叟载盐?。","山叠鹦哥翠，浪驱白鸟飞。","暮来风转急，吹水溅行衣。"]},{"t":"泊西洞庭","f":"五言律诗","c":["白浪浸天冷，青山引黛长。","朝童迷水怪，夜女出江黄。","种橘皆成市，凿山半作堂。","路疑烦指点，洞口觅渔郎。"]},{"t":"东山晚望","f":"五言律诗","c":["转厌人间少，翻愁大地空。","石枯山眼白，霞射水头红。","浪恶惊三老，鱼稀祭五风。","奇峰探不尽，点点乱流中。"]},{"t":"乞归不得","f":"五言律诗","c":["不放陶潜去，空陈李密情。","有怀惭狗马，无路达神明。","竹影交愁字，莺啼作怨声。","但凭因果在，陨血誓来生。"]},{"t":"纪宦","f":"五言律诗","c":["薄宦经年许，心精好欲慵。","诗书攻俗讳，耳目信尘封。","生女从呼囡，学音渐是侬。","令吴何所有，震泽两高峰。"]},{"t":"初杜门","f":"五言律诗","c":["一笑挥铜绶，高眠諀部民。","放风疏垢发，信懒著闲身。","吏省公移字，堂清案牍尘。","静居堪养性，州郡但劳人。"]},{"t":"斋居戏题","f":"五言律诗","c":["深入终防饵，高张远避罗。","课儿书上字，听客唱吴歌。","检药神方少，疏经悟语多。","一枝生计足，五斗奈人何。"]},{"t":"戏柬江进之","f":"五言律诗","c":["作令真成累，全身总是归。","道傍春自谑，人里鬼相依。","缓系牛皮带，宽披燕子衣。","云霄终有翼，学取一行飞。"]},{"t":"惜日","f":"五言律诗","c":["芳树低檐浅，游丝绕户牵。","闲情观秘戏，消日坐枯禅。","范蠡藏身险，庄周入梦颠。","浮生如石火，何物可长年。"]},{"t":"任意吟","f":"五言律诗","c":["解带腰肢免，投闲意态疏。","纵心搜乐事，信口择群书。","万物齐非马，千仙饱壁鱼。","有名终是累，无用可还虚。"]},{"t":"荒园独步","f":"五言律诗","c":["寒食春犹烂，东风草自芊。","花燃无焰火，柳吐不机绵。","宦博人间累，贫遭妻子怜。","一官如病旅，直得几缗钱。"]},{"t":"病起","f":"五言律诗","c":["病起心情太，閒来礼法疏。","愁听传事板，懒荅问安书。","不去终惭鹄，无才合类樗。","何如逃世网，髡发事空虚。"]},{"t":"夜起","f":"五言律诗","c":["凉月穿纱见，微风响树来。","夜虫亲火语，窗鼠触明回。","生卧凭书遣，行藏作谜猜。","终宵眠不得，无计缓愁哀。"]},{"t":"偶成","f":"五言律诗","c":["嵇叔终疑傲，陶潜总任真。","祗因啚事简，不敢恨家贫。","宦邸为欢少，乡书报死频。","弥天都是网，何处有闲身。"]},{"t":"独坐","f":"五言律诗","c":["胸臆知难尽，行藏未可陈。","摊书嫌字小，烹水试茶新。","拨闷占茅卜，祈归拜上神。","闲云与倦鸟，终是一流人。"]},{"t":"述怀","f":"五言律诗","c":["岁月无停晷，迁流快织梭。","寐来趋夜壑，老去皱恒河。","悟法东西祖，藏身大小何。","一沤能几许，枉自著愁多。"]},{"t":"和江进之寒山寺之作 其一","f":"五言律诗","c":["山寺依人境，乘闲且杖藜。","好花营地种，熟鸟认枝栖。","洗钵防茶老，开轩碍竹低。","西来空有义，记取鹁鸠蹄。"]},{"t":"和江进之寒山寺之作 其二","f":"五言律诗","c":["忍草侵阶遍，慈云湿座飞。","爱花僧是业，伺食鸟成机。","一榻书和卷，三生钵与衣。","尘劳方未已，合掌愿皈依。"]},{"t":"初夏同江进之坐孙内使池台感赋 其一","f":"五言律诗","c":["竹隐千花径，亭开卐字栏。","银塘骄水鸭，罗幄护风兰。","邸报传来闷，民膏到处难。","东南供费极，不忍更周残。"]},{"t":"初夏同江进之坐孙内使池台感赋 其二","f":"五言律诗","c":["细果亚枝重，垂藤拂幔低。","檀烟薰睡犬，松子食雏鸡。","情鸟雄雌狎，名花姊妹齐。","繁华终有气，端不似山栖。"]},{"t":"登阳山","f":"五言律诗","c":["巉石蹲如象，枯松驳似鳞。","鹤仙何处是，龙母果然神。","穴有能言兽，岩多不语人。","吴宫零落尽，踪迹果谁真。"]},{"t":"饮徐参议园亭","f":"五言律诗","c":["古径盘空出，危梁溅水行。","药栏斜布置，山子幼生成。","攲仄天容破，玲珑石貌清。","游鳞与倦鸟，种种见幽情。"]},{"t":"赠江进之 其一","f":"五言律诗","c":["苑花经四果，门柳近千枝。","年俭迟君俸，官贫独我知。","痛民心似病，感事泪成诗。","不是催科拙，由来薄茧丝。"]},{"t":"赠江进之 其二","f":"五言律诗","c":["数叠铜符篆，一挥案牍尘。","宾朋嗔事简，妻子怪官贫。","德畏民无狱，道治鬼不神。","知君本仙令，家世武陵人。"]},{"t":"赠江进之 其三","f":"五言律诗","c":["窥铜怜貌减，裹鬓觉霜欺。","乡语青奴误，官情白鸟知。","佳儿能问字，小妇与填词。","解得庭中乐，闲官亦可为。"]},{"t":"赠江进之 其四","f":"五言律诗","c":["几年名茂宰，艳冶古长洲。","霸气吴宫尽，涛声震泽秋。","花深苑作国，人去馆为楼。","箫管家家曲，那能不醉侯。"]},{"t":"赠江进之 其五","f":"五言律诗","c":["端居持简体，吏隐见仙才。","案牍皆诗料，纷庬入酒杯。","横乌移卯去，灵鹊抱巢来。","一见逍遥作，知君笑口开。"]},{"t":"赠江进之 其六","f":"五言律诗","c":["债子今应长，钱儿久不神。","簿书行流水，参佐拥空尘。","蓄古频分客，题诗每向人。","退斋修竹里，盆沼漾文鳞。"]},{"t":"赠江进之 其七","f":"五言律诗","c":["尝胆经时苦，劳薪几日休。","秃须黄印绶，芒履黑平头。","簿领分从事，腰肢恼督邮。","可怜人似玉，赢得发如秋。"]},{"t":"赠江进之 其八","f":"五言律诗","c":["专诸遗旧剑，西子变新娥。","国大游民聚，时清艳事多。","炫城花似面，络地水如罗。","团扇前溪上，吴娘唱子歌。"]},{"t":"丘长孺 其一","f":"五言律诗","c":["不问南和北，都成故与新。","放开双孔眼，阅尽一时人。","言语谁同味，肝肠孰最真。","金陵居可买，是否作佳邻。"]},{"t":"丘长孺 其二","f":"五言律诗","c":["横金米如珠，洞庭春似雪。","只恐君不来，君来我当设。","酒可供千人，米亦勾三月。","君来当即来，明日吴令发。"]},{"t":"张伯起","f":"五言律诗","c":["两年稀面见，一字到官疏。","白石连云煮，青芩带雨锄。","尊前红拂传，花下古钗书。","兄弟多名理，何山故不如。"]},{"t":"曹以新","f":"五言律诗","c":["踪迹人间冷，生濡一世疏。","近花安酒曰，避雨约床书。","文雅王元美，清夷孙太初。","长庆名不死，有子亦为馀。"]},{"t":"张幼于","f":"五言律诗","c":["家贫因任侠，誉起为颠狂。","盛事追求点，高摽属李王。","鹿皮充卧具，鹊尾荐经床。","不复呼名字，弥天说小张。"]},{"t":"皇甫中璋","f":"五言律诗","c":["爱客常投辙，登盘必市鲜。","茶烹无色水，香炼不燃烟。","高十披先传，稽勋拾旧编。","藤花缭閤子，点点缀青钱。"]},{"t":"刘子威 其一","f":"五言律诗","c":["盛事推弘正，高才足雁行。","丹台函姓字，石鼓筮文章。","管库名伊吕，闭门读老庄。","时贤零落尽，天壤一刘郎。"]},{"t":"刘子威 其二","f":"五言律诗","c":["山居忘甲子，玄想證无生。","天意私高士，人间瑞老成。","文章不死药，形体岁星精。","避世羞藜火，桃灯传五行。"]},{"t":"县斋孤寂时曹以新王百谷黄道元方子公见过有赋","f":"五言律诗","c":["宦向清时懒，囊添旧日贫。","琴孤行赠客，鹤惯不疑人。","怕死归婆子，休官谢鬼神。","寒云流日影，震气赤鳞鳞。"]},{"t":"题方子公蓼莪馆","f":"五言律诗","c":["小筑依蒿里，高篇寄蓼莪。","天空犹堕雪，垢苦不生萝。","夜月呼山鬼，秋坟咽楚歌。","近轩多古柏，攀折泪如何。"]},{"t":"岁暮即事","f":"五言律诗","c":["兰焰添灯重，花光簇夜红。","綵枝閒玉剪，金帖冷屏风。","宦意如霜草，乡心折晚鸿。","谁能学少女，眉画入时工。"]},{"t":"除夕同王百谷皇甫仲璋方子公衙斋守岁","f":"五言律诗","c":["懒贴宜春字，聊为卒岁歌。","官能客脱网，客喜不张罗。","始觉门如谢，刚惭肉似何。","江湖新管领，一径白云多。"]},{"t":"元日述怀","f":"五言律诗","c":["客署闲花事，乡心醉柳条。","闭门春草长，高枕白云骄。","牛马呼仍在，鹍鹏路已遥。","有田堪种米，罄折笑前朝。"]},{"t":"元日方子公对奕","f":"五言律诗","c":["三百争驰道，十千讣赌钱。","屠苏惭得后，奕品僣居前。","花锦添新日，霜毛减少年。","谁能黑白里，悟得远公禅。"]},{"t":"述怀","f":"五言律诗","c":["种树先芝桂，裁衣度薜萝。","敝图悬祖炳，败絮拥妻罗。","丘壑驰驱甚，玄虚色相多。","市朝无拘管，何处不渔蓑。"]},{"t":"病痊","f":"五言律诗","c":["病合当求去，宦情非是阑。","与其官作病，宁可活无官。","腰膝皆相贺，妻儿亦自驩。","高堂垂万里，谁与说平安。"]},{"t":"苦雨","f":"五言律诗","c":["转觉云沉重，翻疑天苦辛。","横将无厌两，淹杀有情春。","山作龙钟貌，花如失意人。","百钱一斗米，谁与贷官贫。"]},{"t":"宿惠山僧房 其一","f":"五言律诗","c":["小阁寒灰火，清香古佛颜。","潮来吹雨叶，云起叠山鬟。","白恰随人指，青峰送客还。","红尘触处到，长日下幽关。"]},{"t":"宿惠山僧房 其二","f":"五言律诗","c":["排遣何曾达，思惟亦是尘。","病翻为乐果，发在是愁因。","松老皆成佛，花清亦避人。","禅栖如窦许，色色可怡神。"]},{"t":"初晴","f":"五言律诗","c":["暾日迟迟影，和风淡淡新。","山微舒态度，柳小足精神。","宗测当如祖，梁鸿竟傍人。","欲从游客饮，除里觅纱巾。"]},{"t":"偶成 其一","f":"五言律诗","c":["世事怜贪饵，同群怖独翔。","摊书时引梦，临水或思乡。","兄弟皆丘小，山林之日长。","行藏细检点，多半是襄阳。"]},{"t":"偶成 其二","f":"五言律诗","c":["佛大刚盈尺，山高也避尘。","时时闻戒定，法法遇贪嗔。","竹粉遗天女，松脂食道人。","南能休借阅，即汝是前身。"]},{"t":"偶成 其三","f":"五言律诗","c":["羁客胸怀少，天涯侣伴稀。","未须愁独立，终是念归飞。","云来吹水叶，潮去落沙衣。","酷忆湘江上，梅花伴钓矶。"]},{"t":"寄江进之","f":"古风","c":["吏老心尤苦，才清调转孤。","花飞常乱押，梅气欲侵符。","旧俸开来否，新粮勾也无。","政成须勉强，尺步是?途。"]},{"t":"嘉兴道上过古寺","f":"五言律诗","c":["金尽沙为地，竹枯水过篱。","龙池蛙带子，佛顶雀衔儿。","古迹钱王是，残经宋代疑。","道旁龟剥落，草里卧丰碑。"]},{"t":"嘉兴道中","f":"五言律诗","c":["弥野桑成市，排溪柳作衙。","菜香齐吐甲，树煖欲蒸花。","天色滑如卯，江容润似纱。","酒帘青带日，三五聚邹家。"]},{"t":"过龙井示德舟禅人","f":"五言律诗","c":["数盘行井上，百计引泉飞。","画壁屯云族，红栏蚀水衣。","路香茶叶长，畦小药苗肥。","宏也学苏子，辨才君是非。"]},{"t":"饮湖心亭","f":"五言律诗","c":["便可无方丈，何须说洞庭。","虽云旧山水，终是沾丹青。","浓淡妆常变，天乔性亦灵。","白波千丈许，众好湖心亭。"]},{"t":"灵隐路上 其一","f":"五言律诗","c":["柳缕时常罥，花溪不断飞。","因寻涧底水，忽过树傍扉。","面熟逢僧问，心闲数客归。","沿流多石趾，尽可作渔矶。"]},{"t":"灵隐路上 其二","f":"五言律诗","c":["柳光吹绿焰，溪雨作红烟。","花气蒸云熟，石纹带乳鲜。","闻香知草性，随例与茶钱。","淡冶应无比，幽奇亦可怜。"]},{"t":"灵隐路上 其三","f":"五言律诗","c":["细鸟伤心叫，闲花作意飞。","芳蹊红茜雨，古涧绿沈衣。","艳女逢僧拜，游人缓骑归。","幸随真寔友，无复可忘机。"]},{"t":"过灵峰","f":"五言律诗","c":["冥漠烟如醉，空濛日带青。","有山兼有涧，宜榭复宜亭。","避客愁云热，拜僧怕佛灵。","无心竖拂子，随意举莲经。"]},{"t":"过龙井","f":"五言律诗","c":["都说今龙井，幽奇踰昔时。","路迂迷旧处，树古失名儿。","渴仰鸡苏佛，饥参王版师。","因循坐谷口，欲去复还疑。"]},{"t":"去湖上","f":"五言律诗","c":["浪迹西湖上，儿童问总知。","能言出入处，及与往来期。","不忍题归字，终难滞许时。","眼前虽别去，只恐病相思。"]},{"t":"天真书院阳明讲学处","f":"五言律诗","c":["百尺颓墙在，三千旧事闻。","野花粘壁粉，山鸟煽炉煴。","江亦学之字，田犹画卦文。","儿孙空满眼，谁与荐荒芹。"]},{"t":"初至绍兴","f":"五言律诗","c":["闻说山阴县，今来始一过。","船方革履小，士比鲫鱼多。","聚集山如市，交光水似罗。","家家开老酒，只少唱吴歌。"]},{"t":"吼山观石壁","f":"五言律诗","c":["知不是天造，良工匠意成。","千年云气老，七日浑沌生。","精祟虚无出，猿猱叹息行。","道傍因借问，恐是越王城。"]},{"t":"兰亭","f":"五言律诗","c":["定武石空在，兰亭迹已讹。","清流大概是，峻岭果然多。","古屋穿新霤，苍松瘦老柯。","墨池閒贮水，犹得放邹鹅。"]},{"t":"诸暨县","f":"五言律诗","c":["近水多鱼稻，依山即市廛。","野人朝闭户，溪女夜牵船。","俗健惟贪讼，田宽务积钱。","僻居游辙少，客到也喧传。"]},{"t":"赠高峰","f":"五言律诗","c":["捉得松为柄，粘来纸作衾。","山云娇老态，溪水有无心。","挂锡沉香树，安禅天竹林。","西来闲会取，空迹寄飞禽。"]},{"t":"赠海禅","f":"五言律诗","c":["海公知道者，闲雅好威仪。","饷客云千斛，论心棒一枝。","岂无真法友，毕竟所依谁。","余亦贪佛去，因君乞圣师。"]},{"t":"宿双清庄赠印上人","f":"五言律诗","c":["百折琉璃沸，千峰帝网罗。","更忧尘界少，却碍岭云多。","说法乌成马，穷源水是波。","死关真个死，赚尔儿孙何。"]},{"t":"赠莲小师","f":"五言律诗","c":["解法生明本，登山熟导师。","闭门常礼忏，会境也题诗。","耘石分香草，煎花供茗糜。","人天一只眼，望汝小厮儿。"]},{"t":"潘庚生馆同诸公得钱字","f":"五言律诗","c":["山色重重冶，云容片片鲜。","花风香水气，梅雨润苔钱。","茶别松萝味，兰销鹊尾烟。","每于诗外旨，悟得句中禅。"]},{"t":"赠景升","f":"五言律诗","c":["麈柄韵如屑，匡床味似禅。","闲惟追酒伴，忙亦检诗编。","是客皆停辙，何人不道贤。","聪明事事有，大抵只无钱。"]},{"t":"宿落石台山房 其一","f":"五言律诗","c":["苍翠垂三亩，凉阴可一庭。","茶烟和雾出，灯影入流青。","快眼山容熟，蒸岩雨气腥。","溪声寒到枕，阖户了遗经。"]},{"t":"宿落石台山房 其二","f":"五言律诗","c":["不独林园胜，居停更可儿。","云生卧地石，山压傍墙枝。","字母逢僧转，文心问水知。","看君举业好，岐路不须疑。"]},{"t":"泛溪","f":"五言律诗","c":["小筏平如舫，文纱蔽赤栏。","只贪下水易，谁识上滩难。","蕨粉和为馔，石班鲙作盘。","梅天多骤雨，重来晚亦寒。"]},{"t":"新安江 其一","f":"五言律诗","c":["一里垂千折，一山近万盘。","草髡和尚岭，石腐秀才滩。","入峡逢天小，投厓叹鸟难。","轻舟薄似纸，未惯也心寒。"]},{"t":"新安江 其二","f":"五言律诗","c":["咫尺愁溪尽，萦回觉路疑。","小舟尖似履，细缆密如丝。","下水贪奇峻，归舟叹崄巇。","相逢不用羡，亦有放流时。"]},{"t":"新安江 其三","f":"五言律诗","c":["怪石穿江出，江寒石亦寒。","或从舟底见，或作假山看。","聚客多茶店，逢人上米滩。","溪流虽较险，下水也平安。"]},{"t":"新安江 其四","f":"五言律诗","c":["浪恶石尤恶，肤青骨亦青。","玄岩听鬼语，野烧炙龙醒。","树古疑唐族，碑攲或宋铭。","可知太白老，浪说有猩猩。"]},{"t":"新安江 其五","f":"五言律诗","c":["市郭全然少，崖邹大底同。","溪云千片黑，山火一丝红。","暴雨蒸沙气，高岩返去风。","骤来应骤解，昨夜月如弓。"]},{"t":"新安江 其六","f":"五言律诗","c":["山都吟复笑，猩语是耶非。","易黑江湖面，纯青客旅衣。","草根鱼子长，沙末燕儿飞。","家信云梢去，郎归计日归。"]},{"t":"新安江 其七","f":"五言律诗","c":["云细蒸山出，溪登见底空。","买盐多妇女，羡水尽儿童。","江有往来浪，神无南北风。","暴流皆石齿，得失在头工。"]},{"t":"新安江 其八","f":"五言律诗","c":["草丰不辨树，山隐却如烟。","客舫因滩浅，牵夫傍兕眠。","谁家朝奉去，几得少年还。","历尽江儿水，嬴来合子钱。"]},{"t":"新安江 其九","f":"五言律诗","c":["浪子由来苦，行人大抵劳。","山云低压帽，溪雨恶侵袍。","欲得恣心意，除非伐顶毛。","将鸥与鹜比，毕竟是谁高。"]},{"t":"新安江 其十","f":"五言律诗","c":["凉风沁石骨，快雨过山头。","筏上行沙鼠，云中啸老猴。","天长鸭绿水，斛许翰青舟。","万里游垂尽，六休休未休。"]},{"t":"赠心湛一小师","f":"五言律诗","c":["布衲裁烟雾，蒲团藉草莎。","雷峰定里火，湖水观中波。","削发嫌根在，忌言恨舌多。","少年色力健，魔佛奈他何。"]},{"t":"拜长耳和尚肉身","f":"五言律诗","c":["轮相居然足，漆光与鉴新。","神魂知也未，爪齿幻耶真。","一个庄严佛，千年骨董人。","饶他铜与铁，到此亦成尘。"]},{"t":"憩法相","f":"五言律诗","c":["峰脚微微仄，篁梢个个清。","听钟龙忏悔，入室虎经行。","鞭笋和泥重，头茶带纸轻。","山僧谈往事，一倍惜尘情。"]},{"t":"留别黄道元","f":"五言律诗","c":["踪迹频频至，邻僧个个知。","会多嫌话少，坐久畏驴饥。","说虎归途快，怀鸳夜梦痴。","一灯禅榻下，睡著小沙弥。"]},{"t":"戊戌元日潘景升兄弟偕诸词客邀余及洪子崖知县踏青真州东郊以云霞梅柳句为韵余得度字","f":"五言律诗","c":["一里一停帴，摇摇驻青雾。","歌长牙扳温，酒响觥筹度。","雪尽露山身，沙平吞水步。","涧冷涩春泉，芽香吐枯树。"]},{"t":"淮安舟中 其二","f":"五言律诗","c":["兀兀叹淫滞，西风两日馀。","近床铺纸叶，研彩类方书。","触目无非网，登盘只是鱼。","荒村经水后，十屋九家虚。"]},{"t":"淮安舟中 其四","f":"五言律诗","c":["河堤千里道，柳缕万条肠。","客是粘愁蒂，禅为治苦方。","乡思鱼子饭，酒梦蛤蜊汤。","渐觉读书懒，游蛛网笔床。"]},{"t":"宿房村","f":"五言律诗","c":["野廓吹加劲，膏微影渐黄。","残垆煨粪火，败絮拥蒿床。","站远酸皮骨，沙飞涩胃肠。","离魂相伴往，合眼见江乡。"]},{"t":"徐州道中","f":"五言律诗","c":["西风吹日夜，千里旱沙黄。","马急知缰促，人疲觉路长。","安心犹有法，医懒却无方。","何不遂长往，淹淹名利场。"]},{"t":"济宁守邀饮南池","f":"五言律诗","c":["踏影入春丛，碑荒榻半空。","树分菱藻月，滩响鹭鸶风。","落絮粘行牍，残觥谑小童。","夜深铃卒语，窗外一枝红。"]},{"t":"入燕初遇伯兄述近事","f":"五言律诗","c":["撇却閒嚣冗，残书且自哦。","官贫人事减，客久面纹多。","坏壁涂僧豫，高窗见鸟窠。","词曹虽冷秩，亦复慎风波。"]},{"t":"尊经阁偶成","f":"五言律诗","c":["一月户长扃，幽廊雨过腥。","云生山被酒，客去鸟听经。","碑古漏痕遍，槐高日影青。","郑家书带草，随意满斋庭。"]},{"t":"学斋留梅子马","f":"五言律诗","c":["踏尽高槐影，青虫落酒巾。","袖怀三月草，衣浣一年尘。","梦里听朝事，杯中觅圣人。","贫厨非大祭，未有肉留宾。"]},{"t":"送张西麓之任罗平","f":"五言律诗","c":["疋马夜郎西，层山万绿齐。","空江行罔象，瘦岭出偏蹄。","番牒多如篆，蛮歌乍似啼。","僻乡名迹少，慎勿厌标题。"]},{"t":"游满井","f":"五言律诗","c":["怪我频来去，无樽亦啸歌。","店荒酤酒浊，僧近施茶多。","竹里分黄阙，波间语翠娥。","溪光最胜处，高柳荫长坡。"]},{"t":"刘常侍水轩 其一","f":"五言律诗","c":["入室翠层层，秋容分外澄。","花分西内种，树古北朝僧。","波净寒生簟，峰高夜见灯。","墨光浓淡里，山水赵吴兴。"]},{"t":"刘常侍水轩 其二","f":"五言律诗","c":["随意移床枕，无窗不可眠。","西山篱落下，流水卷炉边。","茭叶遮城垒，荻花隐寺田。","儿童私打网，时有白鱼鲜。"]},{"t":"刘常侍水轩 其四","f":"五言律诗","c":["敞屋高临水，卑垣奥作庐。","山僧能咒树，童子解医鱼。","剑玦充文具，歌谣集古书。","之乎亦不识，糟却几盈虚。"]},{"t":"尊经阁偶题","f":"五言律诗","c":["长戚戚何为，曲肱愧孔尼。","草髡苗败砌，树老落乾枝。","飞鸟衔残字，园丁榻旧碑。","邻斋四五叟，日日染愁髭。"]},{"t":"双寺逢本上人","f":"五言律诗","c":["高僧如疼鹤，懒得著袈裟。","雪案堆庄子，花函藏内家。","问方医病竹，邮水泛春茶。","一室沉香气，青烟吐白纱。"]},{"t":"坐小修斋中","f":"五言律诗","c":["寒日篱花少，虚窗五尺馀。","砚皴呵绣墨，壁老剧垂书。","定业诗调冶，幽忧酒破除。","家人攀釜看，绨锦当黄糈。"]},{"t":"送白教谕之昌邑","f":"五言律诗","c":["依旧中山氏，长然即墨侯。","衣宽存礼乐，箧敝裹阳秋。","渤日流红晕，盐花上黑头。","到时图海市，东去是登州。"]},{"t":"送艾教谕之镇安","f":"五言律诗","c":["一百二秦地，三千五去程。","山鲜充豆品，野服礼诸生。","把卷听夷乐，开轩见虎行。","犹将京国意，一洗近边城。"]},{"t":"冬日杂兴 其一","f":"五言律诗","c":["残菊收新药，丹书缀断编。","砚呵胶婢指，苔老夹冰钱。","百衲支风惯，空杯见雪颠。","缄书报知己，霜满蜡花笺。"]},{"t":"冬日杂兴 其二","f":"五言律诗","c":["泻纸罗纹滑，飞枰石子寒。","菊衰愁别蒂，鹤老梦归滩。","香重红膏泣，粉枯白蠹残。","寄声询衲病，驰帖报花安。"]},{"t":"冬日杂兴 其三","f":"五言律诗","c":["雪炷抽寒焰，辰香扫炙尘。","谱词分侍女，鬻帖与门人。","边信封黄鼠，乡心想白鳞。","卑官与大吏，一种逐蹄轮。"]},{"t":"冬日杂兴 其四","f":"五言律诗","c":["残帙随风卷，閒窗尽日哦。","胆瓶青剥落，梵呗语殽吪。","寒节逢人少，新诗说酒多。","小蛮持管笑，呵墨写长蛾。"]},{"t":"美人临镜 其一","f":"五言律诗","c":["一片湖州水，吹光到晓堂。","暗规时世样，校取浅深妆。","山髻平分叠，宫眉与斗长。","常时樈掠罢，背底立何郎。"]},{"t":"美人临镜 其二","f":"五言律诗","c":["强起淹馀睡，柔多艳亦多。","笑时添两靥，恨至叠双蛾。","印指生寒晕，分钗割水波。","休将月月比，仙子不如他。"]},{"t":"美人临镜 其三","f":"五言律诗","c":["野艳云争出，幽閒萼并头。","分明呈舞态，只是欠歌喉。","西子不离水，绿珠长在楼。","娥英若令见，匣取洞庭秋。"]},{"t":"美人临镜 其四","f":"五言律诗","c":["百看百如意，随他作笑颦。","回钗生溜影，分耀及旁人。","睡少添自重，思多理注频。","面光滑似水，脂粉不如尘。"]},{"t":"送武冈州判张子之任","f":"五言律诗","c":["雉堞倚山乡，青娥立晓堂。","胥徒勤检点，蛮语细参详。","湘竹裁荆杖，藤花上牍床。","荒衢通野落，士女半夷装。"]},{"t":"人日","f":"五言律诗","c":["旅况无些子，空扉阅广轮。","气寒薪少力，客谢几生尘。","心切投林羽，身悲贷沬鳞。","滔滔人尽是，未始出非人。"]},{"t":"谷日怀潘景升","f":"五言律诗","c":["西湖多少地，客信也难知。","流落依何氏，巉岏历几支。","吴娘嗔罄橐，杭粉上愁髭。","记得拈杯处，题分谷字诗。"]},{"t":"题龙腾山房","f":"五言律诗","c":["急雨朝翻箔，飞泉夏入庐。","竹高遗凤子，石长出雷书。","山鸟衔云语，园丁带翠锄。","南冈北岭草，枯却几年馀。"]},{"t":"王氏双节","f":"五言律诗","c":["玉折苦相仍，彤编合并称。","泪枯双井水，心死万年冰。","恶粉常芟竹，凄花每避镫。","霜眉白似缕，阅尽几衰兴。"]},{"t":"花朝日白苏斋看梅","f":"五言律诗","c":["一倍惜花时，寒香滴酒卮。","幸依无事客，且喜不蟠枝。","近枕通幽梦，安禅伴净尼。","未知白苏老，酬唱几番诗。"]},{"t":"昌平道中","f":"五言律诗","c":["柳条新婉娈，麦陇渐柔丰。","闪日云光薄，翻空旆影红。","马嘶不见鬣，毂响但闻风。","恰为青山去，青山尘雾中。"]},{"t":"谢在杭钟樊桐诸凡集郊外","f":"五言律诗","c":["百晤百回新，肝肠绝少尘。","未言先侧耳，每笑必伤神。","落翠沾行帢，空罂惑醉人。","石潭清到底，信手出纤鳞。"]},{"t":"送李湘洲使浙 其一","f":"五言律诗","c":["咫尺山东道，千艘与万舻。","邮栖常下鹤，驿饭一炊菰。","闭口听朝事，降心祖佛徒。","不言知向越，面上有西湖。"]},{"t":"送李湘洲使浙 其二","f":"五言律诗","c":["别路红桥上，无情亦有歌。","青山遮道石，流水拍云波。","北阙新知少，西湖熟梦多。","向来题字处，墨沈遍嵯峨。"]},{"t":"秋日集江进之王以明方子公王章甫小修饮崇国寺","f":"五言律诗","c":["露叶滴秋窗，竹香入酒缸。","娇青槐子破，浅嫩菊丫双。","石火增茶韵，松音出梵腔。","冥心真契理，瓮里有莲邦。"]},{"t":"九日天慧寺登高迟家伯修黄平倩不至","f":"五言律诗","c":["苍色满诸峦，如何独自看。","閒僧四五众，丈石两三盘。","白额题高冢，红衫度远栏。","北风浸骨冷，端不似秋残。"]},{"t":"过通州","f":"五言律诗","c":["白舫绿油扉，多时梦亦稀。","浪中丹雉见，郭里水禽飞。","古寺荒何代，空杨瘦十围。","四年一带水，三度断肠归。"]},{"t":"寒溪道中","f":"五言律诗","c":["空岩著古花，石路水纹斜。","瘦野多耘枣，桑门屡饷茶。","逢人皆说旱，上马但愁砂。","匣地诛求尽，孤云也失家。"]},{"t":"丛台","f":"五言律诗","c":["梦绕陌花薰，残宫没野耘。","秋空吪凤泪，阴谷女龙云。","古水空沉照，飞蛾每化裙。","苔封埋半碣，斑剥有遗文。"]},{"t":"雨中过王官谷香光林 其一","f":"五言律诗","c":["脱屐入春丛，拾芳携翠笼。","一番洗竹雨，几阵报花风。","薪老知茶忌，须长论药功。","疏黄秾碧里，一树石楠红。"]},{"t":"雨中过王官谷香光林 其二","f":"五言律诗","c":["为药常烧竹，贪僧每贮粮。","观心三点字，叠膝一绳床。","谱石增新样，和香觅旧方。","黄柑栽未几，已得五拳长。"]},{"t":"风柳","f":"五言律诗","c":["夏后倾城喜，羊家通体腰。","蝶魂抛冷絮，莺梦恼娼条。","几日青门道，当时红版桥。","閒思与閒恨，种种逐烟销。"]},{"t":"和王以明山居韵 其一","f":"五言律诗","c":["蜡屐先春试，新诗倍日吟。","为花常驻马，有字即题襟。","竹老云辞去，廊空月到深。","将何伴幽冷，水响与柯音。"]},{"t":"和王以明山居韵 其二","f":"五言律诗","c":["自候烹茶火，閒开看竹窗。","方情四五众，花事两三桩。","古注多题什，邻翁也姓庞。","虚空系得否，无起亦无降。"]},{"t":"和王以明山居韵 其三","f":"五言律诗","c":["小石含山意，柔风寓冶情。","卷终香字损，禅起夜绵轻。","第水兼新品，注花带别名。","晴沙看鸥母，引得小雏行。"]},{"t":"和王以明山居韵 其四","f":"五言律诗","c":["饱食长腰米，高撑过顶枝。","閒寻施药地，细剖讼花辞。","雾眼添灯晕，云瓢挂瘿师。","山斋通夜雨，肠断子瞻诗。"]},{"t":"和王以明山居韵 其五","f":"五言律诗","c":["细鸟藏窗叶，幽花缀静枝。","猎心生翠管，冶习露春诗。","为发添尘罥，因寒罢讲期。","贪嗔真可去，何事并除痴。"]},{"t":"和王以明山居韵 其六","f":"五言律诗","c":["洁得如霜室，层层尽岳图。","僧贻少室屦，舶买岭南盂。","径僻花争发，林深鸟尽趋。","趁时先贮酿，莫遣渴来沽。"]},{"t":"和王以明山居韵 其七","f":"五言律诗","c":["拨却閒生事，孤清亦可风。","半痕离树月，一影没池鸿。","种菊防沙虱，加绵滤水虫。","近郊多麦陇，青鬣好柔丰。"]},{"t":"和王以明山居韵 其八","f":"五言律诗","c":["几日穷彫镂，嗒然一遇之。","辟如风与水，相识忽成漪。","梦清云入肺，吟定发生岐。","好挟飞仙去，深山伴种芝。"]},{"t":"柳浪馆月中泛舟","f":"五言律诗","c":["烟树湿茙茙，残缸细隐红。","池容通国水，柳散一城风。","僧静能消月，庭方好贮空。","幽窗渔梵冷，童子印香终。"]},{"t":"潇湘舟中别某禅人","f":"五言律诗","c":["山深影独翔，湍月似冰凉。","石入分泉玺，莓生滤药囊。","树头悬笠子，经背写花方。","若过湘君去，琅玕截许长。"]},{"t":"岳阳舟中同诸上人语","f":"五言律诗","c":["槵子碧丝绳，官程亦伴僧。","每闻静者语，似饮热时冰。","隙月冲帘幌，高云谢缴矰。","七番经过地，话尽一窗灯。"]},{"t":"汉阳逢丘长孺 其一","f":"五言律诗","c":["不是频游地，如何亦遇君。","相看唯惜死，所问不离云。","白帢增官韵，黄蕉织水纹。","冶心今较可，敝笈委缃裙。"]},{"t":"汉阳逢丘长孺 其二","f":"五言律诗","c":["解跃穿花辔，学披细叶衣。","诗于七字长，面较别时肥。","怒石当江立，腥鸢跕水飞。","他时蒲社饮，倍感友朋稀。"]},{"t":"舟中逢周行可","f":"五言律诗","c":["君是滕元发，长舠破浪来。","入群瞻岳岳，顾水影䰄䰄。","黄石曾窥奥，稠林每乱才。","通侯画地取，筠管亦何哉。"]},{"t":"登平山阁同江浦诸友论文","f":"五言律诗","c":["石路突寒松，柔岚被远封。","白波千里舶，青叆六朝钟。","云老蛟迁窟，窗晴雨洗峰。","文心喻烟水，吞吐几重重。"]},{"t":"将抵家园作 其一","f":"五言律诗","c":["都说还家乐，今来无此情。","稍稍亲宿累，渐渐入愁城。","岳月随归梦，芦风作苦声。","令人仇鬓发，遮我学无生。"]},{"t":"将抵家园作 其二","f":"五言律诗","c":["况是风吹旐，那能石作肝。","一门冰水泪，千里路人寒。","痛绝椿堂雪，孤他熊胆丸。","郭西原上草，曾是绣归看。"]},{"t":"冬尽","f":"五言律诗","c":["怕见历头残，穷年逼小寒。","见人黑发去，自检白髭看。","好句逢僧得，新怀语客难。","云山与烟水，梦著也成欢。"]},{"t":"除夕观诸公饮","f":"五言律诗","c":["剪却残膏穗，閒观未了棋。","角杯穷酒事，分帖记花时。","白发羞螺子，青溪访钓丝。","买棕新作笠，江海任吾之。"]},{"t":"雪霁看月和度门韵时将发玉泉","f":"五言律诗","c":["一片牙光地，南宫墨不成。","近窗花淡泊，就枕梦孤清。","吊古前朝泪，耽幽后夜行。","刻期峰顶上，踏雪共题名。"]},{"t":"舟中元夕偶谈郡中旧事","f":"五言律诗","c":["又见一回圆，长江净可怜。","稍谈朝野事，递语盛衰缘。","万井浓华歇，孤灯沙雪前。","瓶梅香楚楚，似欲嬲枯禅。"]},{"t":"元夕舟中同马元龙夜话","f":"五言律诗","c":["夜深蜡燄残，月色净诸峦。","近水临窗语，和烟带树看。","貌兼杉影瘦，思入井冰寒。","办得一番死，参禅也不难。"]},{"t":"荆门道中 其一","f":"五言律诗","c":["山势错隆隆，斜畴苦稼同。","看人登迅坂，叱马作聋虫。","废驿崩桥石，闲花远坞风。","私营与公事，了不到心中。"]},{"t":"荆门道中 其二","f":"五言律诗","c":["十度麦城道，三分汉寿侯。","蛮乡耘土瘦，鬼俗见鸦愁。","烈迹穷诸夏，青山让北丘。","毗尼称弟子，荤血可能休。"]},{"t":"岘山道中闻颂汪使君德政诗以纪之","f":"五言律诗","c":["閒坐说循良，青槐古影凉。","横身遮数郡，一笑檡权珰。","通国嫌称户，生男必字阳。","小儒无大计，束手叹非常。"]},{"t":"入琼台观 其一","f":"五言律诗","c":["涧路曲盘盘，闻香又隔滩。","岩攲天古拙，石瘦月高寒。","屡共云封事，曾闻鸟纪官。","人间三万日，洞里不相干。"]},{"t":"入琼台观 其二","f":"五言律诗","c":["一帕覆长眉，深衣大带垂。","无通名姓地，有驾鹄鸾时。","为客烹乌药，教人悟白髭。","声名与荣利，膏火露花儿。"]},{"t":"智者洞","f":"五言律诗","c":["其下有龙渊，潜通印度天。","云畴螺子地，雾顶树王年。","就石为君枕，迷津指我船。","向来神怪事，勿为小儒传。"]},{"t":"龙湾市","f":"五言律诗","c":["閒坐说渚宫，高台集古枫。","万家寒鉴上，一国水轮中。","游蛤秋怀月，归蛟夜战风。","楚天波捲去，鱼鸟尽依空。"]},{"t":"生女","f":"五言律诗","c":["闻啼知得雌，一笑慰衰羸。","龟筴频占凤，家人屡梦丝。","瓶花香娈娈，窗竹粉离离。","从此添婚嫁，因名向累儿。"]},{"t":"元日书怀 其一","f":"五言律诗","c":["口合任烟云，全家鸥鹭群。","软黄将柳信，滑碧上溪纹。","花榭因窗作，葑田带水耘。","湖塘三十顷，自著藕根分。"]},{"t":"元日书怀 其二","f":"五言律诗","c":["商略正王事，更番作野游。","三童四冠者，西岭北江头。","水巷连祠竹，沙村带石洲。","官私与禅讲，一味劝心休。"]},{"t":"偶成","f":"五言律诗","c":["閒坐阅年光，青阳倍倍长。","渐升贫等级，乍入老班行。","僧说观空法，道言续命方。","酒人频启事，曲蘖供心王。"]},{"t":"月下偶成","f":"五言律诗","c":["冗懒遂成性，人皆笑此翁。","坐依藤架月，行傍藕塘风。","万事溪声外，一生云影中。","自从甘曲枕，不复梦三公。"]},{"t":"夏五雨不止","f":"五言律诗","c":["宴坐乌皮几，昏昏似苦禅。","夜烧防水吏，街鼓送神船。","野客团茶社，山僧访芋田。","尊罍那得满，旋典葛衣钱。"]},{"t":"赋得风雨亦来过","f":"五言律诗","c":["寤寐高斋柳，穷阴到亦多。","云齐千亩稻，雪捲四时波。","竹里垆烟出，花间艇子过。","醉来即高枕，梦境也清和。"]},{"t":"早秋晓行入寺","f":"五言律诗","c":["溪深菱芡香，花落读经床。","露叶千畴拭，风梢一院凉。","白头鹫目子，玄饮乌梅汤。","转入村林去，瓶罍只自将。"]},{"t":"秋夜独坐看月","f":"五言律诗","c":["净绿云千树，玲珑月一池。","就花来扫石，宿羽忽垂枝。","懒与烟霞称，閒干水竹宜。","山中招静侣，几客似鸬鹚。"]},{"t":"柳浪杂咏 其一","f":"五言律诗","c":["假寐日高舂，青山落枕中。","水含苍藓色，窗满碧畴风。","适性营花石，书方去鸟虫。","酒人多道侣，醉里也谈空。"]},{"t":"柳浪杂咏 其二","f":"五言律诗","c":["蕉衫乌角中，半衲半村民。","蒋药常占日，浇花每刻辰。","涧毛分净侣，瀼水贷西邻。","卒岁学为稼，樊须也小人。"]},{"t":"柳浪杂咏 其三","f":"五言律诗","c":["得得寻花去，冲烟过柳居。","见僧询母字，为客检方书。","幽梦通巢鹤，閒心系沼鱼。","浮尘无可竞，竞得也空虚。"]},{"t":"八月十二日同诸公看月水轩","f":"五言律诗","c":["扫却层云去，无尘可翳空。","凿窗临水上，引月到亭中。","入座鸥凫气，吹衣荇藻风。","开尊半白首，宁不借脂红。"]},{"t":"柳浪雨中时亲朋多自场中归","f":"五言律诗","c":["自起约书床，炉烟细细长。","稍呼营酒客，新试焙茶方。","夜雨花棚绽，朝盘豆角香。","亲朋递来往，閒与校头场。"]},{"t":"两弟自文战归","f":"五言律诗","c":["离却至公堂，飞舠出汉阳。","新衣荷碧色，远瓮蟹黄香。","笺牍频频出，文章字字商。","家传弧矢诀，个个解穿杨。"]},{"t":"和散木韵 其一","f":"五言律诗","c":["閒适也相宜，楸枰彻暮棋。","晚花残蓓蕾，古榻乱装池。","云脚才收雨，秋容渐上诗。","家家贮新酿，等取菊开时。"]},{"t":"和散木韵 其二","f":"五言律诗","c":["君监冯敬通，休心壮岁中。","治生菱浦月，送老石门风。","每笑横波日，閒怜戴屋虫。","禅锋示妻子，输我作庞公。"]},{"t":"和散木韵 其三","f":"五言律诗","c":["只合卧云休，闲驱款段游。","愁来鸥失渚，梦里鹿寻丘。","碧水青烟市，红柑白果秋。","斗湖新月里，荡个小渔舟。"]},{"t":"和散木韵 其四","f":"五言律诗","c":["老无出处累，也欲趁些忙。","月课脩花户，日携看麓床。","晓风绵子落，村院瓦松香。","遍郭谋新酿，空杯待夕阳。"]},{"t":"和散木韵 其五","f":"五言律诗","c":["间随马少游，乡里度春秋。","洗药松根下，分花水市头。","请云遮谷口，与俗割鸿沟。","一味鸥鹥去，长年百不忧。"]},{"t":"和散木韵 其六","f":"五言律诗","c":["落叶蔽秋矶，残霞雨洗晖。","弹花蝉虎匿，掠竹水鹰飞。","白足遗棕屦，青娥送道衣。","庖童觅鲙去，兼买紫姜归。"]},{"t":"和散木韵 其七","f":"五言律诗","c":["遍识今朝士，无如隐者亲。","酒浇种柳客，图写姓庞人。","鹦鹉司茶具，弥猴盗角巾。","赠君柳浪水，堪浣胃中尘。"]},{"t":"和散木韵 其八","f":"五言律诗","c":["空潭独影谁，个是好相知。","每笑鹏心侈，闲怜鹳垒危。","眼光常照渌，面貌日浮卮。","一往青山去，还愁鹤不随。"]},{"t":"再和散木韵 其一","f":"五言律诗","c":["平生四不宜，担粪与围棋。","强捉山公斝，生填逸少池。","窗前微点石，花底小裁诗。","稍欲装风景，休推临老时。"]},{"t":"再和散木韵 其二","f":"五言律诗","c":["藤纸书一通，裴诗王集中。","时清传雅语，格婉变骚风。","丽体收花露，方言辨鸟虫。","绿绨閒贮取，一一示诸公。"]},{"t":"再和散木韵 其三","f":"五言律诗","c":["颠毛老去休，拟伴赤松游。","尽室营新麓，全身观古丘。","云峦閒品藻，花月小阳秋。","欲作天台讯，东阳有便舟。"]},{"t":"再和散木韵 其四","f":"五言律诗","c":["山居饶水石，消得一生忙。","夜雨沉丹灶，秋花蔽井床。","古苔烦树瘿，乾牍老鱼香。","梦里匡山路，斜帆指汉阳。"]},{"t":"再和散木韵 其五","f":"五言律诗","c":["稼圃也优游，山庄又一秋。","迎风收栗子，过雨剪花头。","自洗蒙苔石，聊通滞叶沟。","閒中真本草，蠲忿与忘忧。"]},{"t":"再和散木韵 其六","f":"五言律诗","c":["夜雨水平矶，朝暾树树晖。","笼中珍鸟语，天外拙鸠飞。","古杖藤花笠，垂绦板摺衣。","形容堪尽取，画作虎溪归。"]},{"t":"再和散木韵 其七","f":"五言律诗","c":["幽居长在定，直与简编亲。","东鲁先夫子，西方古圣人。","侍儿泉洗面，座客鸟衔巾。","几日僧寮去，山房一半尘。"]},{"t":"再和散木韵 其八","f":"五言律诗","c":["酒正合弹谁，醉乡甲令知。","睡魔槟五岭，愁伯放三危。","词客花盈斗，钱奴醋满卮。","清谭都拨去，只许雅歌随。"]},{"t":"九月二日盛集诸公郊游至二圣寺仍用散木韵 其一","f":"五言律诗","c":["潇散与秋宜，枇杷树下棋。","衣纹粘草地，人影散花池。","石望僧流梵，霞江雁谱诗。","空台聊戏马，预取茱萸时。"]},{"t":"九月二日盛集诸公郊游至二圣寺仍用散木韵 其二","f":"五言律诗","c":["莎径许谁通，香寮紫翠中。","窗衔半岭日，院钱一池风。","认药收花片，阄题得草虫。","玄言三五反，小欲困支公。"]},{"t":"九月二日盛集诸公郊游至二圣寺仍用散木韵 其三","f":"五言律诗","c":["折柬召僧休，儒禅结伴游。","藻心遮戒律，觞改黜轲丘。","壁冷啼虫暮，云盘怒隼秋。","小章閒理楫，歌板上渔舟。"]},{"t":"九月二日盛集诸公郊游至二圣寺仍用散木韵 其四","f":"五言律诗","c":["靖节一生懒，秋来有底忙。","妻儿团菊社，宾客守糟床。","西肆驼蹄熟，东邻蟹甲香。","山中无姓字，呼我作高阳。"]},{"t":"九月二日盛集诸公郊游至二圣寺仍用散木韵 其五","f":"五言律诗","c":["白马紫缰游，溪光湛碧秋。","蛾眉司酒监，大鼻领曹头。","抽点荞花雪，杯香芳叶沟。","山房开料理，菊晚是吾忧。"]},{"t":"九月二日盛集诸公郊游至二圣寺仍用散木韵 其六","f":"五言律诗","c":["閒寻古钓矶，树影与波晖。","乾鹊一生喜，焦鹩半亩飞。","奴嚣亡酒具，客醉唾僧衣。","又趁芦花去，长歌缓棹归。"]},{"t":"九月二日盛集诸公郊游至二圣寺仍用散木韵 其七","f":"五言律诗","c":["偶然深树里，乍得野鸥亲。","蔓棘衣閒路，松风聒静朲。","桥边红累子，花底碧纱巾。","怕掠青苔去，空阶不扫尘。"]},{"t":"九月二日盛集诸公郊游至二圣寺仍用散木韵 其八","f":"五言律诗","c":["独树扣镶谁，幽人觅故知。","斜鬟溪女笑，丫路板桥危。","山户虫封蜡，花乡果旧卮。","白公君记取，是处有僧随。"]},{"t":"九月初五日得三弟京闱第三报志喜仍用散木韵践前约也 其一","f":"五言律诗","c":["高科晚最宜，先著是卑棋。","潭跃新龙子，天还旧凤池。","恩门侵晓辔，秋卷早朝诗。","一点射堂月，开尊忆昔时。"]},{"t":"九月初五日得三弟京闱第三报志喜仍用散木韵践前约也 其二","f":"五言律诗","c":["东华晓气通，南省谢班中。","绝景霜蹄道，垂天老翮风。","酒浇退笔冢，花煖蛀书虫。","更念同门友，蓝衫待至公。"]},{"t":"九月初五日得三弟京闱第三报志喜仍用散木韵践前约也 其三","f":"五言律诗","c":["磊块破除休，几年禽向游。","全家呼季子，举国号糟丘。","帝里云霞烂，故山松桂秋。","名成不受爵，同上五湖舟。"]},{"t":"九月初五日得三弟京闱第三报志喜仍用散木韵践前约也 其四","f":"五言律诗","c":["读书依梵侣，静里几番忙。","白骨通文字，青蒲作讲床。","月花根干老，天女鬘鬟香。","偶见题名处，桃灯感渭阳。"]},{"t":"九月初五日得三弟京闱第三报志喜仍用散木韵践前约也 其五","f":"五言律诗","c":["四海论交游，文场二十秋。","卷中生紫燄，镜里换霜头。","古寺邻宫月，寒淙响御沟。","高堂微启齿，销却几年忧。"]},{"t":"九月初五日得三弟京闱第三报志喜仍用散木韵践前约也 其六","f":"五言律诗","c":["辞却旧花矶，红尘踏晓晖。","蚕心千叶老，蝶翅九衢飞。","爱纽缠高士，浓竿饵布衣。","贤昆得第日，走马看山归。"]},{"t":"九月初五日得三弟京闱第三报志喜仍用散木韵践前约也 其七","f":"五言律诗","c":["慷慨歌燕市，依然屠狗亲。","远山随酒媪，胡粉抺天人。","异服花纹裤，高风垫角巾。","绯桃一夜雨，浣却素衣尘。"]},{"t":"九月初五日得三弟京闱第三报志喜仍用散木韵践前约也 其八","f":"五言律诗","c":["百亩青山谁，孤藤即旧知。","閒云投远旷，倦羽避高危。","重叠花前板，朋从几上卮。","满板三五稔，季也掷冠随。"]},{"t":"舟行黄金口同散木王回饮","f":"五言律诗","c":["乡落也陶然，篱花古岸边。","田翁扪虱坐，溪女带竿眠。","小港芦租户，低仓米税船。","河刀与生酒，兴剧不论钱。"]},{"t":"又九日偕诸叔及诸季昆散木陈正夫王回登高孟溪剧饮","f":"五言律诗","c":["笑谑略卑尊，飞筹迭盎盆。","一湾茶枣市，合族水云村。","小管吹芦叶，魁罍卧柳根。","未须量斗石，强饮倍齐髡。"]},{"t":"和散木登高之作","f":"五言律诗","c":["落日度微岑，红霞带碧林。","渔箱风卷目，客哨晚传金。","波瞥劳鱼尾，云桃古鹤心。","醉归如梦里，歌马路昏沉。"]},{"t":"村居杂题 其一","f":"五言律诗","c":["古柳半心枯，楼台泻碧湖。","山花权作侑，溪鸟乍名奴。","邻叟询难字，田家挂历图。","老松饶韵格，屋底近千株。"]},{"t":"村居杂题 其二","f":"五言律诗","c":["稍似朱衣巷，儿童问礼诗。","一村垂大带，十里望丹旗。","小榜依蛮市，枯扬引水祠。","树皮如藓石，老尽寄生枝。"]},{"t":"散木和前诗仍用韵答 其一","f":"五言律诗","c":["小雨润苔枯，鱼人集晓湖。","著书要惠子，作帖与官奴。","夜语天台约，秋山瀑布图。","霜花看渐老，著意养寒株。"]},{"t":"散木和前诗仍用韵答 其二","f":"五言律诗","c":["山居无可好，只是好吟诗。","砌叶封虫户，垆花战茗旗。","鱼商填小市，狐粉聚空祠。","偶到骑羊路，红柑缀满枝。"]},{"t":"再和散木韵 其一","f":"五言律诗","c":["空阶锐草枯，山影落澄湖。","花下舂云母，霜中课橘奴。","移家求水石，舍宅事浮图。","一笑掀髯去，孤峰绝顶株。"]},{"t":"再和散木韵 其二","f":"五言律诗","c":["白石青烟梦，空花水月诗。","禅锋摧老敌，糟垒竖高旗。","云湿篬筤岭，江寒社若祠。","榔梅多手植，忽已见孙枝。"]},{"t":"集沈青平斋限韵 其一","f":"五言律诗","c":["霜月寒冲瓦，松风夜入炉。","丽歌飞楚雪，方语杂吴都。","閤里藏幽鸟，花间命女雏。","一窗云气冷，白水对清酤。"]},{"t":"集沈青平斋限韵 其二","f":"五言律诗","c":["角杯椰子酿，沈水博山炉。","酒至申三令，诗成偿五都。","茶花披冷艳，笋竹放冬雏。","痛饮何妨夜，西邻有浊酤。"]},{"t":"斋中閒夜小集 其一","f":"五言律诗","c":["久语绿觥残，重帷犯月寒。","寻常杯酒事，动作岁年看。","石眼穿花瓣，霜岩碎马肝。","静思膏火理，一倍使心安。"]},{"t":"斋中閒夜小集 其二","f":"五言律诗","c":["去去北山残，寒灰决定寒。","随他花锦烂，只作水云看。","空月舒颜面，閒窗语肺肝。","新居频料理，最喜竹平安。"]},{"t":"岁暮书怀得风字 其一","f":"五言律诗","c":["指板付青童，衰颜一笑红。","斜波冰闪日，虚屋柳啼风。","树影溪纹路，鸥心鹤貌翁。","颠毛翮种种，只合老墙东。"]},{"t":"岁暮书怀得风字 其二","f":"五言律诗","c":["衰至学无功，家乡是醉中。","更无催老历，只有解酲风。","日日添髭白，连连唤颊红。","腾腾一沈去，直欲傲天工。"]},{"t":"次峰字韵 其一","f":"五言律诗","c":["平常心远处，即是最高峰。","小辟池三亩，横开室几重。","花枝宜古瘦，酒味去甘浓。","莫道追随厌，读书老亦慵。"]},{"t":"次峰字韵 其二","f":"五言律诗","c":["延沼添回道，当窗卓小峰。","书来燕雪满，梦去越山重。","谷水烹茶冽，螺烟渗纸浓。","经冬人事减，多半为花慵。"]},{"t":"小竹林蜡梅盛开兼赠主人","f":"五言律诗","c":["顿觉水沉粗，幽香袭一湖。","瘦枝梅韵格，鲜蕊桂肌肤。","月下高真梦，烟中静女图。","主人无俗累，花性也清孤。"]},{"t":"和僧韵因赠","f":"五言律诗","c":["山僧能险语，酷似李才江。","坐久衣粘石，人归雪满窗。","看云开竹户，会境写花幢。","手把枯藤去，孤清鹤一双。"]},{"t":"甲辰元旦饮刘绳之梅花下听歌时一衲在侧","f":"五言律诗","c":["卜艳催花发，长眉带柳来。","醉怜回雪舞，老怕失年杯。","笑靥生春晕，禅心试冷灰。","一尊一板去，村舍几题梅。"]},{"t":"花朝月下泛舟限四韵","f":"五言律诗","c":["练水拍平桥，流连暮复朝。","都将花岁月，收入酒科条。","溪閤千场笑，风柯十里腰。","玲珑歌莫止，面上怕红消。"]},{"t":"清明","f":"五言律诗","c":["弱女紫丝筐，藤花刺路傍。","柳繁风絮乱，波浅水茅香。","老学耕田法，贫添省事方。","头茶与鲜笋，刻日待新尝。"]},{"t":"石马庄夜集得封字","f":"五言律诗","c":["苦瘦角诗容，题函半尺封。","夜沉歌板法，窗冷印香慵。","醁泻杯光滟，灯分字影重。","若非文战苦，何以约谈锋。"]},{"t":"竹林限四韵 其一","f":"五言律诗","c":["百回经眼地，倍倍惜高寒。","绕屋香成涧，摩天碧洗澜。","花头丰似颊，枝底啭如丸。","纵是醉名客，频游也挂冠。"]},{"t":"竹林限四韵 其二","f":"五言律诗","c":["百亩亭亭绿，风梢作意寒。","只如无市井，长似有波澜。","适性琴三叠，尊生药一丸。","苍髯白麈尾，都学晋衣冠。"]},{"t":"竹林为官谷物今属小修四岁中凡三易王矣余频年兴作故后半以自箴仍用前韵","f":"五言律诗","c":["阅人如邮舍，旁观意也寒。","年年山易姓，事事水催澜。","免作劳生计，都无驻景丸。","东移复西改，似沐猴而冠。"]},{"t":"偶成","f":"五言律诗","c":["去去白云层，空江理钓罾。","竹方曾受削，樗老不堪绳。","静悟竞巢雀，间观扑纸蝇。","辟纑聊易米，裂却旧吴缯。"]},{"t":"湖上碧酣楼落成","f":"五言律诗","c":["聊作栖身地，遂成隐者家。","三面修閤子，四度看荷花。","碎影方塘月，苍烟活水茶。","稚川徒自累，白首恋丹砂。"]},{"t":"暑中舟行入村舍偕冷云及明教居士 其一","f":"五言律诗","c":["深林枣实红，沙鸟立阴中。","旷野云烧日，平川雨洗风。","酒香知杜近，村静识年丰。","渐看河桥上，提携有醉翁。"]},{"t":"暑中舟行入村舍偕冷云及明教居士 其三","f":"五言律诗","c":["抛却旧衫红，披蓑向此中。","微云缥碧水，深树绿沈风。","官税租能给，山赀了不丰。","扑头随衲子，犹可作庞翁。"]},{"t":"初入村居 其一","f":"五言律诗","c":["割爱聊芟竹，薙荒暂作桥。","云岚披旧址，花鸟历前朝。","涧伏多年雪，山深太古条。","南华志怪者，不达小逍遥。"]},{"t":"初入村居 其二","f":"五言律诗","c":["一派松篁路，聊通曲木桥。","山空狐女啸，树古鸟王朝。","花入玲珑榭，溪分婉娈条。","不知泻近速，只觉去人遥。"]},{"t":"七月六日","f":"五言律诗","c":["瞥眼花成实，惊心鸟作桥。","婆娑巫觋笑，斋沐老僧朝。","薄月疏烟竹，回风怒水条。","馀生施静峤，转觉世途遥。"]},{"t":"山中","f":"五言律诗","c":["是处堪销伏，深林半沼台。","水才驱热去，月适送风来。","滴历松间露，幽澄雨后苔。","十年前后事，电火与飞埃。"]},{"t":"山中限韵","f":"五言律诗","c":["山气亲藤杖，花光耀酒铛。","好风排日至，佳月彻旬明。","僧院棋频覆，田家座屡盈。","腾腾清睡里，證得小无生。"]},{"t":"中秋偕诸衲泛舟洞庭","f":"五言律诗","c":["匝地云销尽，平湖绝点青。","琉璃天子月，香水海王城。","怒蛤排帆立，神鱼掣练行。","山僧精观忍，天倍发光明。"]},{"t":"秋夜宿德山绝顶玩月前此看月江上顶有善卷坛","f":"五言律诗","c":["江月峰头月，清光孰最多。","稍能增潋滟，终是让嵯峨。","玺谷高岩在，苍颜白发何。","古来师善卷，未必解尘罗。"]},{"t":"龙君超邀余过新置山庄庄在翠微中甚幽僻 其一","f":"五言律诗","c":["扫石移尊去，披云曳杖行。","冈峦频转换，郛郭偶生成。","溪尽田家出，山回仄路平。","远峰稠叠起，苍翠扑轩楹。"]},{"t":"龙君超邀余过新置山庄庄在翠微中甚幽僻 其二","f":"五言律诗","c":["閒即攀萝上，倦来枕石眠。","田庐阴翠壁，鸡犬入层烟。","竹院通茶户，山乡近水廛。","主人心但了，胜作苦形仙。"]},{"t":"龙君超邀余过新置山庄庄在翠微中甚幽僻 其三","f":"五言律诗","c":["买足青山地，幽回搆屋居。","暮烟慈竹岭，秋水菊花渠。","炼石为方药，磨岚写道书。","丹砂如就得，拔去即仙庐。"]},{"t":"龙君超邀余过新置山庄庄在翠微中甚幽僻 其四","f":"五言律诗","c":["闭却层崖道，人间了不知。","渔樵分氏族，花果认干支。","滴露新梧子，参云老桧枝。","龙髯曾此去，峦壑也堪疑。"]},{"t":"德山遍入诸岩壑","f":"五言律诗","c":["总被閒驱使，登临也未閒。","霞光红涨壁，水气绿浮山。","遍入云岐路，熟观石面颜。","似曾经眼过，想像不知还。"]},{"t":"夜入桃源县月中","f":"五言律诗","c":["深村杞菊香，壁影拂船凉。","和月和烟市，全山全水乡。","高云排鹤路，怒沬响鱼梁。","若个垂纶客，溪头旧姓黄。"]},{"t":"望渌萝山有怀江渌萝","f":"五言律诗","c":["好在青溪曲，岩花石乳新。","空闻流水引，不见渌萝人。","明月层层岫，乌纱而面尘。","十年求道侣，能不忆仙邻。"]},{"t":"题桃源县","f":"五言律诗","c":["闹处云常至，僮来鸟亦随。","仙人成邑里，烟水作城池。","山有容空地，溪无不怒时。","偶然岚翠起，一县绿离离。"]},{"t":"入桃花源 其一","f":"五言律诗","c":["溪雨濯云根，花林水气温。","睡鸾常守月，仙大欲遮门。","绿壁红霞宅，丹砂石髓村。","人中几甲子，洞里一黄昏。"]},{"t":"入桃花源 其二","f":"五言律诗","c":["白头丫髻子，花里去如仙。","鸟弄云霞栅，人耕芝术田。","庚年看红蕊，生死在苍烟。","认著炉香去，瞿童火尚然。"]},{"t":"入桃花源 其三","f":"五言律诗","c":["花户当云辟，跸门临水关。","何年骑马客，踏断采芝山。","古井沈烟雾，空潭洗面颜。","丘陵一变海，一度到人间。"]},{"t":"入桃花源 其四","f":"五言律诗","c":["洞外一长揖，人仙从此分。","看君如水影，要我似溪云。","花气薰崖户，霞光绕茜裙。","往来江海上，鸾鹤冀相闻。"]},{"t":"九月二十九日同罗服卿及社中诸兄弟登高二圣寺 其一","f":"五言律诗","c":["昔去逢秋至，今来送九归。","菊残将入枕，绵老渐装衣。","定起书黄叶，杯阑语翠微。","禅翁兼醉侣，一种不相违。"]},{"t":"九月二十九日同罗服卿及社中诸兄弟登高二圣寺 其二","f":"五言律诗","c":["竹里将云去，窗间看鸟归。","酒香沾净具，花气著僧衣。","老圃推先达，星坛礼少微。","尘劳君莫问，问著与心违。"]},{"t":"服卿访余柳浪不遇俟我沙头既归服卿再至遂用韵赠之","f":"五言律诗","c":["千里劳君至，三秋俟我归。","柳残多叶字，莲解一池衣。","逸格临杯见，新思入路微。","云山心总在，未与宿根违。"]},{"t":"唐尧胤自贵竹过访用君御韵奉赠","f":"五言律诗","c":["夷马向东驰，青袍敝许时。","袖中三尺雪，梦里一竿丝。","泥酒呼鹦鹉，披诗想荔枝。","武夷若再至，为我道相思。"]},{"t":"唐尧胤以诗见投用韵奉答","f":"五言律诗","c":["滚滚飞尘路，蹄轮相伴居。","浊杯浇瘴月，颠草杂蛮书。","吊古悲无忌，忧时托子虚。","蕉衫凉似水，骑马欲焉如。"]},{"t":"闰九月一日罗服卿唐尧胤王以明刘绳之王连玉及方平无烦两弟夜集斋头得成字","f":"五言律诗","c":["竹外閒风雨，潇潇又满城。","杯行兰炷落，话尽酒垆鸣。","卷石攲窗瘦，寒花倍老成。","喜逢严录事，三五令申明。"]},{"t":"灯下观菊花影同社中诸友赋 其一","f":"五言律诗","c":["清媚知无敌，披丽寔可怜。","易方唯月里，难写是风前。","才子影皆好，倾城背亦妍。","赵昌真粉本，一洗黛螺烟。"]},{"t":"灯下观菊花影同社中诸友赋 其二","f":"五言律诗","c":["一片篱花谱，吴绡墨未成。","何人工点染，添我作渊明。","月浪沉沉路，风香淡淡情。","骚魂多念汝，梦里屈先生。"]},{"t":"灯下观菊花影同社中诸友赋 其三","f":"五言律诗","c":["只与屏添艳，全凭幻写真。","光光能取影，叶叶解分身。","萝月思前世，松风梦故人。","黄筌信好手，没骨有精神。"]},{"t":"灯下观菊花影同社中诸友赋 其四","f":"五言律诗","c":["淡月莪莪碎，微风剪剪疏。","折从栾大手，寄与化人居。","藻叶菱文浪，云官鸟纪书。","烟光与焰水，一种绘空虚。"]},{"t":"灯下观菊花影同社中诸友赋 其五","f":"五言律诗","c":["舞影将流地，颓香乍可闻。","玲珑千朵月，碎琐一窠云。","押以无弦韵，吟成没字文。","长时嗔罔两，或恐近夫君。"]},{"t":"灯下观菊花影同社中诸友赋 其六","f":"五言律诗","c":["山中频领略，得意是萧疏。","半赭佳人后，一帘温语初。","墙颓生画意，蛇斗悟颠书。","离即成三昧，超超寔起余。"]},{"t":"灯下观菊花影同社中诸友赋 其七","f":"五言律诗","c":["静语一堂熏，兕觥屡付君。","窿洼扪水影，游戏写风纹。","倩女归时魄，巫山嫁后云。","鼻根如灭却，亦可嗅清芬。"]},{"t":"灯下观菊花影同社中诸友赋 其八","f":"五言律诗","c":["变体初从墨，名家但姓黄。","空花新女弟，乌有旧儿郎。","函作仙人谜，和成羽客方。","浮生虚妄等，一倍感欢场。"]},{"t":"五弟清梵阁落成闰九月九日同邹伯学王闇然王连玉刘绳之方平弟觞其上得清字","f":"五言律诗","c":["隐几牙签横，蠹鱼渐次成。","花枝合苑影，骚雅一楼声。","租薄盘飧瘦，人閒笑韵清。","篱东香未歇，展限与渊明。"]},{"t":"过五弟天花馆同郝公琰王尚父小酌","f":"五言律诗","c":["草草命洼樽，秋花瘦满盆。","题诗红桕叶，坐语绿槐根。","僧懒迟鸣磬，鸦昏不过村。","开帘见树影，月在槿篱门。"]},{"t":"月下坐小阁","f":"五言律诗","c":["雏女笑咿哑，疏帘委委斜。","酒浇清苦月，诗慰寂寥花。","影落回风雁，先分坐树鸦。","侍儿供茗碗，幽事在山家。"]},{"t":"秋夜痛饮李上舍家和公琰韵","f":"五言律诗","c":["冠珥堕纷纭，清言了不闻。","炉焦鸣暴雨，杯沓卷春云。","醉眼常疑柱，颠书乱扫裙。","主人苛酒政，起立诵弹文。"]},{"t":"郝公琰邀过禅堂访诸高衲 其一","f":"五言律诗","c":["白衱与乌藤，相邀访定僧。","君言未合齿，吾屐已先登。","但省乾无事，何忧百不能。","如临幽涧水，虽小却清澄。"]},{"t":"郝公琰邀过禅堂访诸高衲 其二","f":"五言律诗","c":["幽院日清和，墙苔与径莎。","到来閒挂少，始觉顶毛多。","病亦强人健，愁犹胜客歌。","且休谈出世，入世又如何。"]},{"t":"过法华练若","f":"五言律诗","c":["瘦柏多连架，寒花半入瓶。","山僧轮指语，幽客倚窗听。","苔壁三年墨，蔬园十亩青。","茶烟细细起，竟日锁柴扃。"]},{"t":"夜话清梵阁限韵","f":"五言律诗","c":["萧骚叶满窗，枫落话吴江。","坐久枯兰烬，言深倒酒缸。","寒泉鸣废圃，邻月影高幢。","碧楯方塘曲，昂藏老鹤双。"]},{"t":"看诸友奕 其一","f":"五言律诗","c":["竹影风轩外，楸枰石子声。","暂凭閒调度，清却苦经营。","乌帻连花堕，红云泼面生。","旁观亦自喜，赖是学无成。"]},{"t":"看诸友奕 其二","f":"五言律诗","c":["窗下攲襟坐，无人不看来。","时闻飞似雨，忽有笑如雷。","得意天山捷，沈思槁木灰。","经营定何许，九地九天回。"]},{"t":"风林纤月落 其一","f":"五言律诗","c":["瑟瑟残规吐，泠泠小籁吹。","偶然低远碧，恰好透疏枝。","罥藻勾萝去，笼烟压露垂。","归樵与去艇，处处杜陵诗。"]},{"t":"风林纤月落 其二","f":"楚辞体","c":["轮浅虚笼树，兮斜乍避鸾。","一痕光浅艳，万井气森寒。","耻作妆奁喻，聊为烟水看。","江湖多钓侣，时与校鱼竿。"]},{"t":"风林纤月落 其三","f":"五言律诗","c":["碎影平侵槛，寒梢半妥轮。","装幽来隐舍，布景与词人。","只在风篁曲，长依水石邻。","东郊西浦上，不信有飞尘。"]},{"t":"风林纤月落 其四","f":"五言律诗","c":["帘卷烟条重，窗分翠叠澄。","诗要林处士，图请赵吴兴。","活景通千壑，閒观倚一藤。","匡床谁对语，合有韵高僧。"]},{"t":"夜话春草堂限韵 其一","f":"五言律诗","c":["刻日春杯酽，消时筠管纤。","问风传巷语，备体杂香奁。","山水堆唇角，烟云上指尖。","世缘如骰子，遇著偶然拈。"]},{"t":"夜话春草堂限韵 其二","f":"五言律诗","c":["螺子春生艳，蛾眉老避纤。","祗宜供剪尺，不可更妆奁。","时缬抽丝嫩，新花出样尖。","陇西见弓矢，二见一回拈。"]},{"t":"夜话春草堂限韵 其三","f":"五言律诗","c":["陶令情非冶，广平赋偶纤。","鸾台朝洗砚，春草夜收奁。","倦翮犹思猎，村眉也效尖。","白发伴毛颖，溷上亦时拈。"]},{"t":"喜苏潜夫至柳浪座上限韵 其一","f":"五言律诗","c":["入门檐鸟乱，红叶照青衫。","童子初弛笈，花骢乍解衔。","瓮头倾滟潋，卷里出巉岩。","屡眄跫音至，秋来信几缄。"]},{"t":"喜苏潜夫至柳浪座上限韵 其二","f":"五言律诗","c":["侧帽花垂髻，翻杯酒污衫。","骚坛为佐领，曲部是兼衔。","话久风掀席，思奇笋出岩。","半宵酬和语，题满一封缄。"]},{"t":"喜苏潜夫至柳浪座上限韵 其三","f":"五言律诗","c":["小仄呼藤杖，微喧去皂衫。","花头当槛落，鸟影入杯衔。","对口浮三爵，他时老一岩。","暂来犹有禁，佛语口须缄。"]},{"t":"集方平弟绿荫堂古槐下即事限韵","f":"五言律诗","c":["率尔生幽意，非关对水山。","苔枝垂酒盏，虫叶堕烟鬟。","只此双眉黛，舒开一座颜。","婆娑醉老叟，项领曲如弯。"]},{"t":"小修久住沙市苏潜夫迟之十馀日矣雨中集刘绳之高斋小脩忽至赋得十灰","f":"五言律诗","c":["百里三回约，无朝不眄来。","未曾离口齿，忽已到池台。","酒病花销去，诗心竹引开。","筼筜旧老圃，芟草去尘灰。"]},{"t":"赋得裙拖六幅潇湘水","f":"五言律诗","c":["细简匀匀叠，长墙靡靡澜。","风回千皱乱，花绕一拖寒。","洛水罗呈出，谢家练比看。","两般俱死水，争解舞惊鸾。"]},{"t":"赋得欢场害马","f":"五言律诗","c":["恶态频来见，清谈事每差。","杯徼合券客，庭老晒裈花。","遇月长扃户，登山屡忆家。","每当欢饮夕，三五散如鸦。"]},{"t":"乍寒集王连玉宅小饮","f":"五言律诗","c":["浅屋低檐下，春花滴小槽。","箸阑思蟹足，话久觅绒袍。","竹语调刀切，云啼獝狖高。","等閒历寒暑，颠里换斑毛。"]},{"t":"丈石居小集送苏潜夫","f":"五言律诗","c":["底事心难尽，穷宵说未终。","半槽平口水，一叶打霜风。","寒月冲煤焰，枯株照粉红。","别来元白语，多分在诗筒。"]},{"t":"代","f":"五言律诗","c":["随例东门柳，那堪折赠行。","早知云易散，何忍梦难成。","小玉终无匹，汪伦只有情。","别来林处士，卖鹤买新声。"]},{"t":"送郝公琰南下","f":"五言律诗","c":["雪子落纷纷，鸣涛远送君。","梦回牛渚月，书达敬亭云。","俗薄休怀刺，交浮莫定文。","王充如有论，应使蔡邕闻。"]},{"t":"外甥毛云花烛诗","f":"五言律诗","c":["玉立映澄壶，儿郎洵美都。","香含新豆蔻，花引嫩鹓雏。","案小频过额，烟轻欲散垆。","韦门素业好，付与外甥卢。"]},{"t":"夜起同廖道人扣王生门索酒酒行而电电大作众皆辟易余兴益豪至子夜乃休 其一","f":"五言律诗","c":["夜暖不成寐，披衣聊起行。","一街丝雨暗，半隙幌灯明。","壁上烟黄字，瓮头点滴声。","乾莲与烘笋，倍觉有心情。"]},{"t":"夜起同廖道人扣王生门索酒酒行而电电大作众皆辟易余兴益豪至子夜乃休 其二","f":"五言律诗","c":["天意苍茫恶，奔雷驾雨风。","书翻入瓮内，儿走匿床中。","拍案山公叫，沾唇儿盏空。","归途那用烛，电火照人红。"]},{"t":"曾长石诗来约以寒食见过用韵合之","f":"五言律诗","c":["湖上腰如许，那能不系人。","到门青李帖，屈指永和辰。","笋蕨抽蔘嫩，旗枪战火新。","云山无处少，只少自由身。"]},{"t":"苦雨","f":"五言律诗","c":["且莫问提壶，春风一半孤。","暮云啼滑滑，晓树语呱呱。","梦绕飞花社，思牵线柳湖。","无方可醉得，浊酒坐灰垆。"]},{"t":"曾退如太史返棹江干雨甚宿杨上舍家令门僧持卷来观夜坐有怀敬题其末 其一","f":"五言律诗","c":["兰蕊坐销红，长吟短噫中。","游天车轴雨，撼地户邮风。","梦去云连峡，诗来翠扫空。","习家地上酒，何事外山公。"]},{"t":"曾退如太史返棹江干雨甚宿杨上舍家令门僧持卷来观夜坐有怀敬题其末 其二","f":"五言律诗","c":["山鬼莫吹灯，羁心感少陵。","话中江渺渺，卷里岫层层。","岚重千畦衲，云开九节藤。","联床今夜雨，空对岭南能。"]},{"t":"泛舟便河 其一","f":"五言律诗","c":["一棹碧苍茫，蕉衫碎影凉。","风音和鸟语，水色与天光。","岸老蒲根出，沙平荻笋香。","蹄轮何滚滚，对面即沧浪。"]},{"t":"泛舟便河 其二","f":"五言律诗","c":["禅板佐尊罍，青溪曲曲回。","鱼閒知浪静，鸟喜觉风来。","漠漠新云树，荒荒旧沼台。","一番见高冢，一度使眉开。"]},{"t":"送苏潜夫北上","f":"五言律诗","c":["去去日华东，晴霞似火红。","好辞杯底月，莫畏马头风。","谢客休耽屐，张融且竖铜。","绯袍白手板，勉矣偶场中。"]},{"t":"游章台寺和小修韵 其一","f":"五言律诗","c":["飞尘冷冷消，人语隔烟遥。","雨洗青畦道，风薰白芷苗。","竹深存废碣，僧老话前朝。","霸业荒残尽，虚名只细腰。"]},{"t":"游章台寺和小修韵 其二","f":"五言律诗","c":["碧水蠲忙去，红葩引笑开。","兔葵伤故国，狐粉啸空台。","古屋晴生菌，深房昼锁苔。","松音与梵响，一洗大夫哀。"]},{"t":"游章台寺和小修韵 其三","f":"五言律诗","c":["云捲三分地，尘飞六国王。","自然归灭劫，不必问巫阳。","古叠荒遗搆，澄波照冷篁。","廿年双屈指，头白话儿郎。"]},{"t":"游章台寺和小修韵 其四","f":"五言律诗","c":["碧渚新琅玕，入门碎影寒。","么弦将水听，青黛作烟看。","且乐时花艳，休悲故垄残。","南威他自美，兴废岂相干。"]},{"t":"夏日同龙君超傅中执萧季星龚散木彭长卿崔晦之小修王小白泛舟便河得桥字","f":"五言律诗","c":["好作烟林谱，微霞带水条。","平平铺碎浪，远远出红桥。","天坼云鳞见，江澄暑路消。","山光与粉黛，一种是逍遥。"]},{"t":"又和龙君超韵","f":"五言律诗","c":["白板赤栏桥，石根系小舠。","风传初稻信，雨应熟梅潮。","柳密兼烟重，槎枯带藓漂。","洄沿无定止，只似野云邀。"]},{"t":"刘元质宅宴得金字","f":"五言律诗","c":["远水轻云意，孤桐野鹤心。","消磨归酒政，游戏入花林。","赵姊双名燕，卢郎一字琛。","庞公见亦悔，湘水错沉金。"]},{"t":"龙君超徼集章台以看花台为韵 其一","f":"五言律诗","c":["碧筱当烟出，朱华带渚看。","佳人吴笑语，公子晋衣冠。","始觉欢场盛，争言雅道难。","经时觅快友，才得许如兰。"]},{"t":"龙君超徼集章台以看花台为韵 其二","f":"五言律诗","c":["一笑烂云霞，青娥驱法华。","章台新马足，洞口旧鱼槎。","秋水人人月，春风面面花。","不同愁未玉，萧瑟对东家。"]},{"t":"龙君超徼集章台以看花台为韵 其三","f":"五言律诗","c":["天际飒轻雷，浓阴泼地来。","丛中避粉黛，树底卧樽罍。","数点将穿屋，移时忽泛台。","只疑旧歌舞，化作雨云回。"]},{"t":"病起新霁见月","f":"五言律诗","c":["病起初逢月，云开哎亦开。","云随残闷去，月逐好怀来。","地叶凝清露，新香泻绿醅。","冶心虽校浅，仍是欲然灰。"]},{"t":"林兰阁同王以明先生及尚父谢道人小集偶成","f":"五言律诗","c":["凉月下空疏，萧萧静者居。","休心花事断，忌药酒船虚。","竹外披烟鹤，尊前带子鱼。","盘飧聊复尔，商略古人书。"]},{"t":"醉归示凡公响泉道人","f":"五言律诗","c":["不寐即狂歌，莲花漏水多。","醉来寻白足，定起唤青娥。","梵唱嗔吴肉，荷衣剪越罗。","亦知风景煞，争奈老颠何。"]},{"t":"当阳僧来邀游青溪紫盖诸胜 其一","f":"五言律诗","c":["十载青山约，今番始赴期。","如云投旧岭，似鸟念高枝。","蓝压仙翁井，苔深鬼谷祠。","车将一喝去，秤取布裈师。"]},{"t":"当阳僧来邀游青溪紫盖诸胜 其二","f":"五言律诗","c":["一涧珠翻处，千山玉照时。","东冲西逻酒，横版侧厓诗。","僧老扶雏至，鹤骄带子随。","掌茶与谷水，宿世也相知。"]},{"t":"登遨游冢有感示凡公响泉道人","f":"五言律诗","c":["古冢新新道，荒原漠漠枫。","荷衣蕙带鬼，燕麦兔葵风。","颓叠高陵变，分趋逝水东。","莫言空不得，何事不成空。"]},{"t":"将入青溪值雨雪凡公有诗见促用韵荅之","f":"五言律诗","c":["童子语諵諵，雪花打皂衫。","云低天惨淡，霜老石巉岩。","怪鸟鸣枯叶，空江立瘦杉。","青溪骑鹤叟，聊且附书缄。"]},{"t":"送雪照还吴","f":"古风","c":["洗钵焚钞去，瞻云倚棹歌。","离乡吴语变，入咏楚骚多。","五老峰头瀑，三江雪后波。","?衣棕笠子，袖手看嵯峨。"]},{"t":"又代作","f":"五言律诗","c":["四载椒林社，精研只有君。","高谈排嘿照，独往贱多闻。","江面瓶心月，山南岭北云。","逆风香自远，无路袭芳芬。"]},{"t":"暮鸟投林和张明教 其一","f":"五言律诗","c":["雾卷复烟披，嘈嘈话许时。","大都寻故侣，莫是拣高枝。","半岭云千态，疏林月一规。","夜寒风袅袅，归梦在天池。"]},{"t":"暮鸟投林和张明教 其二","f":"五言律诗","c":["霞碧与山红，烟林绘谱中。","乍啼缘见月，半妥为梢风。","万点铺沙异，千畦带椟同。","莫愁三匝苦，犹胜在金笼。"]},{"t":"暮鸟投林和张明教 其三","f":"五言律诗","c":["渺渺辞沙屿，嘹嘹带远空。","分行来树里，送影入池中。","小艇烟江月，高楼晚箔风。","佳人天末许，同此眄归鸿。"]},{"t":"乙巳除夕","f":"五言律诗","c":["十亩负江田，归耕已七年。","稚松云堰地，雏女发垂肩。","贝叶翻将绽，荷衣著屡穿。","贫乡何可恋，大抵为林泉。"]},{"t":"春日同谢于楚周观国小脩李澄之王尚夫崔晦之刘绳之过智者堂访度门法师","f":"五言律诗","c":["数里碧阴森，高禅静亦吟。","趁花来远涧，听鸟入平林。","历尽摧车坂，稍存绕指金。","浮尘都歇尽，未歇唾壶心。"]},{"t":"诸衲见过","f":"五言律诗","c":["閒即过东皋，衲衣对酒糟。","袖中怀米帖，花底读离骚。","箔卷垆烟细，窗寒石累高。","负家无可供，沚水与溪毛。"]},{"t":"哭江进之 其一","f":"五言律诗","c":["石火乍飘红，匆匆四闰中。","才名巴子国，吏迹馆娃宫。","洗海登天月，催芳烂蕊风。","不留长把玩，收拾与虚空。"]},{"t":"哭江进之 其二","f":"五言律诗","c":["案有君遗迹，时时动我悲。","梦中呼白也，卷里哭微之。","骨似凝冰石，心如静水池。","太玄那得比，嘱累有佳儿。"]},{"t":"哭江进之 其三","f":"五言律诗","c":["一笑凌云去，高寒自少尘。","骚魂皆楚鬼，吊客尽秦人。","作诔倾南国，移书诅北辰。","斯文凋丧尽，何用死麒麟。"]},{"t":"哭江进之 其四","f":"五言律诗","c":["偏是佳人少，鸺鹠日日鸣。","应刘皆早世，晁贾竟虚生。","雪涧寒当户，渔梁怒满城。","怜才与惜宝，天似未分明。"]},{"t":"哭江进之 其五","f":"五言律诗","c":["蜀魄悲鸣后，巫猿叫啸初。","峨嵋徒有黛，巴水不成书。","女鬼行云侍，仙邻卖卜居。","浣花溪上叟，情切旧乡庐。"]},{"t":"哭江进之 其六","f":"五言律诗","c":["好手经炉冶，匡时正老成。","文通才未尽，元静职犹轻。","妖作长沙鵩，帐空澧水萤。","花源留迹处，莎草背阶生。"]},{"t":"哭江进之 其七","f":"五言律诗","c":["节节来余梦，溪云湖柳边。","浪仙神尚瘦，米芾鬼犹颠。","花国恣题品，珠宫任纂编。","閒时出谐史，一笑谑诸天。"]},{"t":"哭江进之 其八","f":"五言律诗","c":["湘水濯魂清，纷纷兰芷生。","桃花仙路艳，薜荔鬼衣轻。","喜去朝虞帝，悲来过屈平。","沙萝村口上，夜引瞿童行。"]},{"t":"哭江进之 其九","f":"五言律诗","c":["作者心良苦，悠悠世岂知。","近俳缘矫激，取态任斜攲。","江阔无澄浪，林深有赘枝。","向人言似梦，无计解愚痴。"]},{"t":"哭江进之 其十","f":"五言律诗","c":["薄俗好检点，因循愧少箴。","只疑如豆目，未达似空心。","琴败孤音绝，林荒破宅深。","期君一百载，只字双南金。"]},{"t":"送周观国还会稽兼寄陶周望兄弟 其一","f":"五言律诗","c":["江流澎湃处，一曲是官衙。","小邑城三里，荒垣市几家。","斗湖曾载月，浪柳也吹花。","局蹐真如茧，能禁念若耶。"]},{"t":"送周观国还会稽兼寄陶周望兄弟 其二","f":"五言律诗","c":["且莫听啼魂，烟岚路亦昏。","山连内史宅，水到贺公门。","晓月兰桡市，春风黛绿村。","个年题壁处，霜洗旧苔痕。"]},{"t":"曾雷二太史过柳浪用杜韵 其一","f":"五言律诗","c":["云岚深几曲，五月气犹寒。","月下兼花下，林端史水端。","愁来诗监押，老至道遮阑。","识得岁身计，尘劳也自安。"]},{"t":"曾雷二太史过柳浪用杜韵 其二","f":"五言律诗","c":["劝我早经营，三山海上城。","亦如怜素女，其那忤方平。","青鸟曾经约，丹台也注名。","竹枝江上雨，难道是无情。"]},{"t":"黄平倩久无书有僧自蜀来传其厌世余不信数日后陶周望书来云闻平倩有疾且求消息于余余谓小修曰必无他诗以志之","f":"五言律诗","c":["积雪峨嵋路，三年渺去鸿。","岷江惟有浪，巫峡祗闻风。","惊绝西僧语，愁深太史筒。","子瞻定不死，吾已料天公。"]},{"t":"西来僧云平倩初病痹今已痊复志喜","f":"五言律诗","c":["西望嘉陵信，迢迢半影鸿。","黄州元不死，白傅已无风。","小近临邛黛，新开郫酒筒。","僧言真实否，吾欲让庞公。"]},{"t":"夏日同龚散木能者崔晦之邹伯学李子髯携妓泛舟和尚桥 其一","f":"五言律诗","c":["白舫形如鹄，青娥姓是卢。","衣香泥翡翠，扇影怯鹈鹕。","石竹和人籁，山花爇野炉。","遥看十里水，一片芙蓉湖。"]},{"t":"夏日同龚散木能者崔晦之邹伯学李子髯携妓泛舟和尚桥 其二","f":"五言律诗","c":["试说鸳鸾侣，何如鸥鹭群。","溪光描翠黛，竹影写罗裙。","云日鱼鳞气，霞波雉尾文。","鹤飞冲树起，天半一声闻。"]},{"t":"病起独坐","f":"五言律诗","c":["荒草绿如烟，何秋不可怜。","病家无客至，小犬亦高眠。","开帙寻诗料，添衣缺酒钱。","闭门读庄子，秋水马蹄篇。"]},{"t":"病起偶题 其一","f":"五言律诗","c":["对客心如怯，窥铜只自怜。","负暄疏败发，发箧理残篇。","名岂儒冠误，病因浊酒痊。","浮生喻泡影，何以乐青年。"]},{"t":"病起偶题 其二","f":"五言律诗","c":["独坐真成闷，孤砧急暮声。","乾坤偏恶道，世路几狂生。","骚雅原无命，湖山剩有情。","一丘何不可，身外即浮萍。"]},{"t":"病起偶题 其三","f":"五言律诗","c":["强欲亲暾日，无那怯晓风。","缠绵悲二竖，坐起仗双童。","世路他如梦，浮名我失弓。","一番三径里，秋菊又成空。"]},{"t":"病起偶题 其四","f":"五言律诗","c":["不断青云梦，难堪白发情。","跳梁山鬼妒，落莫酒人轻。","色界身终苦，无生学未成。","浮沤能几许，枉自觅枯荣。"]},{"t":"花朝即事","f":"五言律诗","c":["雨过庭花好，开尊亦自幽。","不知今夕醉，消得几年愁。","一朵新红甲，四筵半白头。","久知行乐是，老矣复何求。"]},{"t":"江涨","f":"五言律诗","c":["滟滪三冬雪，潇湘五月波。","疾流翻地转，远势触云过。","县尉临江祭，巴人下水歌。","世平无孟珙，父老恨如何。"]},{"t":"即事","f":"五言律诗","c":["俗态有如此，谁云道不贫。","黄金贵贱士，乌帽是非人。","公叔绝交甚，东方慢世真。","浮云看物理，浪迹混风尘。"]},{"t":"秋扇","f":"五言律诗","c":["濯濯齐纨素，团团明月辉。","舍羞王氏女，失宠汉宫妃。","出入心犹在，炎凉态已非。","自甘藏箧笥，不敢触寒威。"]},{"t":"夏日泛舟","f":"五言律诗","c":["泛泛鵁鶄近，深深雀鹳闻。","空潭不受暑，野竹半捎云。","公子收行盖，佳人晒舞裙。","垂杨乱荇藻，日色冷纷纷。"]},{"t":"得李宏甫先生书","f":"五言律诗","c":["似此瑶华色，何珠空谷音。","悲哉击筑泪，已矣唾壶心。","迹岂焚书白，病因老苦侵。","有文焉用隐，无水若为沉。"]},{"t":"冬菊","f":"五言律诗","c":["众芳无不改，篱菊晚犹开。","护叶多编竹，怜香自剪莱。","惊心寒节破，载酒故人来。","忽忆东篱叟，狂歌试举杯。"]},{"t":"江行","f":"五言律诗","c":["霞彩收晴色，澄波媚夕晖。","饥鹰奔树冷，沙樢触人飞。","墩叟迎儿出，乡童负犬归。","少年饶酒力，何事怯寒威。"]},{"t":"登台","f":"五言律诗","c":["登台当此日，潦倒尽馀驩。","古木何年有，林花尽日寒。","霞来鳞作市，山晚气成澜。","去去沧江暝，狂歌兴未阑。"]},{"t":"除夕前八日","f":"五言律诗","c":["每恨年光驶，东风又一时。","入门花自媚，出谷鸟先知。","宦去嵇康懒，情来育长痴。","无为愁暮景，幽意在南枝。"]},{"t":"夜坐别彭子","f":"五言律诗","c":["寂历严更漏，凄其旅客情。","倾肠谈近事，屈指数游程。","寒气冲筵入，乡心冒酒生。","经年事奔走，名利一无成。"]},{"t":"社中","f":"五言律诗","c":["宿昔城南约，苍茫十载情。","交游悲喜尽，文字揣摩成。","古屋繁阴入，空阶冻鸟行。","终年雅搦管，辛苦是书生。"]},{"t":"小斋","f":"五言律诗","c":["情至观无始，愁来宝奈何。","蠹行粘败粉，燕起触檐罗。","往事惟长啸，新知一放歌。","鹓雏虽饿死，不与雀争多。"]},{"t":"迎九","f":"五言律诗","c":["节物何堪问，流光转自哀。","世情搔首过，秋色闭门来。","才子新开社，参军旧有台。","菊花才作药，迟尔共衔杯。"]},{"t":"忆蟹","f":"五言律诗","c":["鄂州为客处，紫蟹最堪怜。","朱邸争先买，青楼不计钱。","昔年桐乳下，今日菊花前。","咫尺晴川水，无由见尔鲜。"]},{"t":"夏日同龙君超君善家伯修郊外小集","f":"五言律诗","c":["避却红尘子，晴郊共举杯。","踏云穿宝阁，立马问金台。","古木无心长，杂花不定开。","东南饶胜友，喜与二郎来。"]},{"t":"宿村中","f":"五言律诗","c":["古木攒幽壑，丛篁蔽小祠。","篮舆村犬吠，罗服野人疑。","稻熟家家酿，山香处处诗。","田翁强解事，款款具威仪。"]},{"t":"示社友","f":"五言律诗","c":["所至成三笑，居然似七贤。","社开正始后，诗数中兴年。","一代称同轨，千秋欣执鞭。","古来藏二酉，不必大都传。"]},{"t":"秋日同邹伯学过崔晦之村庄","f":"五言律诗","c":["携得城中友，联镳把臂来。","探阄人踊跃，问姓俗疑猜。","邻酒无因至，霜花有限开。","一丘荒楚里，门户蔽蒿莱。"]},{"t":"送周尚宝左迁海澄典史 其一","f":"五言律诗","c":["羯虏终无赖，馀波横及人。","清时骄魍魉，平地蹶麒麟。","去国宁辞谤，投荒幸有身。","边筹终及尔，勿复叹沉沦。"]},{"t":"送周尚宝左迁海澄典史 其二","f":"五言律诗","c":["几度青门抑，荣枯送尔行。","庙谋何日定，边事仗谁成。","名以批鳞重，恩因市虎轻。","知君心独苦，万死亦关情。"]},{"t":"送周尚宝左迁海澄典史 其三","f":"五言律诗","c":["十年声籍甚，一日去长安。","作赋元投楚，为文欲吊韩。","云开龙首出，雨过鳄溪寒。","到处青山好，何忧行路难。"]},{"t":"九日江上小集","f":"五言律诗","c":["物色千林换，江声四面澜。","脱冠酬胜节，呼酒贺新寒。","童子携方罫，庖人进鲙盘。","秋郊如醉里，潇洒一凭栏。"]},{"t":"偶成","f":"五言律诗","c":["尘世无暇日，孤馆有馀情。","黄金铸知己，青编列友生。","事佛心难定，学仙道不成。","去去双田下，兄弟事耦耕。"]},{"t":"郊行同龚散木能者邹伯学","f":"五言律诗","c":["高柳藏山寺，杂花缀水滨。","青溪六七里，白帢两三人。","钟釜蚊䖟过，烟霞鹿豕邻。","箕踞亦是礼，何必取冠巾。"]},{"t":"嘉鱼李太清书斋","f":"五言律诗","c":["尚有青云旧，谁云白首新。","孤尊相对日，万死可怜身。","曝衲惊黄鸟，开轩跳紫鳞。","名臣何必贵，衰腐据要津。"]},{"t":"夏日邹伯学园亭","f":"五言律诗","c":["几坐无俦侣，观空绝想尘。","床头高士传，花下上皇人。","养鹤移茶灶，怜鱼辍钓纶。","蒙庄去已久，斯意竟谁陈。"]},{"t":"夏日即事 其一","f":"五言律诗","c":["一官因懒废，万事得禅逃。","岁月谈空老，风尘拂袖高。","贫交殊面背，薄俗厚皮毛。","不解和光指，空斋坐郁陶。"]},{"t":"夏日即事 其二","f":"五言律诗","c":["闷即摊书读，长年一腐儒。","开门残雨过，攲枕片云孤。","世事输棋局，人情转辘轳。","浮生宁曳尾，断不悔江湖。"]},{"t":"夏日同龚能者崔晦之邹伯学纳凉李子髯斋中高柳下","f":"五言律诗","c":["高柳著溪烟，团团翠可怜。","空街摇白水，疏日冷青钱。","原宪贫非病，维摩疾是禅。","居然城廓里，一种小林泉。"]},{"t":"偶题","f":"五言律诗","c":["得句题蕉叶，裁冠费笋皮。","宦情三不可，禆理百无知。","野馆繁栀子，晴窗语燕儿。","谢安何小草，相业仅能棋。"]},{"t":"寄沈介庵","f":"五言律诗","c":["不谓晴川阁，同时失此人。","龙门吾有意，鱼服尔何神。","封事惊来草，除书怪积薪。","和光古有语，好得耐风尘。"]},{"t":"初秋","f":"五言律诗","c":["负俗将无傲，閒居合有秋。","骄阳犹避鹊，小雨亦呼鸠。","中散交多绝，司空宦总休。","明知悲冉冉，何苦不沧洲。"]},{"t":"漫兴 其一","f":"五言律诗","c":["少年多浪迹，老大合幽栖。","事业卑牛口，生涯尚马蹄。","避人嘲自解，隐几物难齐。","每忆山中友，秋来好杖藜。"]},{"t":"漫兴 其二","f":"五言律诗","c":["独往吾何有，狂痴世所怜。","一身书蠹后，万事酒杯前。","礼乐从先进，交游附少年。","昨来益自喜，信口野狐禅。"]},{"t":"江崩及城","f":"五言律诗","c":["城郭荒如许，迁来得几时。","江通夔子国，潮打武侯祠。","六代馀封在，三分故里疑。","焉知深谷底，不有万山碑。"]},{"t":"寄散材","f":"五言律诗","c":["只觉秋悲苦，那堪别赋工。","予瞻南去雁，尔望北来风。","寒日疏篱菊，清霜落井桐。","江湖夕照里，登眺许谁同。"]},{"t":"寄杨敦初 其一","f":"五言律诗","c":["野树吟秋日，江云送目初。","百年谁命驾，两地且传书。","潘岳功名薄，庄生吏体疏。","禅心知不减，挥麈近何如。"]},{"t":"寄杨敦初 其二","f":"五言律诗","c":["万事传经懒，官閒且自由。","闭门无不可，得秫更何求。","玄草扬云宅，清时王粲楼。","莫言工作赋，此地易悲秋。"]},{"t":"忆弟 其一","f":"五言律诗","c":["万里南征路，扁舟去不来。","赋投鹦鹉水，诗上凤凰台。","天地穷相傍，云霄蹇自哀。","千秋无汉武，司马一庸才。"]},{"t":"忆弟 其二","f":"五言律诗","c":["骤传伏枕去，转觉泪沾巾。","短发三江棹，孤蓬四海人。","文章妻子怪，姓字友朋嗔。","兄弟皆衣紫，君胡命苦辛。"]},{"t":"忆弟 其三","f":"五言律诗","c":["去住非无谓，蹉跎似不羁。","亲朋尽欲杀，知己半相疑。","独我能青眼，因君是白眉。","东来书一纸，读罢泪如丝。"]},{"t":"登高有怀","f":"五言律诗","c":["秋菊开谁对，寒郊望更新。","乾坤东逝水，车马比来尘。","屈指悲时事，停杯忆远人。","汀花与岸草，何处不伤神。"]},{"t":"过古寺","f":"五言律诗","c":["红桥过雨润，黄叶会霜稀。","古殿催金榜，空塘落水衣。","畏人寒鸟窜，护法老龙饥。","醉语兼禅语，都非第二机。"]},{"t":"宿僧房","f":"五言律诗","c":["夜雨沉清磬，霜林起暮鸦。","莲台三品叶，佛果一时花。","觉路昏罗縠，禅灯黑绛纱。","早知婴世网，悔不事袈裟。"]},{"t":"忆弟 其一","f":"五言律诗","c":["尚有他乡客，那堪两地春。","文章聊玩世，儒墨竟疑人。","别后山川换，愁来岁月新。","沧江一万里，浊酒向谁陈。"]},{"t":"忆弟 其二","f":"五言律诗","c":["东去交多少，南询兴有无。","高天鸿鹄举，世路马牛呼。","骚雅命难达，江湖迹易孤。","步兵虽嗜酒，倘亦恨穷途。"]},{"t":"异僧","f":"五言律诗","c":["买印支公僻，输瓶座首能。","咒言听似鸟，梵字写如藤。","托钵施仙饭，支床面佛灯。","一身犹不用，何处有三乘。"]},{"t":"出郭","f":"五言律诗","c":["稻熟村村酒，鱼肥处处家。","轻刀粘水去，独鸟会风斜。","落日流红浪，长江徙白沙。","山僧迎客喜，颠倒著袈裟。"]},{"t":"江上","f":"五言律诗","c":["白雾迷荒楚，青流带远空。","沙平晴献雪，树老夜屯风。","旷野眠饥兕，孤洲落晚鸿。","布帆如屋里，何处有城中。"]},{"t":"郊外小集 其一","f":"五言律诗","c":["赖有沧洲意，聊行浊酒杯。","白波吹日上，粉堞映江开。","米谷舟中市，人烟水面来。","息机吾已久，鸥鸟莫相猜。"]},{"t":"郊外小集 其二","f":"五言律诗","c":["浪迹真无赖，狂心今若何。","一尊聊对酒，万事且狂歌。","稚子矜黄叶，渔人语白波。","芦花青袅袅，秋意满溪蓑。"]},{"t":"三弟回志喜 其一","f":"五言律诗","c":["送汝才三月，那知西复东。","客中何地返，橐里几时空。","世事穷来见，文章病后工。","浮湘而涉海，司马之遗风。"]},{"t":"三弟回志喜 其二","f":"五言律诗","c":["突兀英雄气，飘零病苦身。","黄金憎赋客，青眼谢时人。","按剑投珠恨，呼牛应马真。","无钱觅知己，到底白头新。"]},{"t":"三弟回志喜 其三","f":"五言律诗","c":["万里将孤舫，长江与太湖。","山川几尽越，文字耻为吴。","见我故人否，识君高义无。","士安交不薄，珍重序三都。"]},{"t":"三弟回志喜 其四","f":"五言律诗","c":["东去人人叩，西来事事疑。","苦心真学者，出世好男儿。","消息蕲州得，机缘老宿知。","何人皮相士，道尔定狂痴。"]},{"t":"花朝日呈伯修 其一","f":"五言律诗","c":["垆气薰高阁，歌声绕细厨。","桂尊清且满，坐客美而都。","共唱三妇艳，同开百子图。","主人将夜饮，傍晚禁啼乌。"]},{"t":"花朝日呈伯修 其二","f":"五言律诗","c":["宛转花如结，差池燕似知。","佳人炊寿饼，童子按新辞。","珠履散还聚，兰膏尽复吹。","青轩红丽蕊，第一好天时。"]},{"t":"京师夜坐","f":"五言律诗","c":["兀坐酲酲闷，读书字字难。","竹枯知凤馁，瓶涩验天寒。","事往心方省，穷来交渐宽。","微官犹窘我，赢马日长安。"]},{"t":"北行道中示弟","f":"五言律诗","c":["惜别无多日，驱驰看逼年。","客愁繁似雨，官路远如天。","冻碛酸车毂，严霜齧马鞭。","流光付行旅，尔我递相怜。"]},{"t":"挽苏母","f":"五言律诗","c":["喜得全归日，郎君巳致身。","凭将万死事，泣报九原人。","野气迷丹旐，秋风冷石麟。","但留天语在，一纸夜台新。"]},{"t":"秋夜感怀","f":"五言律诗","c":["莫以千人和，遂轻白雪歌。","支离常调失，突兀此生过。","薄俗论交尽，秋风阅世多。","鹓雏终万仞，嚇我待如何。"]},{"t":"余山居六年矣丙午秋复北上临发偶赋","f":"五言律诗","c":["又被閒驱出，冥鸿那可飞。","添多新蒜发，典尽旧荷衣。","柳密云侵郭，荷长水浸矶。","鸥凫争作语，客子几年归。"]},{"t":"过荆门观蒙惠泉","f":"五言律诗","c":["云过山城没，溪回磴道平。","一沤淙石底，万户枕泉声。","童子将茶去，僧雏负钵行。","居人传好语，得似长官清。"]},{"t":"石桥道中","f":"五言律诗","c":["上上仄岩颠，清溪落马前。","陂陀聊作馆，硗确以为田。","人出斜山照，鸡鸣废寺烟。","亭翁颜半赭，知得有丰年。"]},{"t":"襄阳道中逢龙君御君御节镇西宁便道省太夫人","f":"五言律诗","c":["征马隔林鸣，双旌忽背行。","白头橑远梦，红树促归程。","银管书生去，铁衣老将迎。","羌胡知姓字，檄草在边城。"]},{"t":"壬辰秋日余与伯修兄俱得请先后出都门至郑相及同宿州署今相去十五年伯脩厌世亦六年矣电火惊心山川触目因书数语兼示小脩方平两弟","f":"五言律诗","c":["十五度春秋，沤花转眼休。","含悲上东里，无路避西州。","孤月伤鸿阵，寒云障马头。","对床今夜雨，清泪几行流。"]},{"t":"邺城道 其一","f":"五言律诗","c":["何处魏离宫，荒烟断苇中。","猎蹄晴捲雪，高隼怒盘风。","苑古梧桐秃，墙崩枸杞红。","空台与流水，想像旧帘栊。"]},{"t":"邺城道 其二","f":"五言律诗","c":["白日悲难驻，英雄谁不然。","鱼膏焚地底，蛾黛哭生前。","南国香成雾，西山石化烟。","人间绝快事，天子作神仙。"]},{"t":"邺城道 其三","f":"五言律诗","c":["碧草涨寒塘，菖蒲花下香。","山禽犹翠羽，野果尚丹房。","残粉迎新帝，妖魂逐小郎。","曹家兄弟好，无那太淫荒。"]},{"t":"邺城道 其四","f":"五言律诗","c":["且著双眉目，休随俗笑嚬。","帘前挝鼓吏，床上捉刀人。","胡粉装尤怪，蔗竿舞入神。","精光如可画，宁与魄俱尘。"]},{"t":"邺城道 其五","f":"五言律诗","c":["那得长无语，无情泪亦垂。","碑馀汉岁月，水洗邺城池。","楼外羌雏啸，宫中寡妇悲。","好还不再世，凶狡亦何为。"]},{"t":"邺城道 其六","f":"五言律诗","c":["近得铜台瓦，重来五十锾。","无方鬒白发，空自治青山。","上马蒐才藻，横戈按髻鬟。","霸图今已矣，文采照人间。"]},{"t":"邺城道 其七","f":"五言律诗","c":["仆去前王碣，耕来故国坟。","蜂巢无两大，兔窟有三分。","夜火生空树，阴龙战野云。","美人何处所，试与定遗文。"]},{"t":"邺城道 其八","f":"五言律诗","c":["且勿度前村，白杨路渐昏。","一丘文字鬼，千古战争魂。","历数孙曹闰，风流魏晋繁。","成蹊人自省，桃李不须言。"]},{"t":"邺城道 其九","f":"五言律诗","c":["谋士虎兼龙，三家霸局同。","文章分鼎足，才品第英雄。","龌龊司徒后，昏顽锻锡公。","陈琳檄自有，离可愈头风。"]},{"t":"邺城道 其十","f":"五言律诗","c":["校尽中原士，初逢国手棋。","孙郎争一道，刘冑仅双持。","石悍刀方利，风高海始奇。","唐宗与宋祖，应悔不同时。"]},{"t":"游崇国寺得明字 其一","f":"五言律诗","c":["入寺稀人识，僧雏尽老成。","花犹香废苑，石莫话前生。","壁上苔栖墨，廊间雨坏楹。","春衣能几日，又复过清明。"]},{"t":"游崇国寺得明字 其二","f":"五言律诗","c":["只作幽探计，如来与證明。","出门皆黛色，入寺有泉声。","酒似溪光嫩，身如云影轻。","閒官无别侣，头白旧方情。"]},{"t":"惠安伯圜亭同顾升伯李长卿汤嘉宾看牡丹 其一","f":"五言律诗","c":["古树暗房栊，登楼只辨红。","分畦将匝地，合燄欲焚空。","蝶醉轻绡日，莺捎煖絮风。","主人营一世，身老众香中。"]},{"t":"惠安伯圜亭同顾升伯李长卿汤嘉宾看牡丹 其二","f":"五言律诗","c":["通国皆狂死，谁家解满栏。","径须一石醉，消得几生看。","小榭迎初月，层岚作晚寒。","携归才数朵，掩尽百罗纨。"]},{"t":"浴佛日刘元定邀诸公偕游高梁桥得为字 其一","f":"五言律诗","c":["节是祗园会，欢同曲水池。","妖童歌串乱，天女鬟华随。","是树皆停盖，无波不泛卮。","鱼龙与角抵，乐事看君为。"]},{"t":"浴佛日刘元定邀诸公偕游高梁桥得为字 其二","f":"五言律诗","c":["万队千骑出，燕游第一时。","繁华虽有态，烟水未曾知。","西去层层岫，东来面面池。","胸中好丘壑，借与主人为。"]},{"t":"月夜归来与长孺道旧仍用前韵","f":"五言律诗","c":["盛事那堪记，衰来亦自悲。","看穷烟柳地，老尽露桃枝。","算酒休论石，税花莫计池。","平生心种种，难及壮时为。"]},{"t":"偕曾退如过净土盖","f":"五言律诗","c":["像设都非丽，疏题亦不红。","花移牛槛日，槐老一庭风。","寓目皆成淡，诸方敢斗空。","到门有醉客，乡里旧山公。"]},{"t":"汤嘉宾以使事入江西将遍游诸名胜诗以送之 其一","f":"五言律诗","c":["碧渚苍云路，长帆几叶还。","趁秋行九子，携谱看庐山。","采药灵溪见，映花石户关。","孤藤双竹屦，听尽水潺湲。"]},{"t":"汤嘉宾以使事入江西将遍游诸名胜诗以送之 其二","f":"五言律诗","c":["亦解惊人语，干君数倍难。","片鳞犹变化，尺水尚波澜。","万卉经春烂，千山过月寒。","欲知才大小，试取昔贤看。"]},{"t":"汤嘉宾以使事入江西将遍游诸名胜诗以送之 其三","f":"五言律诗","c":["九派浔阳地，寒潮一叶通。","少年姑狡狯，太舌石玲珑。","触路飞泉雨，扪碑怪穴风。","到时秋正老，江景绘丹枫。"]},{"t":"汤嘉宾以使事入江西将遍游诸名胜诗以送之 其四","f":"五言律诗","c":["携去山盈袖，书来墨满岩。","岚光疲瘦仆，泉水洗尘衫。","识遍金仙侣，搜残玉简函。","楚云青咫尺，汉水莫停帆。"]},{"t":"早起入朝书册午间冲暑走城外别汤嘉宾晚赴刘元定饮时诸公已半酣赋得原字","f":"五言律诗","c":["晓出铜龙署，暮归曲水村。","座凉心乍贴，觥乱饮初喧。","妥尾筠侵阁，长头客在门。","公然去巾屣，奴态亦堪原。"]},{"t":"夏日城西园亭闻蝉得阴字 其一","f":"五言律诗","c":["清响彻平林，云深树亦深。","乍闻心爽豁，蠲尽午昏沉。","琴里高山韵，诗中瘦岛吟。","乡园频梦尔，中里柳湖阴。"]},{"t":"夏日城西园亭闻蝉得阴字 其二","f":"五言律诗","c":["未曾离溽暑，亦不到云林。","坐觉暄凉变，遂令院舍深。","声来如远壑，宿处必层阴。","燕子与黄鸟，难除闺阁音。"]},{"t":"夏日城西园亭闻蝉得阴字 其三","f":"五言律诗","c":["虽在高云地，长怀冷石心。","羽流分体魄，骚客与声音。","竹柏风相乱，笙歌耳可箴。","如何君与我，俱不守长林。"]},{"t":"苦雨吟和曾退如 其一","f":"五言律诗","c":["陵雨无朝夕，呻吟益病妻。","床头新墁落，灶下老㜎啼。","一室坳堂芥，千家乱水畦。","侍儿持茗语，满褶裤花泥。"]},{"t":"苦雨吟和曾退如 其二","f":"五言律诗","c":["旧势将排砌，新痕又没花。","街头眠野鹜，窗上语池蛙。","古佛龛生菌，娇儿面有沙。","东斋无额字，便可唤浮槎。"]},{"t":"苦雨吟和曾退如 其三","f":"五言律诗","c":["似道雷焚火，又闻水决墙。","哭声来远巷，昏火照方床。","小屋苇帘破，邻家苍术香。","儿童浪惊喜，檐底有微光。"]},{"t":"苦雨吟和曾退如 其四","f":"五言律诗","c":["莫是天家乐，轻闻下土哀。","九州吹立水，万部役雕雷。","地远声难彻，阍高唤不回。","巢居与穴处，曾见有唐来。"]},{"t":"中秋泊潞河看月同子公云影赋 其一","f":"五言律诗","c":["秋树泠泠白，添衣也觉寒。","如何今夜月，不共昔人看。","客路风停阁，民居水破残。","那堪更值此，衰草漫流滩。"]},{"t":"中秋泊潞河看月同子公云影赋 其二","f":"五言律诗","c":["万水千山路，羁魂来不来。","双签题姓字，两处送钱财。","风叶牵钩幔，寒花背镜台。","思量具杯酒，有口向谁开。"]},{"t":"中秋泊潞河看月同子公云影赋 其三","f":"五言律诗","c":["亦欲消孤闷，其如不去心。","稚儿神惨淡，病客语呻吟。","野戌风传柝，空艚火隔林。","更怜明月里，尚有独飞禽。"]},{"t":"中秋泊潞河看月同子公云影赋 其四","f":"五言律诗","c":["道侣前宽解，君深天竺书。","我心自检点，试比毗邪庐。","法喜妻辞世，散花天异居。","任他金粟老，亦有泪涟如。"]},{"t":"潞河舟中和小修别诗 其一","f":"五言律诗","c":["鹤老翻辞侣，松寒乍剪萝。","孤舟将幼累，北海望南讹。","乱苇藏村社，枯槎卧古河。","所嗟人异路，不畏客程多。"]},{"t":"潞河舟中和小修别诗 其二","f":"五言律诗","c":["昔日饥寒伴，凄凉无一存。","去花难返榭，好月不留轩。","龟手衣犹在，齐眉案尚温。","一门新旧鬼，强半北方魂。"]},{"t":"潞河舟中和小修别诗 其三","f":"五言律诗","c":["一恸出云堂，秋高雁影凉。","容颜渐朽谢，恩爱日销亡。","竹老湘君庙，花深油水阳。","解君旧箧笥，拟买白莲庄。"]},{"t":"潞河舟中和小修别诗 其四","f":"五言律诗","c":["欲觅藏身处，瞿童路上寻。","鱼宁愁不阔，鸟岂畏山深。","秋叶虹霜寺，春苞紫笋林。","辟如纵鹦鹉，未有恋笼心。"]},{"t":"潞河舟中和小修别诗 其五","f":"五言律诗","c":["少谢人间事，歌坛与舞筵。","有山皆种竹，无水不栽莲。","见死知生苦，月鳏识道缘。","一杯从惠远，白社问诸贤。"]},{"t":"潞河舟中和小修别诗 其六","f":"五言律诗","c":["江柳江枫道，秋来倍损神。","琼花撩怨客，香草梦离人。","白鸟谁非故，青山不厌贫。","陶朱吾可学，整水养鲲鳞。"]},{"t":"潞河舟中和小修别诗 其七","f":"五言律诗","c":["客路虽云苦，烟波亦自清。","云开九子近，月上五湖明。","石壁同僧看，花坊信马行。","家缘无十口，少累省忧生。"]},{"t":"潞河舟中和小修别诗 其八","f":"五言律诗","c":["弟也檀州去，征南尚可依。","青油寒夜醉，画戟晓风威。","塞草鞲鹰疾，胡天字鸟飞。","吾庐行信美，乡社几时归。"]},{"t":"潞河舟中和小修别诗 其九","f":"五言律诗","c":["小艇烟江雨，长堤杮叶霜。","一洲鱼子市，千树木奴乡。","客去寻空谷，书来话酉阳。","繁华销枕上，家近吕仙堂。"]},{"t":"潞河舟中和小修别诗 其十","f":"古风","c":["禅味争如醉，无何即是乡。","休心为曲蘖，省事作资粮。","慢世稍同朔，绝交亦似康。","东?犹滞酒，余乃醒而狂。"]},{"t":"沧洲逢瞿太虚运使问及近事偶题 其一","f":"五言律诗","c":["问我京华事，动君一日愁。","添多新世态，无复旧交游。","北寺凉阴尽，西堂讲席收。","烟光逐日改，那不念归休。"]},{"t":"沧洲逢瞿太虚运使问及近事偶题 其二","f":"五言律诗","c":["白帢生蕉屦，知君亦悼亡。","忧时心耿耿，学道鬓苍苍。","老衲同三昧，稚儿守一床。","所惭不共隐，魂魄滞他方。"]},{"t":"德州舟中逢沈何山 其一","f":"五言律诗","c":["鬓上微添雪，衣间亦有尘。","俱为行役客，孰是自由身。","处世真妨达，归山无那贫。","且收鱼鸟韵，检点作时人。"]},{"t":"德州舟中逢沈何山 其二","f":"五言律诗","c":["敢谓冯唐老，为郎十五年。","不因君濡滞，那与我周旋。","历历分行树，匆匆两去船。","此心无近远，月在浩池边。"]},{"t":"偶作","f":"五言律诗","c":["为道知难进，求閒亦未成。","凭将无益事，娱此有涯生。","见水移觥去，闻山皆襆行。","感时多长语，虚窍偶然鸣。"]},{"t":"下邳舟中和子公","f":"五言律诗","c":["飞雨贱窗湿，衣寒拥敝裈。","所忧唯腊近，最苦是荼浑。","只有飞沙市，更无啼鸟村。","两渔相对语，舟系古槐根。"]},{"t":"集平山堂用平山字为韵偕游者方子两谢生也 其一","f":"五言律诗","c":["衰草乱畦平，长江一线明。","云开智者寺，山表润州城。","万井清霞气，千樯晚吹声。","隋宫何处问，荆杞傍墙生。"]},{"t":"集平山堂用平山字为韵偕游者方子两谢生也 其二","f":"五言律诗","c":["天业空遗事，披图咫尺间。","斜桥兴废水，淡墨有无山。","野老囲香泽，妖狐学黛鬟。","荒亭犹故井，马上挈泉还。"]},{"t":"邹子尹偕僧秋水见访门者不知却之相见乃一笑","f":"五言律诗","c":["几失孔文举，惊逢祢正平。","云澄天自澈，月上海先明。","渴骥闻泉喜，孤鸿见侣鸣。","昭文琴自好，无那有亏成。"]},{"t":"雪中投宿栖隐寺寺去大冶五千里在乱山中 其一","f":"五言律诗","c":["下马历巑屼，晶晶四壁寒。","山门云占断，佛舍雨浇残。","茶好临泉试，松宜带雪看。","轩窗无一可，孤负此峰峦。"]},{"t":"雪中投宿栖隐寺寺去大冶五千里在乱山中 其二","f":"五言律诗","c":["岩户何人启，泉声只自闻。","夜浇盈衲雨，晓耨一犁云。","野笋呼雏伐，山苗带子分。","会须知此意，禅讲也输君。"]},{"t":"雪中投宿栖隐寺寺去大冶五千里在乱山中 其三","f":"五言律诗","c":["细数高低岭，閒询远近乡。","山烟随涧出，松火隔林香。","云冷莓苔殿，雪封萝薜墙。","里门通德近，谁与辟荒凉。"]},{"t":"立春日金牛道中","f":"五言律诗","c":["田夫辍耒耜，红女停机梭。","士人废简编，官吏罢征科。","商贾离廛肆，渔家收钓罗。","余独何人者，峻岭与危坡。"]},{"t":"汉阳过王章甫葵园和二仲韵","f":"五言律诗","c":["户外即遥岑，寒香渐出林。","增池缘亩阔，疏竹为庭阴。","烟雪裁为句，风泉写入琴。","欲知桐性老，火里试焦音。"]},{"t":"舟中除夕忆李安人","f":"五言律诗","c":["客里逢除夕，灯前少故人。","乍如云没海，忽似影离身。","满褶衣衫泪，半年河渚尘。","井枯泉脉在，栋老燕巢新。"]},{"t":"王章甫送余石头口因共游赤壁章甫将归读书九峰山 其一","f":"五言律诗","c":["小舫沙棠楫，矶头试一游。","偶然偕郭李，不是吊曹刘。","山色当陲出，江波载世流。","沉沙无折戟，应已化渔钩。"]},{"t":"王章甫送余石头口因共游赤壁章甫将归读书九峰山 其二","f":"五言律诗","c":["晴柳烟江路，幽探喜共君。","暮风歌鸟翮，春水玩鱼纹。","石老犹含态，蛟闲不起云。","沙头寻鹭侣，且莫话三分。"]},{"t":"王章甫送余石头口因共游赤壁章甫将归读书九峰山 其三","f":"五言律诗","c":["一棹别乌林，高云去去深。","易销唯黑发，未了是名心。","洗墨桐花下，读书石壁阴。","明年定传写，千纸满璆琳。"]},{"t":"柳浪馆杂咏 其一","f":"五言律诗","c":["柳匝层层水，花纷曲曲堤。","古藤随意拙，熟鸟任情啼。","寄客诗题岳，招僧语隔溪。","菱蒲分外长，渐与竹栏齐。"]},{"t":"柳浪馆杂咏 其二","f":"五言律诗","c":["偶然修竹里，新鸟一回闻。","鸡下翻盆石，僧归语峤云。","纵风生水态，任月织波文。","莫遣鸥凫去，频来只有君。"]},{"t":"柳浪馆杂咏 其三","f":"五言律诗","c":["饶水饶烟地，谅花临柳居。","经营成净社，穿凿架僧庐。","小作番唐像，闲堆农圃书。","主人荤血断，鹤亦念溪鱼。"]},{"t":"柳浪馆杂咏 其四","f":"五言律诗","c":["斋阁行将近，迂回又隔蹊。","八窗中远水，万柳外长堤。","凿曲添鱼舍，芟枝减鹤栖。","无人残暴汝，宜近亦宜低。"]},{"t":"过藕花庄","f":"五言律诗","c":["深院竹编墙，丛梢若个长。","入门溪雨溅，满路麦风香。","好梦因凉得，閒愁到水忘。","因循二十载，来到藕花庄。"]},{"t":"夏日同顾朗哉居士王遗狂游谢公岩主人于野宗侯留饮 其一","f":"五言律诗","c":["只有烟林在，王家一事无。","到门唯藓石，对语画山臞。","路失云相引，厓攲竹可扶。","看人车马去，尘起是修途。"]},{"t":"夏日同顾朗哉居士王遗狂游谢公岩主人于野宗侯留饮 其二","f":"五言律诗","c":["莫损莓苔壁，长留翠倚空。","云能供点缀，石自解玲珑。","泉落当窗径，香生渡涧风。","楼台杳何许，树影有无中。"]},{"t":"登定州开元寺塔 其一","f":"五言律诗","c":["孤塔三千级，俯身见鸟过。","但知天阔远，未许岫嵯峨。","铃语闻沙塞，灯光射虏河。","昔贤谁眺此，韩宋与东坡。"]},{"t":"登定州开元寺塔 其二","f":"五言律诗","c":["我醉中山酒，兴衰渺莽间。","宋家遗塞垒，唐典旧河山。","破壁风雷出，空堂燕雀还。","莫言无外警，西去即层关。"]},{"t":"黄竹石入都作别","f":"五言律诗","c":["北阙何曾过，西山亦未登。","袖中无半刺，须上有层冰。","梦入冲烟鹤，书询过海僧。","省庐真似水，知汝不求丞。"]},{"t":"残冬选曹乏人戴星出入不觉过春感而赋此","f":"五言律诗","c":["若问曹中事，但观鬓上丝。","经年未见水，初度也无诗。","夜月閒杯子，春光恼侍儿。","西郊有游骑，唯汝不相宜。"]},{"t":"初授司功副郎","f":"五言律诗","c":["舍锻来为吏，嵇康也未慵。","带犹悬素銙，衔得比青松。","案牍心先碎，疏题手自封。","何年桂神武，买断紫芝峰。"]},{"t":"寒食高梁桥","f":"五言律诗","c":["簿领送春光，须眉分外苍。","僧犹怜我老，水亦怪人忙。","两作青山色，风吹翠袖香。","醉中如有忆，艇子上馀杭。"]},{"t":"暮春偕苏潜夫丘长孺李茂实僧宝方雪照出郭","f":"五言律诗","c":["且复须臾坐，夕阳山气佳。","人归烟雨寺，春到海棠花。","茜甲缘畦吐，青溪带郭斜。","楼台深隐隐，种竹定谁家。"]},{"t":"暮春同王以明丘长孺苏潜夫魏二方游韦氏庄得宽字 其一","f":"五言律诗","c":["几叶茭蒲水，微风亦起澜。","如何寻丈地，绰有江湖宽。","种果栽花易，招鸥引鹭难。","辋川如具礼，画里试思看。"]},{"t":"暮春同王以明丘长孺苏潜夫魏二方游韦氏庄得宽字 其二","f":"五言律诗","c":["树历高云老，门临细水寒。","乱中时有整，幽处偶然宽。","芦笋芽将茁，槟榔蕊渐残。","游鳞真可喜，梦不到渔竿。"]},{"t":"暮春同王以明丘长孺苏潜夫魏二方游韦氏庄得宽字 其三","f":"五言律诗","c":["径路微微折，亭轩倍倍宽。","经营百事善，物力屡朝看。","果税分时敛，茶坊凑水安。","袈裟幸自乐，何苦恋中冠。"]},{"t":"饮渭南郭外水亭","f":"五言律诗","c":["清响落银塘，崖高瀑白长。","晴飞半院雨，暑洗一山凉。","竹石江南梦，云泉逸士肠。","长安卜日饮，金紫照壶觞。"]},{"t":"喜小修至 其一","f":"五言律诗","c":["疋马西风客，青衫远道人。","倾觞三日语，洗面一升尘。","发箧探家信，呼儿换葛巾。","颜肥兼耳阔，失意几曾嗔。"]},{"t":"喜小修至 其二","f":"五言律诗","c":["家事若蚕丝，细听无了期。","某山今旷废，何仆最顽痴。","验貌争肥瘦，谭心校髓皮。","因勘对病药，第一是随时。"]},{"t":"喜小修至 其三","f":"五言律诗","c":["俱言三岁苦，挨得几番虚。","鍊就玉圭字，磨穿铁板书。","莫非头罪过，傥亦慧乘除。","知汝能排遣，高谭且自如。"]},{"t":"喜小修至 其四","f":"五言律诗","c":["买米钱都尽，装衣絮亦无。","奴颜愀失路，马尾秃长途。","沙哭终雠楚，梁舂已去吴。","弥天布铁网，不肯拔珊瑚。"]},{"t":"与小修夜话忆伯修","f":"五言律诗","c":["羁客观人世，孤云信此生。","长兄官自达，小弟学无成。","买酒思灯市，踏花忆贯城。","飞沙没马首，怕不御街行。"]},{"t":"百六诗为丘大赋 其一","f":"五言律诗","c":["血蚀青铜照，魂牵白玉环。","人间冤女冢，地下望夫山。","著土泪犹碧，邻湘草亦斑。","至今西陵月，不忍向南弯。"]},{"t":"百六诗为丘大赋 其二","f":"五言律诗","c":["一夕归兹路，三生惜此人。","死无长负债，恨是不销尘。","小玉终为厉，苏卿必有神。","决猊与怒蟒，无以喻吾嗔。"]},{"t":"百六诗为丘大赋 其三","f":"五言律诗","c":["恶雨催兰桂，饥枭啄凤凰。","埋忧觉地小，量恨与天长。","万者难焦泪，千生不化肠。","明当告世主，幽合诅城隍。"]},{"t":"百六诗为丘大赋 其四","f":"五言律诗","c":["怪事咄如许，稗官见亦稀。","若无亲口语，定道客传非。","始觉生为债，谁言鬼是归。","长时检遗箧，不忍触歌衣。"]},{"t":"百六诗为丘大赋 其五","f":"五言律诗","c":["冤诉知无已，冥司可奈何。","只愁女鬼弱，不怕俗钱多。","双陆因名废，新声只自歌。","唯当仗佛力，救汝出幽罗。"]},{"t":"赴栖霞","f":"五言律诗","c":["黄叶三秋后，青烟一脉中。","天寒虫蛰雨，江阔鲤鱼风。","鹤瘦行藏劲，鸥閒饮啄工。","舟迂迷去处，小立问渔翁。"]},{"t":"摄山纪游 其一","f":"五言律诗","c":["黄叶旋空下，清泉作雨飞。","苔毛青佛面，石色老天衣。","僧静厨蔬少，山寒野雀稀。","自然消万虑，不是学忘机。"]},{"t":"摄山纪游 其二","f":"五言律诗","c":["山色重重怪，高谭事事新。","荒松吹老鬣，古石长斑鳞。","入室寻僧梦，翻经晤客尘。","禅兄兼酒弟，傲杀世间人。"]},{"t":"小集张伯实斋头","f":"五言律诗","c":["白菊颜将赭，苍原木渐黄。","蟹匡行酒至，梧子作阎藏。","钩月分兰焰，玄霜打橘房。","主人红靺鞈，一笑上排场。"]},{"t":"问方子公病 其一","f":"五言律诗","c":["落尽梧桐叶，萧骚满一庭。","当书裁枕被，减食买参苓。","壁暗秋虫泣，垆攲夜火青。","病来曾几日，疏发冷生星。"]},{"t":"问方子公病 其二","f":"五言律诗","c":["贫病知何极，高天也不原。","愁声彻晓夜，药气满楹轩。","梦恶凭奴解，衣单借手温。","空堂悬一榻，黄叶自封门。"]},{"t":"送李季宣比上 其一","f":"五言律诗","c":["长短丹枫道，高低白雪枝。","奚如肩古帙，骏尾束红丝。","闺月能通梦，边烽易入诗。","因思誇官日，是我见朝时。"]},{"t":"送李季宣比上 其二","f":"五言律诗","c":["策蹇迎霜去，冲风逆雁行。","梦中呼小玉，瓮底拜荆卿。","驿路听塘报，寒冬怯水程。","预知廷对策，多半是谈兵。"]},{"t":"日暮","f":"五言律诗","c":["苍茫山几处，高下鸟千枝。","野火烘云脚，霜风老地皮。","安心权在酒，长日困于诗。","除却閒居外，朝昏总不知。"]},{"t":"望乡","f":"五言律诗","c":["无日无乡梦，空街与大堤。","白长香米熟，青浅麦芽齐。","荻月铺双寺，渔双冷孟溪。","长江无尽处，渐觉雁飞低。"]},{"t":"偶成","f":"五言律诗","c":["掷却颠毛去，百无一事齐。","客中稀信至，梦里别家啼。","野店胡桃小，山房枸杞低。","慇勤托鹪鸟，借取半枝栖。"]},{"t":"送蕴璞之通州","f":"五言律诗","c":["敝衲才三尺，羞囊无数钱。","谭诗宗岛瘦，运笔想怀颠。","白果行厨饭，枯株半夜禅。","天涯青点点，一脉海门船。"]},{"t":"忆潘景升","f":"五言律诗","c":["赤仄何年至，青蛾几日休。","当衣归楚子，兑酒卖吴钩。","冻雨江豚泣，邮风海若秋。","相思无寄处，独上县西楼。"]},{"t":"寄伯修","f":"五言律诗","c":["次第逢京使，皆言鬓有华。","廊餐博白饼，宫雪打乌纱。","夜起先鸡唱，朝归必日斜。","倦来呼侍史，石水试煎茶。"]},{"t":"即事","f":"五言律诗","c":["越锦刺吴女，桐弦命小妻。","炉鸣茶已罢，香散日初低。","近火观猫戏，閒窗听鸟啼。","乡书修总懒，笑作两行题。"]},{"t":"扬州晓泊","f":"五言律诗","c":["薄雾随风尽，寒霜对酒销。","芋魁腾晓市，蟹子趁归潮。","往事琼花观，新沟杨子桥。","虽然富罗绮，未必似前朝。"]},{"t":"即事","f":"五言律诗","c":["野树凋青叶，寒江扫白波。","讹音东事变，重语北船过。","衢橘连霜买，卢姬尽日歌。","扬州饶嫁娶，箫鼓夜来多。"]},{"t":"赋得迷楼","f":"五言律诗","c":["古寺行宫是，荒台迹近真。","枫枯能作语，钗老化为人。","夜蜡烧天泪，秋蛾幻月新。","当年倘不乐，难道不成尘。"]},{"t":"小集吴嗣仙斋头","f":"五言律诗","c":["寒月冲帘薄，空阶似水凉。","橘皮消酒气，栗尾乱书床。","校拇人高下，踏歌调短长。","自知非饮客，亦不喜欢场。"]},{"t":"集乔光禄斋头","f":"五言律诗","c":["烛气烘人煖，帘丝透月来。","近花安饮几，分筱出重台。","细曲龙香拨，清酣鹄卵杯。","彻明尚不去，安肯见灯回。"]},{"t":"饭王太古馆中","f":"五言律诗","c":["万事无如静，浮云他自飞。","身心全白业，行止半缁衣。","山药和霜荐，园禽带雪饥。","忘名兼去欲，学道古人稀。"]},{"t":"偶成","f":"五言律诗","c":["贫色杯中减，衰音镜里知。","青山千里屐，白发满头诗。","夜雪烹朝水，鲜花勒陈枝。","回身笑罔两，尔我共支离。"]},{"t":"感怀作","f":"五言律诗","c":["閒适鱼归水，孤羁鸟怯飞。","寒江粘戍艘，贾俗厌儒衣。","失路于人左，贪生学道非。","无才甘自弃，不是怨知希。"]},{"t":"雪中","f":"五言律诗","c":["盖膝衣三补，充脾饭一匙。","长贫商贾贵，久客保佣知。","开帖临黄字，关门变黑髭。","飞蓬逐流水，何日是休时。"]},{"t":"閒行","f":"五言律诗","c":["入肆添红晕，出门换白衣。","雉惊过水去，雀冷近仓飞。","古木半身死，邻僧一个归。","客中无旧识，远望却依稀。"]},{"t":"雪中看月","f":"五言律诗","c":["强起持杯酒，长歌命小鬟。","一重两重白，千里万里山。","冻鹤僵孤影，穷霜益老颜。","客思只如此，渐梦别离顽。"]},{"t":"无题","f":"五言律诗","c":["富贵岂非情，荣枯未必平。","破笼麾鸟去，斸竹放云行。","穷骨耽书傲，寒毛看剑生。","东方唇自腐，执戟竟何成。"]},{"t":"读书","f":"五言律诗","c":["拭却韦编尘，衣冠对古人。","著来皆肺腑，道破益精神。","把斧樵珠玉，恢纲网凤麟。","拟将半尺帚，匝地扫荆蓁。"]},{"t":"閒居","f":"五言律诗","c":["只对陈编坐，閒将稚子行。","笔罢书将老，瓶响茶初成。","饥鹤窥冰涧，穷鸦话夕城。","江烟回照里，转湿转鲜明。"]},{"t":"乍晴即事","f":"五言律诗","c":["寒日回霜薄，天风扇雪晴。","山纹斜界露，树影拗枝横。","海客须眉冻，门宾姓字生。","下床忘栉洗，抛卷上西楹。"]},{"t":"偶成","f":"五言律诗","c":["寒日抛残历，冬风迫小年。","霸图虚孟尺，贫策付丘鞭。","释闷多诙史，嬴欢少破钱。","不簪复不履，随意但高眠。"]},{"t":"刘侯宴","f":"五言律诗","c":["满斗撒珠玑，窗风射蜡晖。","乐从三奏罢，酒看十分飞。","参佐分山果，优人撤地衣。","为贪文字饮，小减邑侯威。"]},{"t":"陶石篑书至","f":"五言律诗","c":["不复言馀事，唯云了即休。","山川销断案，花鸟罢春秋。","定后窗行鼠，餐时壁下猴。","自无求相意，焉用钓文钩。"]},{"t":"何茂倩索游吴诗","f":"五言律诗","c":["莫漫谈吴事，吴中佳事多。","天高震泽网，发细虎丘歌。","只是官无那，由来谷喜过。","莫釐与緸缈，双峰孰嵯峨。"]},{"t":"子公贫病口占乞笑","f":"五言律诗","c":["病阅冬秋尽，方穷内外科。","梦来牵母泣，愁觉此身多。","愧涸鱼求水，翎单雀窘罗。","伤心谈往事，悔作恋灯蛾。"]},{"t":"扬州舟中晨起","f":"五言律诗","c":["薄月层冰上，飞飞叫去鸿。","梦寒孤渚雪，茶向一垆风。","冻网悬枯木，荒崖依病枫。","繁华无用处，陡觉恋虚空。"]},{"t":"送洪子崖之归化县","f":"五言律诗","c":["小邑无官长，登临费履綦。","方言从事译，山景隶人知。","廨舍巢鹦鹉，乡田贡荔枝。","岚光侵簿牍，长日但围棋。"]},{"t":"丁酉除夕","f":"五言律诗","c":["得意人间事，经年作旅人。","愁因山水减，荡免父兄嗔。","蜡屐千乡雪，公衣几摺尘。","瓜洲波起处，长日望垂纶。"]},{"t":"登苏门山泛舟百泉 其一","f":"五言律诗","c":["食罢共成饭，来观泌水泉。","废桥穿竹屿，小舫载茶烟。","方外清溪寺，人间好畤田。","那能营二项，风雨啸台眠。"]},{"t":"登苏门山泛舟百泉 其二","f":"五言律诗","c":["一叶寒塘上，孤云信所如。","东亭观美箭，西沚访幽居。","静玩涵波羽，幽怜避饵鱼。","未容狂阮籍，沉湎污清虚。"]},{"t":"和朱非二山间之作 其一","f":"五言律诗","c":["入谷非无路，凿空尚有痕。","势危攀棘杪，力尽憩松根。","天上云烟市，仙家水石村。","悠然见邃古，梦里亦羲轩。"]},{"t":"和朱非二山间之作 其二","f":"五言律诗","c":["愁绝苍龙岭，苔青万古铜。","㠉深凭绠汲，栈绝赖枝通。","洞隔寒溪雪，僧归石璺风。","半卷轻四岳，一笑傲三公。"]},{"t":"和朱非二山间之作 其三","f":"五言律诗","c":["只觉川原变，宁知七曜同。","按图穷大地，卓笏量虚空。","霞过遗仙影，云归识海风。","人间三不朽，尘里一微虫。"]},{"t":"和朱非二山间之作 其四","f":"五言律诗","c":["极态穷工出，摩天插地孤。","平开东震旦，坐想先供卢。","曰石铛何在，青溪鹤也无。","浩歌中夜月，万里湛冰壶。"]},{"t":"和朱非二山间之作 其五","f":"五言律诗","c":["云懒飞难上，龙痴卧不醒。","巴江寒荡日，郑火夜飞星。","炉瀹千年液，松留太古青。","绿霞封石锁，应是护仙经。"]},{"t":"偕朱非二入少林至初祖洞","f":"五言律诗","c":["宿世同来否，青山记梦登。","云分新坠石，树老旧扶藤。","古藓番文印，胡䰄壁影僧。","摩公真狡狯，只履去何曾。"]},{"t":"话无言上人方丈","f":"五言律诗","c":["秋子拨秋烟，堂头二十年。","还君半面识，乞我一蠡禅。","石壁分窗看，松风对榻眠。","浮生成泛泛，俱有雪毛县。"]},{"t":"山中逢老衲少时从征有功者","f":"五言律诗","c":["头发遮眉白，归来五乳峰。","梦中闻虏笑，定起看经慵。","戒铁支为枕，衲衣挂在松。","閒时穿洞壁，欲去縳狞龙。"]},{"t":"次良乡","f":"五言律诗","c":["劳碌岂堪怜，心情亦自偏。","閒中长似郁，途里却翛然。","草屦多生业，名山老去缘。","云岚成妄想，渴梦走鸣泉。"]},{"t":"次定川和壁间韵","f":"五言律诗","c":["岁岁疲车马，劳劳憩此州。","精神渐耗减，名字益虚浮。","斜月微茫岫，平河散漫流。","西溪莲在否，持语去年鸥。"]},{"t":"定州见拙诗拓戏题","f":"五言律诗","c":["塔上烟煤句，何人勒此中。","鸣虚聊以蚓，篆壁偶如虫。","蚀去宜苔藓，销来仗雨风。","而今真入石，泥土被丹红。"]},{"t":"宿赵州","f":"五言律诗","c":["入市不闻嚣，残阳半丽谯。","人家多画水，贾肆尚依桥。","禅梦采清磬，秋心动夜条。","柏林如见语，还汝旧时瓢。"]},{"t":"晓出柏乡","f":"五言律诗","c":["未晓已先兴，轩车带睡登。","官程胶齿饭，乡思折腰菱。","野店歌鬟女，孤庵瀹鼎僧。","不酲亦不醒，沙里鼓鼟鼟。"]},{"t":"书所见","f":"五言律诗","c":["落日澹秋容，游云忽自重。","斜披四五树，乱点两三峰。","马顾横桥水，僧归别路松。","岩深不见寺，烟里忽闻钟。"]},{"t":"崤陵壁间见黄平倩诗怅然有怀和韵","f":"五言律诗","c":["角声催晓关，云冷梦初还。","秋是王维句，月如李白颜。","涸泉长念雨，笼鸟岂忘山。","拟把一竿去，相从水石间。"]},{"t":"潼关题壁","f":"五言律诗","c":["一枕簟花凉，魂清梦亦长。","雌雷方唤醒，女魃乍迷藏。","云识鬘鬟气，风知菡萏香。","那能倦膏沐，千里酒兰汤。"]},{"t":"偕朱非二汪以虚段徽之雨中投兴教寺望南山 其一","f":"五言律诗","c":["树古积苔痕，山高昼易昏。","袖中云气出，阶下水声喧。","断鼎残埤寺，青螺紫涧村。","倚阑叩京尹，还我玉峰轩。"]},{"t":"偕朱非二汪以虚段徽之雨中投兴教寺望南山 其二","f":"五言律诗","c":["迹往休寻记，台倾莫问年。","风香来韦曲，雪色照樊川。","野寺遮红叶，人家住翠莲。","隔溪山更好，驱马入苍烟。"]},{"t":"偕朱非二汪以虚段徽之雨中投兴教寺望南山 其三","f":"五言律诗","c":["槛外即危岭，烟中跨楚秦。","石留前劫字，洞老别朝人。","夏月莲花雪，冬风暖谷春。","云深无隙地，千里瘦龙鳞。"]},{"t":"过华清宫浴汤泉 其一","f":"五言律诗","c":["镜澈古苔光，溪风湛碧香。","花犹知世代，水不解兴亡。","粉黛山川俗，烟泉岁月长。","而今正好景，石骨照苍凉。"]},{"t":"过华清宫浴汤泉 其二","f":"五言律诗","c":["十六长汤院，阿谁似玉环。","故宫秋草里，小邑水声间。","童子驱羊去，村姑赛庙还。","教他扬广笑，破国只骊山。"]},{"t":"过华清宫浴汤泉 其三","f":"五言律诗","c":["过鸟烟中迹，回风水上痕。","欲知天宝事，唤起石苔言。","兰乳飞千殿，宫云绕数村。","太真方病齿，歌拍且停翻。"]},{"t":"过华清宫浴汤泉 其四","f":"五言律诗","c":["羯鼓弄伊凉，露花石火光。","山馀绣领字，云染碧螺香。","芍药留妃子，鹦哥说上皇。","难将脂粉水，傲我白云乡。"]},{"t":"过华清宫浴汤泉 其五","f":"五言律诗","c":["凤靡鸾吪易，王图霸业轻。","仙灵祠后见，笙柷夜深鸣。","野火烧连理，秋风荐侧生。","遥知石镜月，恨不照倾城。"]},{"t":"过华清宫浴汤泉 其六","f":"五言律诗","c":["东岭复西岭，秦乡与汉乡。","市城云淡淡，今古水汤汤。","废址耕斜坂，归樵话夕阳。","乱亡犹有等，最劣是幽王。"]},{"t":"再泛百泉","f":"五言律诗","c":["欲去复停帴，瓶瓯尚在船。","异沙千种色，密雨一湖泉。","有鹤山中梦，无人池上弦。","醉归旋就枕，带却涧声眠。"]},{"t":"浪歌","f":"古风","c":["朝入朱门大道，暮游绿水桥边。","歌楼少醉十日，舞女一破千钱。","鹦鹉睡残欲语，花骢蹄健无鞭。","愿为巫峰一夜，不愿缑岭千年。"]},{"t":"渑池和黄平倩壁间诗 其一","f":"古风","c":["落日疏林涧水，秋风匹马咸秦。","南北陵收过雨，东西崤起飞尘。","龙锁幽崖翠乳，雷绕古树苍鳞。","穴处巢居谁氏，断辕折轸何人。"]},{"t":"渑池和黄平倩壁间诗 其二","f":"古风","c":["四顾陂陀无地，一螺乡井有君。","百一崤函天险，五千道德灵文。","驿路屏遮障掩，溪田错绣罗纹。","思触枕边流水，梦牵峤外孤云。"]},{"t":"登焦山","f":"七言律诗","c":["海门一带雾初收，碧树丹崖小十洲。","山杂云帆浮水上，江盘螺髻出潮头。","经堂昼寂眠苍兕，石壁晴空挂野猴。","白首闭关僧自苦，花开花落也春秋。"]},{"t":"病中和黄道元至日禅寺梦愁诗","f":"七言律诗","c":["一番花信又成春，百结枯肠万转轮。","铃下久停辰后版，功曹空阁案间尘。","消愁莫问弓蛇影，对境聊观梦幻身。","宫缕添来非我有，秪应添得与游人。"]},{"t":"閒居杂题 其一","f":"七言律诗","c":["树老无花也自新，山茶红似女儿唇。","数茎白发春前长，一点青峦雨后真。","莺欲下枝先作语，鹊能占岁亦如人。","锦鞯金络纷纷去，飞尽晴郊十里尘。"]},{"t":"閒居杂题 其二","f":"七言律诗","c":["儒衣脱却礼金仙，三十偷闲也少年。","芊草如毡花欲舞，淡烟垂幕柳高眠。","兴来学作春山画，病起重笺秋水篇。","酒障诗魔都不减，何曾参得老庞禅。"]},{"t":"閒居杂题 其三","f":"七言律诗","c":["晴日园林放好春，馆娃宫里拾香尘。","痴心春了鸳鸯债，宿命多惭鹦鹉身。","柳爱风流因病睡，鹊贪欢喜也嗔人。","桃花不识潘郎去，又逐东君一面新。"]},{"t":"閒居杂题 其四","f":"七言律诗","c":["一番丹蕊一番泥，何处垂杨无马嘶。","芍药有香兼有态，山鸡能舞亦能啼。","阴晴雨旱劳占问，云月风花细品题。","十分漆园学得五，逍遥犹可物难齐。"]},{"t":"閒居杂题 其五","f":"七言律诗","c":["幽窗重镊鬓边丝，嬴得青鬟谀少时。","垆合博山烟吐篆，沙烘石子煖围棋。","靓妆却念画眉鸟，佞巧愁听百舌儿。","笑杀陶家五杨柳，春来依旧折腰肢。"]},{"t":"閒居杂题 其六","f":"七言律诗","c":["纵多桃李也无言，只是然篱与映门。","暖日护将鹦鹉瘴，和风吹却鹧鸪瘟。","乡书题就双重晕，炉气熏残一缕温。","梦里明明渡湘水，不知若个似仙源。"]},{"t":"皇甫仲璋邀饮惠山上 其二","f":"七言律诗","c":["萍迹犹怜滞水乡，濯缨满地是沧浪。","罢来仙县郎官绶，扮作青溪道士装。","沙鸟惯人眠不醒，岸花经雨折还香。","相思别后知无益，烂向春风醉一场。"]},{"t":"元宵饮华中秘宅上 其一","f":"七言律诗","c":["青丝华管夜从容，客正阑时酒正浓。","堂上观灯莲品品，尊前顾影面重重。","博他镜月千回醉，假我云山第几峰。","麈尾奋来毛欲尽，当筵风雨约谭锋。"]},{"t":"元宵饮华中秘宅上 其二","f":"七言律诗","c":["长竿百尺拥灯轮，浊酒千巡意转真。","霜亚残枝花片老，云拖轻影月痕新。","订将白石成知己，掷却乌纱是野人。","漏水销来杯不尽，当轩鹦鹉亦留宾。"]},{"t":"饮华中秘园亭上","f":"七言律诗","c":["东风杨柳濯青枝，暖日池台艳艳姿。","巧石疏花宜对酒，文窗香阁好弹棋。","饥来野鹤如人懒，饮去河豚亦自疑。","竹里辛夷差得似，天然一幅辋川诗。"]},{"t":"得罢官报","f":"七言律诗","c":["拟将心事寄乌藤，料得前身是老僧。","病里望归如望赦，客中闻去似闻升。","尊前浊酒憨憨醉，饱后青山慢慢登。","南北宗乘参取尽，庞家别有一枝灯。"]},{"t":"游惠山作 其一","f":"七言律诗","c":["柳色渐舒枝渐齐，流莺涩涩美春啼。","花溪水赤香鱼子，荒草牙青倦马啼。","鹧鸟不行终恋侣，鹁鸠无屋懒呼妻。","一瓶煖贮惠泉酒，过得层峦日又低。"]},{"t":"游惠山作 其二","f":"七言律诗","c":["雪后青山暖复鲜，疏黄浅绿也堪怜。","高僧执卷供谈柄，少妇明妆送佛钱。","向子无端儿与女，华阳多事道兼禅。","浮生早被微名误，迟向人开醉五年。"]},{"t":"和沈飞霞代老姬别用原韵","f":"七言律诗","c":["双龙毛羽若为乖，销尽琵琶十里街。","燕子有情终恋主，鸡皮无色强名娃。","愁同班氏秋来扇，愿作杨家多浚钗。","桃叶桃根君记否，当年亲指带如淮。"]},{"t":"踏堤曲 其一","f":"七言律诗","c":["浓绿疏黄总古新，六桥风日更精神。","柳腰似欲争游妓，莺舌分明唤醉人。","暖谷蒸香疑作雨，芳蹊吹汗不沾尘。","洛妃谩欲淩波出，曹植荒唐恐未真。"]},{"t":"踏堤曲 其二","f":"七言律诗","c":["画阁层层出晓波，东风湖面软于罗。","佳人秾李山花髻，荡子垂杨水调歌。","蝴蝶意閒随梦去，鸳鸯情熟奈春何。","苏公雅亦称相识，浪比西施愧已多。"]},{"t":"踏堤曲 其三","f":"七言律诗","c":["桃叶成蹊柳作行，东风吹热少年场。","赵家姊妹皆端正，谢族儿郎有短长。","陌上口声多汴语，垆头结束尽唐装。","吴歌越舞颠如梦，不是湖山也断肠。"]},{"t":"踏堤曲 其四","f":"七言律诗","c":["亭亭如月婉如春，堤上楼边总丽人。","柳汁染将袍已嫩，梨花吹落粉痕新。","瑈帘欲度閒仙语，宝屐初移拾翠尘。","宋玉也知空作赋，越姬十倍胜东邻。"]},{"t":"饮第六桥酒垆上","f":"七言律诗","c":["流芳亭畔草如油，堕粉吹香历几秋。","鄂国有祠争下马，西陵无主漫登楼。","玉龙酿熟多酬直，土哺鱼肥易上钩。","南北诸峰收不尽，朝朝放艇过溪头。"]},{"t":"游虎跑泉","f":"七言律诗","c":["竹床松涧净无尘，僧老当知寺亦贫。","饥鸟共分香积米，落花常足道人薪。","碑头字识开山偈，炉里灰寒护法神。","汲取清泉三四盏，芽茶烹得与尝新。"]},{"t":"赠虞德园兄弟","f":"七言律诗","c":["霜庭五叶晚抽枝，喜得犹通一线儿。","时戒每尝无味水，闲情多赋落花诗。","台宗贤教谁能识，何肉周妻到应疑。","若使相逢不吐胆，更于何处觅相知。"]},{"t":"雨中过苏 其一","f":"七言律诗","c":["二年前事似前朝，记得朱颜个里销。","雨雨风风新震泽，车车马马旧虹桥。","尘来不上双行脚，病后犹存一捻腰。","是我万般辛苦地，如今闲话尽逍遥。"]},{"t":"雨中过苏 其二","f":"七言律诗","c":["无官有客尚留吴，难道陶潜不腐儒。","魂亦寻花如蛱蝶，梦惟逐浪似鹈鹕。","孤灯影瘦寒山寺，荒草流青夏驾湖。","学道参禅都未澈，一毛聊得比杨朱。"]},{"t":"秋日同梅子马方子公饮北安门","f":"七言律诗","c":["閒对枯槎与钓缗，暮云斑驳似龙鳞。","青山不许谈新事，白鸟如曾狎故人。","宫閤参差十里水，衣冠包裹一生尘。","西门车马东门月，冷热从谁问假真。"]},{"t":"伯修斋中","f":"七言律诗","c":["几点秋毛染鬓斑，深衣长褐古铜镮。","榻边石骨抽枯笋，盆里松根露浅山。","霜月洒来如白酒，菊花老去变红颜。","鸡声未动听宫板，已在车尘马足间。"]},{"t":"斋中偶题","f":"七言律诗","c":["冻风吹落壁间尘，温閤投花养瘦鳞。","山水情多长爱画，旃兰气少亦清人。","铛罍侧畔观时变，冠带场中看偶新。","野语街谈随意取，懒将文字拟先秦。"]},{"t":"閒居 其一","f":"七言律诗","c":["藤带丝袍强束身，北风虽厉不吹尘。","轩窗尽日閒诸史，眷属经年断五辛。","官牒注来呈府吏，俸钱支得与门人。","床头一夜西湖语，霜色萧条上角巾。"]},{"t":"閒居 其二","f":"七言律诗","c":["空街羸马有何荣，寂寞繁华两不成。","破懒始知经有味，送眠微觉酒多情。","腮毛未老随霜换，肺病无根见腊生。","收拾閒烟与閒水，凭将筠管作干城。"]},{"t":"閒居 其三","f":"七言律诗","c":["幽房睡足簟纹红，香鸭灰寒唤小童。","弦里乱流崩谷水，瓶中微带入松风。","身心何处谋长策，鬓发而今渐老翁。","净榻如绵窗似洗，明眸皓齿话虚空。"]},{"t":"閒居 其四","f":"七言律诗","c":["有衲层层煖蔽身，道书观了且存神。","懒心不恼思朝事，法服无端裹野人。","芡叶笺中书小偈，柘枝风里拾陈薪。","江湖冻裂冰皮老，霜郭时时有巨鳞。"]},{"t":"閒居 其五","f":"七言律诗","c":["空斋独坐拥残薪，笔有枯芒研有鳞。","梦里风窗听似语，山中烟树念如人。","儿童也解谈东事，箫鼓何因动壮邻。","竟日飞霾无却处，一层吹了一层尘。"]},{"t":"閒居 其六","f":"七言律诗","c":["霜鹤衔冰且忍饥，穷沙休忆稻梁肥。","低棋动欲求先著，钝鸟焉能不早飞。","身分无多难了事，酸迂那得济时机。","长安未有胶粘却，日日开门放客归。"]},{"t":"戊戌初度 其一","f":"七言律诗","c":["卑官自觉与心安，五亩无家去亦难。","毡榻所亲唯老易，儒衫相对几孤寒。","香茶每供邻僧去，院树时同小弟看。","雪色照帘花飐水，浊尊聊复对空盘。"]},{"t":"戊戌初度 其四","f":"七言律诗","c":["清溪曲曲几千松，梦里开门看鹤踪。","乡计久要桃叶渡，客程长念壮高峰。","笙歌渐渐于人懒，山水时时觉话重。","六载牵羁成底事，不如潇洒学为农。"]},{"t":"赠黄平倩编修","f":"七言律诗","c":["窗前独种庵婆罗，石火风灯不浪过。","箱帙夜翻尘牍少，客衣春晒衲头多。","毫端漭漭书巴水，枕上巉巉梦小峨。","诗有馀师禅有友，前希李白后东坡。"]},{"t":"和陆放翁初春遣兴","f":"七言律诗","c":["疏散庸庸寄一官，匡床趺坐觉身安。","聊将古道酬宾客，免把閒思累肾肝。","萤火几时能脱腐，醯鸡无日得离酸。","东风已放西门柳，冻水冰条亦解欢。"]},{"t":"游高梁桥","f":"七言律诗","c":["花时晴色酿芳原，出郭犹如出槛猿。","雾质风梢新柳缕，皴皮瘦骨老藤根。","红云尾变知鱼热，碧缬纹繁觉水温。","耳听碧流心翠岭，閒谈恰已到山门。"]},{"t":"暮春同谢生汪生小修游北城临水诸寺至德胜桥水轩待月 其一","f":"七言律诗","c":["一曲池台半畹花，远山如髻隔层纱。","南人作客多亲水，北地无春不苦沙。","熟马惯行溪柳路，山僧解点密云茶。","满川澄月千条缕，踏踏苍波过几家。"]},{"t":"和韵赠黄平倩","f":"七言律诗","c":["逍遥未必是无官，割累忘情梦也安。","入室祗容金相好，伴身唯有铁肠肝。","蓬莱监里真先辈，冠带场中老细酸。","一帙雒摩三斗酒，孤灯寒雨亦欢欢。"]},{"t":"即事和韵","f":"七言律诗","c":["柳下何曾耐小官，青毡缘简且偷安。","空窗净阁销尘眼，时草新花养病肝。","庙市客来询古字，粮船僧至饷吴酸。","密函怪牒閒搜取，钞得仙方寄所欢。"]},{"t":"送顾升伯出使还吴 其一","f":"七言律诗","c":["四月西山雨过时，箫吹阑道沸旌旗。","痛怜知己他乡别，懒作诸王奉使诗。","绕驿青芦呼水鹳，渡江白笋荐冰鲥。","雕窗画舸堂堂去，间解花嫦首小儿。"]},{"t":"送顾升伯出使还吴 其二","f":"七言律诗","c":["青峦生色水生波，处处吴姬饷酒醝。","震泽有山皆树橘，虎丘无月不听歌。","潮田没去春畦少，侬语讹时怪事多。","近日押徵知不免，阊门风景看如何。"]},{"t":"送夹山舅令太原 其一","f":"七言律诗","c":["踏尽层岩见稔畬，烟峦鸡犬若仙家。","公亭客过开生酿，石室僧来判种花。","竹下簿书閒草偈，山中人使学烹砂。","高槐影静莎庭里，香散屏空放早衙。"]},{"t":"送夹山舅令太原 其二","f":"七言律诗","c":["閒将公事了尊罍，郭外青山探几回。","从事也因流水出，长官多为踏花来。","印文长日封苍藓，簿筴经年长蠹灰。","身是嘉祥旧令尹，东西历尽始知才。"]},{"t":"送黄贞父令进贤","f":"七言律诗","c":["撇却孤山旧葛巾，暂时朱紫缚閒身。","高才正不须违俗，七尺何妨也拜人。","花里课书分小吏，山中留偈谢高真。","直将收斗西湖水，一洗南州案牍尘。"]},{"t":"丘长孺自塞上来","f":"七言律诗","c":["百钱买得梨花春，洗却并州面上尘。","万里质田无售主，一生知己是贫人。","扶摇不肯吹飞絮，尺水如何继巨鳞。","醉起弯弓犹一石，清时羁绁老麒麟。"]},{"t":"雨中坐方平弟旃檀馆即事","f":"七言律诗","c":["柏屏藤格径森疏，阑外蔬畦十亩馀。","坐客始闻烹水法，高人时有乞花书。","瓶中熟结香尤老，雨后山茶韵不如。","本欲死心无可死，烂红堆里话清虚。"]},{"t":"伯学斋中话旧感赋","f":"七言律诗","c":["相逢各自叹秋姿，长忆春郊走马时。","细竹也来成老节，稚松何意见霜皮。","眼中几度消寒水，鬓脚公然长秃髭。","十五盛年看又过，不知难是蜡梅枝。"]},{"t":"别程彦之归吴","f":"七言律诗","c":["无成何用出昭关，眼底浓华阅几般。","陆品携来寻白水，谢家将去入名山。","缁寮乞作分桃忏，练帢羞归掷果湾。","七十二峰青朵朵，岚光只在屋楣间。"]},{"t":"梦中得诗醒记中二联足成之","f":"七言律诗","c":["散发长吟縠水边，吹烟唾月小游仙。","也知紫阁双扉梦，不破青溪半枕眠。","避客偶然抛竹屦，邀僧埘一上花船。","无心更著红衫去，学得寒灰苦未禅。"]},{"t":"赤壁怀子瞻","f":"七言律诗","c":["夜深清拍袅杨枝，惊起澄江白鹭鸶。","过客争浇赤壁酒，几人曾和雪堂诗。","山民自种元修菜，石榻刚存乳母碑。","见欲铸金范老子，柳浪湖上拜新祠。"]},{"t":"寒香","f":"七言律诗","c":["寒香寞寞上屏纱，活火烹泉石碾茶。","溪翠柳烟争压叠，雪条风干五攲斜。","旋开曲社通莲社，痛饮南家又北家。","禅榻归来清似洗，醉看红燄吐膏花。"]},{"t":"无念同余迎先伯修赋此为别","f":"七言律诗","c":["痰石如何比老颜，才留筋骨在人间。","一舟破衲慈明哭，几叶寒帆学士还。","病久思归黄柏岭，衰来梦上戒坛山。","江西湖北频来往，学得心閒似水閒。"]},{"t":"寄黄谕德平倩兼申玉泉之约","f":"七言律诗","c":["宦情拟上武牙滩，世味真吞栗棘丸。","腕上千珠胡语熟，秋来一影射堂寒。","面慈每觉违心易，肌疥当思忍痒难。","枵木如庵茶似掌，蓝堆山色倩谁看。"]},{"t":"初正偶题","f":"七言律诗","c":["惯懒无心更出关，清时梦亦趁人閒。","几回寺里寻花去，独自江头看水还。","处世渐同栗里子，全家拟注玉泉山。","千溪万碧何由见，只是苍枝也破颜。"]},{"t":"久不到沙市矣感赋","f":"七言律诗","c":["斑发今来是老成，缁衣聊复大堤行。","见僧每忆年多少，观水因悲物变更。","率尔扣门常误姓，偶然题壁不书名。","章台寺里曾游处，古棘丛篁绕地生。"]},{"t":"示度门","f":"七言律诗","c":["北平曾记写疏时，黄帕亲封下赤墀。","三十四年薄宦客，一千七众讲经师。","蓝堆山续开皇诏，仙掌茶抽谷雨旗。","鬼斧神工仍七日，直教重勒玉泉碑。"]},{"t":"放言效白 其一","f":"七言律诗","c":["掉头谁拟作公卿，只合林间树下行。","臧是谷非凭耳迥，元轻白俗任诗成。","有身秪作他人看，无事休将造物争。","夜踏芒鞋深雪里，自呼东郭冷先生。"]},{"t":"放言效白 其五","f":"七言律诗","c":["抺却浓岚作羽衫，抚松终日坐枯岩。","盗悲老氏折衡斗，马谢庄生祱辔衔。","青凤下来传古字，白云飞去护仙缄。","芝田数亩那耕得，收拾山中木柄欃。"]},{"t":"卷中见亡友王官谷姓字感赋 其一","f":"七言律诗","c":["残墨犹香落姓名，孤缸清夜泪充横。","公然墨发人将去，毕竟青山约未成。","心事如冰见底里，交游于我快平生。","柳浪湖上深更月，料得诗魂近水行。"]},{"t":"卷中见亡友王官谷姓字感赋 其二","f":"七言律诗","c":["云霞拟置别堂春，其奈些儿露水身。","碧柳典来求古佛，青鬟嫁去事高真。","一生书画皆偿债，数亩琅玕也卖人。","湖石迤南栀子北，哭君此地最伤神。"]},{"t":"苦雪戏作","f":"七言律诗","c":["十日不曾开木扉，弓风苦欲弄残威。","辜他媚媚明明节，只作团团絮絮飞。","琴客己闻将鹤煮，诗翁又诉打花稀。","山人欲取画中意，故著红衫戴笠归。"]},{"t":"新买得画舫将以为庵因作舟居诗 其一","f":"七言律诗","c":["拟将船舫作庵居，载月凭风信所如。","鱼鸟教他为侍史，云烟呼我作尚书。","居如老蠹身藏木，行似蜗牛首戴庐。","下无卓锥上片瓦，致身今口在空虚。"]},{"t":"新买得画舫将以为庵因作舟居诗 其二","f":"七言律诗","c":["囊中随意贮青蚨，歌吹虽喧不可无。","隐逸也须添故事，江山真合点狂夫。","随身恰似天宫殿，寓目皆披水画图。","甲子不须颁凤历，但看莲发与莲枯。"]},{"t":"新买得画舫将以为庵因作舟居诗 其三","f":"七言律诗","c":["五湖不是学玄真，且喜素衣不上尘。","家移碧缬绫中任，身是屏风画里人。","闲追船子咨行脚，老倩中峰作近邻。","一衲蒙头万事已，无怀民与葛天民。"]},{"t":"新买得画舫将以为庵因作舟居诗 其四","f":"七言律诗","c":["鸥邻鱼社作新知，才唱杨枝又竹枝。","风打白蘋来夏口，雨深斑竹过湘祠。","不愁入目山无态，只怕磨心景要诗。","唤作朱公些子似，当窗祗是欠西施。"]},{"t":"新买得画舫将以为庵因作舟居诗 其五","f":"七言律诗","c":["峰峦曲折水湾环，时与游僧作往还。","暂为书碑来禹庙，才因买橘上包山。","心关网密聊成叹，梦被云牵偶不闲。","慎勿誇张竿水过，惹他桑孔算鱼蛮。"]},{"t":"新买得画舫将以为庵因作舟居诗 其六","f":"七言律诗","c":["丝烟丝雨润江湄，又到花娇鸟嫩时。","杜宇一身皆口颊，垂杨通体是腰肢。","閒观水态思吴壁，暗记方言證楚辞。","鸂鶒太文凫太野，就中洁白是银鸶。"]},{"t":"新买得画舫将以为庵因作舟居诗 其七","f":"七言律诗","c":["更无他物作遮阑，但得心忘梦亦安。","渭水一竿犹有待，严滩百尺也无端。","鱼龙直作鸡豚狎，荇藻却如蔓棘看。","莫把古人来比我，同床各梦不相干。"]},{"t":"新买得画舫将以为庵因作舟居诗 其八","f":"七言律诗","c":["舟居元不即田功，稍与农家节令同。","纵小也妨月额雨，虽暄不用卯头风。","才闻摊税征渔户，又说抽丁报老翁。","每被山民来借问，今年湖比几都丰。"]},{"t":"新买得画舫将以为庵因作舟居诗 其九","f":"七言律诗","c":["全家相次入烟云，老鹤稚鸥共一群。","便与青山坚作誓，免劳白水更移文。","澄江夜月连天泛，古涧寒声彻岁闻。","欲把姓名通远峤，函书先达武夷君。"]},{"t":"新买得画舫将以为庵因作舟居诗 其十","f":"七言律诗","c":["聊将幽思托芳菲，閒月閒花总息机。","青草盖蹄黄犊喜，白波点尾翠禽飞。","江篱不作牢骚咏，神女全抛艳粉衣。","纵有志和难比我，我能容得鳜鱼肥。"]},{"t":"期苏潜夫游玉泉竟月不至及至而余复以大人病疮归于其行也诗以讯之","f":"七言律诗","c":["江程才隔一牛鸣，人事参差奈此行。","枉把青山来作梦，孤他白石上题名。","花间废巷查遗迹，雪后崩崖战水声。","到日天台应寄讯，讲堂久矣待袁生。"]},{"t":"花朝和坡公韵","f":"七言律诗","c":["丝丝新柳飏堤门，早晚南村又北村。","风信煖寒观树色，药苗深浅记竿痕。","行来渐觉姑绒重，静里频将奼火温。","是物逢春皆作语，子规未必是啼魂。"]},{"t":"是日新晴","f":"七言律诗","c":["一泓幽碧照篱门，偶为题名过远村。","愁去东风消冻液，喜来春草迸苔痕。","莺花又作新情看，山水间将旧谱温。","东野浪仙谁在者，苦吟清句当招魂。"]},{"t":"述旧西山下有门头村多精蓝","f":"七言律诗","c":["探春犹记出青门，先问门头第几村。","近水只观娥散影，匝堤唯见酒淋痕。","花时乞假朝参少，醉后联鞭笑语温。","是日把杯人已往，雏莺新柳也伤魂。"]},{"t":"习池道中","f":"七言律诗","c":["深岩寂寂石花斑，完却尘沙车马颜。","是客竞来尝白水，几人休去伴青山。","云泉到眼无多热，金紫蒙头第一关。","三尺磨崖书大字，人生到此是清间。"]},{"t":"七真洞赠道者","f":"七言律诗","c":["云烟回合蔽仙关，万仞斜通一发山。","事往已迷新甲子，洞深忘却旧人间。","橘皮鹤下遗雏去，萼绿花来采药还。","白日饵将三五斗，方瞳如水照丹颜。"]},{"t":"长生岩逢休粮道者","f":"七言律诗","c":["只将空榻伴嶙峋，踏遍桃花涧底春。","一口也摈为长物，诸缘皆可作飞尘。","施来白粲都饲鹤，种得黄精每寄人。","留却石炉烟少许，深山遥夜礼高真。"]},{"t":"秋日柳浪馆雨中王以明刘绳之见过","f":"七言律诗","c":["西风索莫午烟迟，一万垂杨袅袅丝。","梦里也随僧入社，间中多以颂为诗。","游鳞翕处常分藻，惰羽栖时不论枝。","沙碧水清云潋潋，禾花将绽藕花衰。"]},{"t":"馆中再用前字寄王以明","f":"七言律诗","c":["閒丹閒碧长秋思，水榭风轩分外宜。","老衲寄书离岳久，田家留语赴斋迟。","枫堤壮枕西湖庙，瀼水斜通濯足池。","免使韩公嗤粪壤，园亭是处有新诗。"]},{"t":"藕塘","f":"七言律诗","c":["藕塘风起散花鳞，踏遍溪桥不上尘。","饥鹤偶来添半口，浮云忽破现分身。","每嫌蕉叶遮帘子，为触番书置净巾。","自起浇莎汰白石，清閒赖是不如人。"]},{"t":"山居","f":"七言律诗","c":["山居只索任天真，无作无营自在身。","青叶髻呼雏弟子，白莲湖老惰耕人。","偶逢上座学观骨，免与东方难腐唇。","一笑蒙城门下土，几归沧海几飞尘。"]},{"t":"九日偕诸弟及僧泛舟至和尚桥","f":"七言律诗","c":["芦花风起雪平川，数亩荒洲倚废莲。","小榜乍依沙子岸，惊禽忽破水条烟。","閒移竹影莓苔地，坐爱溪文荇藻天。","且与鹭鸥相伴著，平分僧月载归船。"]},{"t":"玉泉寺","f":"七言律诗","c":["蓝堆翠扑几千年，银浦何人也覆船。","龙伯徙来方辟地，蚕丛缘此遂登天。","红霞抺额将军拜，白石横烟幼妇眠。","閒与故人池上语，摘将仙掌试清泉。"]},{"t":"哭夹山先生时先伯修归窆","f":"七言律诗","c":["河阳三度放花春，毕竟抛他凫舄身。","左手直教持老子，空闺断不哭佳人。","苔深旧灶丹池冷，胞发金台白朵新。","泪眼一丝能几许，那堪分洒两家尘。"]},{"t":"余蔬食三年矣偶因口馋遂复动荤辄尔有作用呈诸衲不独解嘲兼亦志愧云尔","f":"七言律诗","c":["爱持空钵嚼花寒，白水青盐也自安。","山色每呼棕笠去，月光只付橘皮看。","偶逢白社新开酿，又学山公倒著冠。","珍重晚年赵阅道，略将鲊脯间蔬盘。"]},{"t":"旧太守徐滨岳观察岳阳偶道敝邑诗以送之","f":"七言律诗","c":["江风滟滟绿条丝，父老争来拜戟支。","门外熊轓攀处子，掌中貂虎弄婴儿。","肝肠似月冰皆彻，惠泽如春草不知。","一片酒香湖上石，摩苔重写洞庭碑。"]},{"t":"代送徐观察","f":"七言律诗","c":["章台春嫩碧芽肥，又见阳和使者归。","南纪霜崖留政迹，洞庭波月澹容辉。","弱萝有寄千寻直，狐鹗乘吹万里飞。","三载少林门下士，谬持空钵乞传衣。"]},{"t":"和萃芳馆主人鲁印山韵 其一","f":"七言律诗","c":["乍雨乍烟作艳阳，高斋几度角杯觞。","偶逢竹冷溪幽处，只觉山心水味长。","松下压槽经月醉，花间弹局一枰香。","主人恰似玄真子，细雨斜风载满航。"]},{"t":"和萃芳馆主人鲁印山韵 其三","f":"七言律诗","c":["萝石森疏倚夕阳，主人投辖客传觞。","天高未觉鹏营旷，松老方知鹤梦长。","山雨山烟浓淡著，溪红溪碧浅深香。","醉来一觉云门路，藤枕桃笙泛越航。"]},{"t":"和萃芳馆主人鲁印山韵 其四","f":"七言律诗","c":["几回傍槛折迷阳，流尽春槽曲水觞。","竹邑浅分溪浪滑，花枝斜照夜鬟长。","清言屡射当场覆，艳语频勾隔坐香。","皂帽青鞋从此始，敢将瓢笠附轻航。"]},{"t":"和萃芳馆主人鲁印山韵 其五","f":"七言律诗","c":["几番对酒惜颓阳，聊为飞英送一觞。","竹里葵蔬尼客久，山中甲乙倍人长。","仙畦屡溉新分药，道被犹薰旧赐香。","上马揖来无别语，米家曾乞载书航。"]},{"t":"柳浪偕诸客偶题时午节将至","f":"七言律诗","c":["榴花历历烂青枝，又到分丝剪艾时。","布谷语乾辞社老，寒皋舌长畏童儿。","酒人每自欺新户，骚客频来竞险诗。","花路柳关闲不启，免将肉面照清池。"]},{"t":"题澧州沈大夫加恩册","f":"七言律诗","c":["碧水青崖恋主人，呼他鱼鸟作齐民。","山中不问栽兰户，庭外长留驾鹤宾。","官舍有时唯洗石，印床无事只生尘。","渚宫巴国争传语，看取天花翚锦新。"]},{"t":"谢鲁印山惠舟兼荅来什","f":"七言律诗","c":["白鹄飞来油口滨，尺书衔得自脩鳞。","凭将贮月笼烟水，泛我轻云冷石身。","濯足且呼回道士，浣花先约杜诗人。","鉴湖一曲幽如许，贺老终当作近邻。"]},{"t":"书尾以济川见期非所望也因述鄙怀以报","f":"七言律诗","c":["巨川舟楫竟如何，不那湖湘烟水多。","荇藻自然生远沚，凫鸥终是乐清波。","环池匝木仲长统，细雨斜风张志和。","白日黄鸡底相恼，玲珑争不为君歌。"]},{"t":"湖亭对月述怀同散木赋","f":"七言律诗","c":["竹气荷烟冷不分，石泉汨汨夜深闻。","每随流去呼杯子，但觉风来扫树纹。","百亩池台唯贮月，一家生事只依云。","废庵枵木频栖止，渐喜从鸥不乱群。"]},{"t":"中秋对月同散木作","f":"七言律诗","c":["百年看月几回盈，那得中秋度度明。","纵使清光常满满，若无胜地也平平。","朱栏碧榭垂千亩，白水青霞过一生。","醒即抱鎗眠即枕，腮毛渐渐有霜茎。"]},{"t":"偶成","f":"七言律诗","c":["自将白水照衰颜，也合长林丰草间。","便欲易名辞故国，只愁借姓与青山。","溪边酌月倾高户，花下题诗嫁小蛮。","海错一筐书半纸，门僧新自渐东还。"]},{"t":"寄小修","f":"七言律诗","c":["乡园是处有花芳，不敌深山老萼香。","十载交游填上国，一朝文字榜都堂。","玉因刖足多酬价，砂到飞身始验方。","社曲城南饶古寺，休将名姓语支郎。"]},{"t":"山中旧斋","f":"七言律诗","c":["山禽漠漠堕霜翎，户外长搜老茯苓。","蒲柳根中抽夏笋，桃花枝上寄冬青。","竹蜂入壁垂千穴，夭棘萦丝满一庭。","犹有数行残粉字，古槐西角旧传经。"]},{"t":"荅鲁印山见贺新居之作","f":"七言律诗","c":["东亭故宅昔曾过，旋著新花剪旧莎。","帘远颇宜低度曲，门宽兼得大张罗。","鸠巢唤妇真成拙，瓜屋随身也觉多。","试问柳浪湖上柳，几回秋草几春波。"]},{"t":"癸卯初度筵中示社友及两弟","f":"七言律诗","c":["抛他银绶去躬耕，半踏乡村半市城。","竹大许年成老友，梅开是度作同庚。","但凭髭发称前辈，转觉聪明畏后生。","紫凤檀槽香拍板，听来都肖水泉声。"]},{"t":"集五弟春草堂","f":"七言律诗","c":["草堂红碧尽离离，轻热轻寒正好时。","种药且收曾效子，修花惟去最低枝。","窗间番舌听言鸟，堤外风鸢看小儿。","欲与少陵添故事，入春新作海棠诗。"]},{"t":"浣溪庄落成同社中诸友赋 其一","f":"七言律诗","c":["一湾澄碧一丝缗，洗却平泉草木尘。","溪上唱歌随孺子，楼头作客尽仙人。","鵁鶄带月移西瀼，蛱蝶分花过北邻。","白石青山从此始，不将簪带恼居民。"]},{"t":"浣溪庄落成同社中诸友赋 其二","f":"七言律诗","c":["溪光桃燄煖纷纷，渐远喧嚣渐不闻。","阶下每流无械水，窗间时有不归云。","糟坛屡建三章约，花社新颁凡锡文。","一曲垂杨十里板，醉中偏倚石榴裙。"]},{"t":"赋得溪上落花","f":"七言律诗","c":["碧溪香重水鳞鳞，飘雪回风舞最新。","欲止又飞如照影，乍开忽乱似分身。","愁深孝女江头月，梦逐陈王枕里人。","欲把遗芳付仙子，任他杨柳六街尘。"]},{"t":"余友黄鹄生与所䁥相去二舍为置符以召各藏其半题曰花信风社中雅其事作诗咏之 其一","f":"七言律诗","c":["割得铜符与小蛮，一回和著一开颜。","香封字字花题驿，锦骑程程月作关。","云里快呼王母使，雪中愁上藁砧山。","刘郎谩恨仙途远，流水桃源咫尺间。"]},{"t":"余友黄鹄生与所䁥相去二舍为置符以召各藏其半题曰花信风社中雅其事作诗咏之 其二","f":"七言律诗","c":["蕊珠新节出仙官，使雨召云也不难。","沚壁车中呼小小，善和坊里取端端。","江头作押逢青鲤，花下移文付彩鸾。","纵使黄河如带水，双筠依旧碧琅玕。"]},{"t":"雨中集龚名世平远楼","f":"七言律诗","c":["江干丝雨洗残春，瘦朵浓条取次新。","桐叶烟中遮去艇，麦苗风里数行人。","钟彝屡辨商周识，绢帖閒翻晋宋尘。","碧草青畦烦指点，尚书高垒卧麒麟。"]},{"t":"四弟旃檀馆即事","f":"七言律诗","c":["淙淙石脉溜春渠，长日关门扫地居。","莲叶漏中兵研汁，木香花底读方书。","丛筠傍屋多臧鸟，小市通江易得鱼。","洗墨焚香幽事了，庭莎增草佞浇锄。"]},{"t":"和散木韵 其一","f":"七言律诗","c":["暖风吹雨溉花畦，荣辱何劳问木鸡。","窗下止容三亩月，门前亲著一丸泥。","功名且自轮诸弟，家政都将付老妻。","碧水丹崖身自领，黄柑斗酒伴莺啼。"]},{"t":"和散木韵 其二","f":"七言律诗","c":["废垣耘得作春畦，幽客时来载黍鸡。","蜀葛细裁三尺雪，吴瓶远饷一封泥。","全家遏末封胡弟，半百高柔莱子妻。","蔬水虽贫聊自解，幸无饥苦使儿啼。"]},{"t":"集子静水明楼听歌仍和散木韵","f":"七言律诗","c":["百亩春兰盖碧畦，玲龙且莫唱黄鸡。","青丝屡罥鸳纹水，红袖频麾燕嘴泥。","岘石坡前山简客，天花场上净名妻。","千枝万朵黄家去，听取娇莺恰恰啼。"]},{"t":"散木方鳏誓不娶诗以嘲之仍用前韵","f":"七言律诗","c":["汉阴无侣灌蔬畦，枯枕寒缸坐晓鸡。","未许少汤能沃雪，也知狂絮不粘泥。","家凫自伴龟家语，野雉聊为牧儥妻。","割袖分桃听忏悔，辟将黄叶止儿啼。"]},{"t":"偶成示卫道人用前韵","f":"七言律诗","c":["丹垆成砌药成畦，枉把刀圭事犬鸡。","料得此身虽暂毁，辟如土偶乍漂泥。","寒山宛尔称兄弟，庞叟随缘示女妻。","未转枕来残梦了，晨光又动晓鸡啼。"]},{"t":"竹香 其一","f":"七言律诗","c":["噀雨拖烟湿几丛，空阶十亩月玲珑。","但凭一抺高寒气，洗尽千稍艳粉风。","深院鹤醒人去后，孤云僧老鼻观中。","松花柏子差相得，才有微芬也不同。"]},{"t":"竹香 其二","f":"七言律诗","c":["削尽秾华是此君，碧栏银沼醉氤氲。","全凭出格幽微韵，体出无声大古文。","定里只消风引月，梦来唯觉水依云。","袜材写尽湖州派，清冷知他闻不闻。"]},{"t":"喜小修至自燕","f":"古风","c":["蓝衫脱却乍归乡，心了无官也不妨。","客过试开陈白酿，病馀聊服地黄汤。","谩追舌底新朝事，且觅山中旧睡方。","?取大觥与长管，一齐阑入少年场。"]}]};